window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-cirurgia-med-cir-06"]={"block":"med:med-cirurgia-med-cir-06","label":"MED · MED CIR 06","count":386,"questions":[{"id":"med-cirurgia-med-cir-06-345474","number":"345474","sourceNumber":"345474","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Com relação ao câncer de pâncreas, é CORRETO afirmar que:","options":{"A":"A Icterícia obstrutiva ocorre precocemente quando o câncer é localizado na cauda do pâncreas.","B":"O tabagismo é o principal fator de risco ambiental para o desenvolvimento do câncer de\npâncreas.","C":"A tomografia computadorizada do abdome é o melhor método de imagem para rastreamento do\ncâncer de pâncreas.","D":"Todos os pacientes com mais de 60 anos de idade dever ser submetidos ao rastreamento do\ncâncer de pâncreas."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-343825","number":"343825","sourceNumber":"343825","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Mulher de 30 anos, chaga ao seu ambulatório com queixa de dor inespecífica no\nhipocôndrio esquerdo e epigástrio. Conta que realizou tomografia de abdome por conta própria e\nficou assustada ao ler o laudo. Laudo: massa na cauda do pâncreas, bem delimitada, com\ncontornos regulares, cápsula espessa, heterogênea, de padrão misto, sólido cístico, com\ncalcificações internas, medindo cerca de 4 cm. Qual a principal hipótese diagnóstica?","options":{"A":"Pseudocisto pancreático.","B":"Neoplasia cística mucinosa do pâncreas.","C":"Tumor de Frantz.","D":"Neoplasia intraductal mucinosa pancreática."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-345509","number":"345509","sourceNumber":"345509","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente masculino, 65 anos, em acompanhamento ambulatorial de hepatite por vírus\nC, vem à consulta de rotina com quadro de dor\nabdominal, plenitude pós-prandial e anorexia.\n\nRealiza ultrassonografia de abdome que demonstra lesão hipoecóica com cerca de 3 cm de\ndiâmetro, com aspecto em mosaico. Assinale o diagnóstico mais provável:","options":{"A":"Metástase de tumor de próstata.","B":"Hepatocarcinoma primário.","C":"Adenoma hepatocelular.","D":"Hemangioma hepático."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-345512","number":"345512","sourceNumber":"345512","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Assinale a alternativa que corresponde ao fator de risco mais forte para\ndesenvolvimento do hepatocarcinoma:","options":{"A":"Etilismo.","B":"Infecção pelo vírus da hepatite C.","C":"Ingestão de aflatoxinas.","D":"HbeAg do vírus da hepatite B positivo."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-343847","number":"343847","sourceNumber":"343847","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"A Síndrome de Peutz-Jeghers é caracterizada pela presença de pólipos\nHamartomatosos pelo trato gastrointestinal\nassociado a manchas escurecidas na mucosa dos\nlábios, cavidade oral e pele. Sobre ela é CORRETO dizer que:","options":{"A":"É Autossômica dominante.","B":"É Autossômica recessiva.","C":"Não apresenta relação com incidência de neoplasias sólidas.","D":"O diagnóstico é clínico com a determinação das lesões, tendo em vista ausência de teste\ncomplementar específico."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-283270","number":"283270","sourceNumber":"283270","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 69 anos, tabagista, comparece no consultório com queixa de astenia e\nprostração, refere ainda períodos de constipação intestinal com episódios alternados de diarreia.\nAo exame físico não se encontram grandes alterações. Em relação à conduta imediata assinale\nalternativa CORRETA.","options":{"A":"Solicitar tomografia abdominal.","B":"Solicitar ressonância magnética abdominal.","C":"Solicitar colonoscopia.","D":"Solicitar pesquisa de sangue oculto nas fezes."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-291775","number":"291775","sourceNumber":"291775","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente, sexo feminino, 45 anos de idade, é encaminhada ao ambulatório de cirurgia\npor apresentar nódulo palpável em região cervical\nanterior. A paciente nega comorbidades ou uso\nde medicações. Ao exame, bom estado geral, presença de nódulo palpável na topografia da\nglândula tireoide, medindo cerca de 1,2cm no maior diâmetro. Foi realizada uma ultrassonografia\nda região cervical. Indique a principal suspeita diagnóstica para o nódulo cervical.","options":{"A":"Metástase linfonodal.","B":"Carcinoma papilífero de tireoide.","C":"Cisto tireoidiano.","D":"Lipoma de subcutâneo."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-291776","number":"291776","sourceNumber":"291776","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente, sexo feminino, 45 anos de idade, é encaminhada ao ambulatório de cirurgia\npor apresentar nódulo palpável em região cervical\nanterior. A paciente nega comorbidades ou uso\nde medicações. Ao exame, bom estado geral, presença de nódulo palpável na topografia da\nglândula tireoide, medindo cerca de 1,2cm no maior diâmetro. Foi realizada uma ultrassonografia\nda região cervical. Determine a conduta mais adequada para confirmar o diagnóstico.","options":{"A":"Realizar tomografia computadorizada de cabeça, pescoço e tórax.","B":"Orientar a paciente que se trata de doença benigna e que não há necessidade de outro exame\ncomplementar.","C":"Realizar punção aspirativa, com agulha fina, do nódulo.","D":"Indicar exérese do nódulo."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-281113","number":"281113","sourceNumber":"281113","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 28 anos do sexo feminino procura o consultório para avaliação de rotina.\nAo exame físico foi observado nódulo de\ntireoide confirmado por ultrassonografia, sólido, de 1,1 cm.\nVocê solicitou exames de função tireoidiana que demonstraram TSH reduzido e T4 livre normal.\n\nNeste caso, a conduta adequada em relação ao nódulo é:","options":{"A":"Monitoramento com ultrassonografia.","B":"Punção aspirativa por agulha fina.","C":"Tratamento com iodo radioativo.","D":"Cintilografia da tireoide.","E":"Tireoidectomia."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-281117","number":"281117","sourceNumber":"281117","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Homem de 55 anos, tabagista ativo de 40 anos x maço. Como deve ser realizado o\nrastreamento para cancer de pulmão?","options":{"A":"TC de tórax a cada 2 anos.","B":"Rx de tórax anualmente.","C":"TC de tórax anualmente.","D":"Rx de tórax semestralmente.","E":"TC de tórax a cada 3 anos."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-283309","number":"283309","sourceNumber":"283309","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Mulher de 30 anos chega ao seu ambulatório com queixa de dor inespecífica no\nhipocôndrio esquerdo e epigástrio. Conta que realizou tomografia de abdome por conta própria e\nficou assustada ao ler o laudo. Laudo: massa na cauda do pâncreas, bem delimitada, com\ncontornos regulares, cápsula espessa, heterogênea, de padrão misto, sólido cístico, com\ncalcificações internas, medindo cerca de 4 cm. Qual a principal hipótese diagnóstica?","options":{"A":"Pseudocisto pancreático.","B":"Neoplasia cística mucinosa do pâncreas.","C":"Tumor de Frantz.","D":"Neoplasia intraductal mucinosa pancreática."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-283310","number":"283310","sourceNumber":"283310","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente sexo feminino, 28 anos, multípara, em uso de anticoncepcional oral há 5 anos,\ndurante exame ultrassonográfico de rotina foi evidenciado nódulo de 5,5 cm no segmento VI do\nfígado de aspecto exofítico. As sorologias para hepatites virais foram negativas. A ressonância\nmagnética com contraste hepato-específico fez o diagnóstico de adenoma hepatocelular. Qual a\nsua conduta?","options":{"A":"Suspender anticoncepcional oral e controle com 3 meses.","B":"Realizar biópsia percutânea para confirmação diagnóstica.","C":"Indicar cirurgia para ressecção.","D":"Indicar ablação por radiofrequência."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-283327","number":"283327","sourceNumber":"283327","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 37 anos, sexo feminino, apresenta EDA com lesão ulcerada em incisura\nangularis do estômago com 1 cm, anatomopatológico confirma adenocarcinoma gástrico GII tipo\nintestinal, qual a melhor conduta cirúrgica para esse caso?","options":{"A":"Gastrectomia parcial com linfadenectomia D1.","B":"Gastrectomia parcial com linfadenectomia D2.","C":"Gastrectomia total com linfadenectomia D1.","D":"Gastrectomia total com linfadenectomia D2."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-281159","number":"281159","sourceNumber":"281159","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Assinale a alternativa que apresenta o tumor hepático benigno mais comum.","options":{"A":"Adenoma.","B":"Hiperplasia nodular focal.","C":"Hemangioma.","D":"Nódulos macrorregenerativos.","E":"Hamartomas."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-281171","number":"281171","sourceNumber":"281171","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 67 anos realiza endoscopia digestiva alta para investigação de anemia que\ndemonstra lesão vegetante em antro gástrico. A biópsia evidencia adenocarcinoma. Assinale a\nalternativa que contenha a variante de acordo com a classificação de Lauren e o provável fator\ncausal desta lesão.","options":{"A":"Tipo difuso ? infecção por H. pylori.","B":"Tipo difuso ? mutação do gene p53.","C":"Tipo Intestinal ? infecção por H. pylori.","D":"Tipo difuso ? consumo elevado de nitratos.","E":"Tipo Intestinal ? consumo de vegetais crus."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-247141","number":"247141","sourceNumber":"247141","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente com 64 anos de idade, tabagista 80anos-maç, foi diagnosticado com nódulo\npulmonar de 2cm em exame radiológico de rotina. Realizou broncoscopia com biópsia que mostrou\nausência de malignidade. A conduta neste momento deve ser:","options":{"A":"Estadiamento.","B":"Alta ambulatorial.","C":"Tomografia de tórax a cada 6 meses.","D":"Biópsia a céu aberto.","E":"Acompanhamento com radiografia trimestral."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-247168","number":"247168","sourceNumber":"247168","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente do sexo masculino, 66 anos, tabagista, é internado por hemorragia digestiva\nalta (HDA). Nega comorbidades e refere uso de\nremédio para cefaleia com certa frequência nas\núltimas semanas. O paciente evolui bem no seu terceiro dia de internação, sem novas\nexteriorizações e você pensa em programar a alta. O controle diário de hemoglobina desde a\nadmissão é: maior do corpo gástrico, 1,5 cm, bordas irregulares, com depósito de fibrina. Com\nrelação ao diagnóstico e à conduta para este paciente, assinale a alternativa CORRETA.","options":{"A":"HDA por úlcera gástrica de aspecto péptico. Alta hospitalar com inibidor de bomba de prótons\nVO por duas semanas.","B":"HDA por úlcera gástrica suspeita de ser neoplásica. Manter internação com uso de omeprazol\nEV por sete dias.","C":"HDA por úlcera gástrica medicamentosa. Alta hospitalar com uso contínuo de omeprazol e EDA\nem seis meses.","D":"HDA por úlcera gástrica suspeita de ser neoplásica. Alta hospitalar com inibidor de bomba\nprotônica por quatro semanas e EDA após.","E":"HDA por úlcera gástrica de aspecto péptico. Manter internação com uso de omeprazol EV\nassociado ao tratamento do H. pylori por sete dias."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-247220","number":"247220","sourceNumber":"247220","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Assinale a alternativa que responde CORRETAMENTE à pergunta a seguir. Qual\ndoença está associada ao câncer gástrico em aproximadamente 10% dos casos?","options":{"A":"Síndrome do câncer colorretal não poliposo.","B":"Doença de Crohn.","C":"Colite isquêmica.","D":"Adenocarcinoma de apêndice cecal.","E":"Adenocarcinoma de sigmoide."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-251941","number":"251941","sourceNumber":"251941","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Pac. ?, 60 anos, submetido a Gastrectomia a BII e \"Y\" de Roux para tratamento de um\nadenocarcinoma gástrico. Qual a importância do \"Y\" de Roux nesse procedimento?","options":{"A":"Profilaxia da deficiência de Vit. B12.","B":"Profilaxia da S. de Dumping.","C":"Profilaxia da gastrite alcalina.","D":"Profilaxia da perda de peso pôs-gastrectomia."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-251946","number":"251946","sourceNumber":"251946","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente ?, 50 anos, portador de hepatite B, Child A, MELD 6, apresenta na tomografia\nde abdome com contraste dinâmico lesão\nhipervascular com washout precoce e diâmetro de 6,5 cm\nlocalizada em segmento III do fígado. A dosagem de alfa-feto-proteína foi de 1900 ng/ml. Qual a\nmelhor conduta?","options":{"A":"Indicar transplante hepático.","B":"Ablação por radiofrequência.","C":"Segmentectomia do segmento III.","D":"Alcoolização percutânea."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-251948","number":"251948","sourceNumber":"251948","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Nos tumores de reto baixo, como opções terapêuticas, exceto?","options":{"A":"Ablação por radiofrequência.","B":"Excisão trans-anal.","C":"Amputação abdomino-perineal do reto.","D":"Radioterapia e quimioterapia."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-217697","number":"217697","sourceNumber":"217697","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente de 67 anos de idade, com antecedente de tabagismo, hipertensão e\ndiabetes, refere que, há três semanas, vem\nnotando o rosto inchado e vermelho ao se levantar pela\nmanhã. Hoje cedo, foi auxiliar sua filha a carregar um pacote pesado e descreveu uma sensação\nde quase desmaio, que o motivou a procurar o pronto-socorro. No exame físico, apresentava PA de\n140 x 80 mmHg, FC de 74 bpm, FR de 21, SatO? de 92%, ingurgitamento venoso cervical e edema\ncraniofacial, além de edema discreto em MMSS. Não havia edema em MMII. Ausculta\ncardiopulmonar e exame abdominal sem alterações. O ECG mostrou ritmo sinusal e FC de 74, sem\nalterações patológicas do traçado. Nesse caso hipotético, o DIAGNÓSTICO PROVÁVEL é:","options":{"A":"Síncope cardiogênica.","B":"Síndrome da veia cava superior.","C":"Insuficiência cardíaca.","D":"Insuficiência renal aguda."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-217670","number":"217670","sourceNumber":"217670","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente, sexo feminino, 37 anos, refere história de diarreia com mais de 6 evacuações\nao dia, presença de sangue e muco, períodos\nde exacerbação e remitência, com evolução de um\nano. Há 3 meses, apresenta piora progressiva do quadro, associado a dor abdominal difusa, tipo\ncólica, urgência, tenesmo e perda ponderal de 13 kg neste período. Qual a conduta inicial no\nambulatório?","options":{"A":"Solicitar enema opaco.","B":"Realizar retossigmoidoscopia.","C":"Solicitar colonoscopia.","D":"Realizar toque retal."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-217677","number":"217677","sourceNumber":"217677","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente masculino, 68 anos, refere dor epigástrica há 9 meses e nos últimos 2 meses\ncom vômitos pós-prandiais precoces. Refere\nemagrecimento de 6 kg nesse período e ao exame\nfísico nota-se nódulo endurecido em fossa supraclavicular esquerda. Qual a hipótese diagnóstica?","options":{"A":"Tumor de Pancoast.","B":"Câncer de esôfago médio.","C":"Câncer gástrico.","D":"Câncer de cólon."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-217694","number":"217694","sourceNumber":"217694","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente do sexo masculino com 42 anos com história de nódulo tireoidiano visível à\nultrassonografia, medindo 1,5 cm, único, com microcalcificações, vascularização central maior que\nperiférica e halo incompleto. Qual é a melhor conduta?","options":{"A":"Tireoidectomia total.","B":"Observação e reposição de levotiroxina para supressão hormonal.","C":"Cintilografia de corpo inteiro com 131-iodo.","D":"PAAF e provas de função tireoidiana."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-183189","number":"183189","sourceNumber":"183189","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente adulta vem apresentando síndrome consuntivo e apresenta placas extensas\npapilomatosas hiperqueratósicas e hipercrômicas nas regiões intertriginosas. Suspeitando-se de\nmanifestação paraneoplásica, o tumor que mais frequentemente se associa a esse quadro é\nadenocarcinoma de:","options":{"A":"Pulmão.","B":"Estômago.","C":"Pâncreas.","D":"Cólon.","E":"Ovários."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-183186","number":"183186","sourceNumber":"183186","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Em relação ao câncer colorretal, assinale a alternativa INCORRETA:","options":{"A":"Aproximadamente, 1% a 3% dos carcinomas colorretais são relacionados às síndromes\npolipoides hereditárias, tais como. Polipose\nadenomatosa familiar, Síndrome de Gardner de Turcot.","B":"Não há evidências suficientes de que a dieta rica em gordura animal esteja relacionada com o\naumento da incidência de câncer colorretal.","C":"Mulheres com história pessoal de câncer de mama, endométrio e ovário têm maior probabilidade\nde desenvolver câncer colorretal que o restante da\npopulação normal.","D":"Aproximadamente, 10% dos indivíduos com câncer colorretal desenvolvem metástases\nperitoneais.","E":"Segundo a classificação TNM, pode-se dizer que um indivíduo com adenocarcinoma de colo que\natinge até a camada muscular e apresenta comprometimento linfonodal encontra-se em estágio III."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-182642","number":"182642","sourceNumber":"182642","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente feminino, 53 anos, apresentou queixas de plenitude pós-prandial e\ndesconforto abdominal há 2 meses, há 30 dias\napresenta icterícia e colúria. A ultrassonografia\ndemonstrou dilatação de vias biliares intra e extra-hepática, com vesícula biliar distendida,\nparedes\nespessadas, sem cálculos. Qual o exame com melhor poder diagnóstico?","options":{"A":"CPRE (Colangio-Pancreatografia Retrógrada Endoscópica).","B":"Colangiorressonância magnética com contraste.","C":"Tomografia computadorizada com contraste e cortes finos de pâncreas.","D":"Ecoendoscopia."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-182633","number":"182633","sourceNumber":"182633","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente masculino, 24 anos, foi submetido à PAAF em nódulo de 2 cm em lobo direito\nda tireoide. O resultado foi \"presença de\ncélulas foliculares\". Qual a conduta?","options":{"A":"Apena observação, provavelmente trata-se de um nódulo benigno.","B":"Indicar tireoidectomia, grande possibilidade de nódulo maligno.","C":"Solicitar cintilografia de tireoide.","D":"Realizar \"core biopsy\"."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-182612","number":"182612","sourceNumber":"182612","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente feminino, 37 anos, realizou exame de ultrassonografia de abdome total como\nparte de check-up de sua empresa, sendo evidenciado nódulo hiperecogênico de 4cm em\nsegmento hepático IVa. Foi realizado tomografia computadorizada de abdome que confirmou a\nlesão de 4cm no segmento referido, com impregnação tardia do contraste. Provavelmente trata-se\nde:","options":{"A":"Adenoma.","B":"Hiperplasia nodular focal.","C":"Hepatocarcinoma.","D":"Hemangioma."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-159103","number":"159103","sourceNumber":"159103","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Assinale a alternativa que, na avaliação de um nódulo tireóideo por USG, reúne\nrespectivamente três sinais sugestivos de uma lesão benigna (B) e três de maligna (M):","options":{"A":"(B) Limites regulares, halo irregular, microcalcificações / (M) áreas císticas, calcificações\ngrosseiras, hipervascularização.","B":"(B) Halo presente, hipoecogênico, calcificações em \"casca de ovo\" / (M) hiperecogênico,\nvascularização periférica e microcalcificação.","C":"(B) Hiperecogênico, microcalcificações, vascularização periférica / (M) halo irregular ou\nausente,\nhipoecogênico, sólido.","D":"(B) Hiperecogênico, calcificações em \"casca de ovo\", vascularização periférica / (M)\nhipoecogênico, microcalcificações, hipervascularização."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-159112","number":"159112","sourceNumber":"159112","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"A respeito das neoplasias malignas da glândula tireóide, podemos afirmar que:","options":{"A":"O carcinoma papilífero na criança, na maioria dos casos, é sintomático e se manifesta com\ndisfonia, disfagia ou massa cervical central, endurecida e fixa.","B":"O carcinoma papilífero na criança é uma doença rara, com disseminação linfonodal frequente e\ncom baixo índice de mortalidade.","C":"O diagnóstico citopatológico (PAAF) para variante de células altas do carcinoma folicular\nraramente é diagnóstico.","D":"Geralmente se manifestam ecograficamente como nódulos hiperecóicos e com acentuada\nvascularização central."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-159071","number":"159071","sourceNumber":"159071","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente masculino, 70 anos, apresentando massa palpável em HD, endurecida e\nmóvel com a respiração. O US de abdome\nrevelou uma lesão sólida de 4,0 x 5,0 em segmento V. A\ntomografia computadorizada de abdome confirma a presença da lesão, a qual apresenta wash-out\nna fase precoce. Qual a hipótese diagnóstica?","options":{"A":"Hepatocarcinoma.","B":"Hemangioma.","C":"Hiperplasia nodular focal.","D":"Nódulo de regeneração."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-135922","number":"135922","sourceNumber":"135922","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Homem com mais de 60 anos em consulta com urologista apresentava-se ao toque\nretal próstata de consistência adenomatosa,\nsuperfície lisa e contornos regulares de\naproximadamente 70 g. Ao ultrassom media 80 g com lobo mediano proeminente para dentro da\nbexiga que se mostrava trabeculada e com alguns divertículos. Qual a hipótese diagnóstica?","options":{"A":"Hiperplasia de próstata e prostatismo sem obstrução urinária baixa;","B":"Carcinoma de próstata com obstrução urinária baixa;","C":"Hiperplasia prostática sem obstrução urinária baixa;","D":"Hiperplasia de próstata com obstrução urinária baixa;"},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-108650","number":"108650","sourceNumber":"108650","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Qual a manifestação cutânea paraneoplásica está mais associada ao câncer gástrico?","options":{"A":"Acantose nigricans.","B":"Prurido.","C":"Pênfigo.","D":"Síndrome de Bazex."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-108664","number":"108664","sourceNumber":"108664","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Em relação ao câncer na infância, assinale a alternativa correta:","options":{"A":"Os tumores são muito mais raros que no adulto;","B":"As leucemias agudas são o tipo mais comum;","C":"A chance de cura é maior que 70%;","D":"Todas as anteriores."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-84511","number":"84511","sourceNumber":"84511","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O antígeno carcinoembrionário:","options":{"A":"Tem valor prognóstico no câncer colorretal.","B":"Não é influenciado pelo tabagismo.","C":"É um antígeno específico no câncer colorretal (CCR).","D":"Tem valor no screening de câncer colorretal.","E":"Pouco sensível."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-84530","number":"84530","sourceNumber":"84530","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O que aumenta o risco de se desenvolver câncer de estômago:","options":{"A":"Comer farinha.","B":"Comer pimenta.","C":"Comer sal.","D":"Tomar refrigerante.","E":"Tomar chá."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-84526","number":"84526","sourceNumber":"84526","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Cirurgia de urgência no câncer gástrico, EXCETO?","options":{"A":"Hemorragia com politransfusão.","B":"Obstrução com vômito.","C":"Ascite hemorrágica maligna tensa.","D":"Perfuração sem bloqueio.","E":"Ruptura por distensão."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-84457","number":"84457","sourceNumber":"84457","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"<p>Nos tumores de reto baixo, temos como opções terapêuticas, EXCETO:</p>","options":{"A":"Ablação por radiofrequência.","B":"Excisão transanal.","C":"Amputação abdominoperineal do reto.","D":"Radioterapia e quimioterapia.","E":"Excisão videolaparoscópica."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-372092","number":"372092","sourceNumber":"372092","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente feminina, 19 anos, queixa-se de abaulamento na região lateral esquerda do\nabdome notada há aproximadamente 5 meses.\nRelata que notou abaulamento local com\ncrescimento progressivo, indolor. Nega trauma. Nega sintomas urinários. Nega febre, perda de\npeso, sudorese. É portadora de polipose adenomatosa familiar, submetida à colectomia total há 5\nanos. Ao exame físico: bom estado geral, com massa palpável na região lateral esquerda, que se\nestende em toda parede lateral do abdome, de limites imprecisos, no espaço entre as últimas\ncostelas e a crista ilíaca, indolor, endurecida, aderida a planos profundos. Realizou a tomografia\nde\nabdome para investigação (figura abaixo). Após avaliação do exame radiológico, foi submetida à\nbiópsia da lesão. O exame histopatológico evidenciou proliferação celular atípica, com estudo\nimunohistoquímico positivo focal para beta-catenina, positivo para actina de músculo liso e negativo\npara desmina. Assinale a principal hipótese diagnóstica.","options":{"A":"Fístula colo cutânea.","B":"Doença de Crohn.","C":"Tumor desmoide.","D":"Rabdomiossarcoma."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":["question_bank/media/medcurso/med-cirurgia-med-cir-06/372092.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-341053","number":"341053","sourceNumber":"341053","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Homem, 65 anos de idade, é levado ao Ambulatório de Cirurgia Geral com história de\ndor em epigástrio, de moderada\nintensidade, com piora à alimentação há dois meses. O paciente\nrefere, também, hiporexia, alguns episódios de náuseas e vômitos e perda de peso (não\nmensurada) neste mesmo período. Relata tabagismo 30 cigarros/dia e etilismo social há 30 anos.\nAo exame físico, regular estado geral, descorado +2/+4, ictérico +1/+4, FC: 72bpm, PA:\n110x74mmHg, ausculta cardíaca e respiratória sem alterações; abdome um pouco distendido;\nruídos hidroaéreos presentes, flácido; dor à palpação profunda de epigástrio, sem sinais de\nirritação\nperitoneal; palpado nódulo em região umbilical, medindo cerca de 1,0cm. Os exames laboratoriais\niniciais apresentaram Hb: 10g/dL, Ht: 32%, Leucócitos totais: 9500células/mm³, Ureia: 35mg/dL,\nCreatina: 1,0mg/dL, Na: 142mEq/L, K: 4,0mEq/L, Bilirrubinas totais 3,5mg/dL (direta: 2,5/dL e\nindireta: 1,0mg/dL). Diante do caso clínico e dos exames complementares, indique a principal\nsuspeita diagnóstica que justifique o quadro clínico do paciente:","options":{"A":"Hepatite crônica alcoólica.","B":"Pancreatite crônica alcoólica.","C":"Linfoma não-Hodgkin.","D":"Câncer gástrico."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-341054","number":"341054","sourceNumber":"341054","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Homem, 65 anos de idade, é levado ao Ambulatório de Cirurgia Geral com história de\ndor em epigástrio, de moderada\nintensidade, com piora à alimentação há dois meses. O paciente\nrefere, também, hiporexia, alguns episódios de náuseas e vômitos e perda de peso (não\nmensurada) neste mesmo período. Relata tabagismo 30 cigarros/dia e etilismo social há 30 anos.\nAo exame físico, regular estado geral, descorado +2/+4, ictérico +1/+4, FC: 72bpm, PA:\n110x74mmHg, ausculta cardíaca e respiratória sem alterações; abdome um pouco distendido;\nruídos hidroaéreos presentes, flácido; dor à palpação profunda de epigástrio, sem sinais de\nirritação\nperitoneal; palpado nódulo em região umbilical, medindo cerca de 1,0cm. Os exames laboratoriais\niniciais apresentaram Hb: 10g/dL, Ht: 32%, Leucócitos totais: 9500células/mm³, Ureia: 35mg/dL,\nCreatina: 1,0mg/dL, Na: 142mEq/L, K: 4,0mEq/L, Bilirrubinas totais 3,5mg/dL (direta: 2,5/dL e\nindireta: 1,0mg/dL). Com base no quadro, indique o exame complementar mais adequado para a\nconfirmação do diagnóstico:","options":{"A":"Punção por agulha grossa do fígado guiada por ultrassonografia.","B":"Tomografia computadorizada do abdome.","C":"Endoscopia digestiva alta.","D":"Videolaparoscopia diagnóstica."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-341055","number":"341055","sourceNumber":"341055","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Homem, 65 anos de idade, é levado ao Ambulatório de Cirurgia Geral com história de\ndor em epigástrio, de moderada\nintensidade, com piora à alimentação há dois meses. O paciente\nrefere, também, hiporexia, alguns episódios de náuseas e vômitos e perda de peso (não\nmensurada) neste mesmo período. Relata tabagismo 30 cigarros/dia e etilismo social há 30 anos.\nAo exame físico, regular estado geral, descorado +2/+4, ictérico +1/+4, FC: 72bpm, PA:\n110x74mmHg, ausculta cardíaca e respiratória sem alterações; abdome um pouco distendido;\nruídos hidroaéreos presentes, flácido; dor à palpação profunda de epigástrio, sem sinais de\nirritação\nperitoneal; palpado nódulo em região umbilical, medindo cerca de 1,0cm. Os exames laboratoriais\niniciais apresentaram Hb: 10g/dL, Ht: 32%, Leucócitos totais: 9500células/mm³, Ureia: 35mg/dL,\nCreatina: 1,0mg/dL, Na: 142mEq/L, K: 4,0mEq/L, Bilirrubinas totais 3,5mg/dL (direta: 2,5/dL e\nindireta: 1,0mg/dL). Identifique, entre os achados da história clínica e do exame físico do\npaciente,\no fator de pior prognóstico:","options":{"A":"Anemia.","B":"Nódulo palpável em região umbilical.","C":"Icterícia.","D":"Perda de peso."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-343190","number":"343190","sourceNumber":"343190","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O câncer de tireoide que acomete mulheres jovens e tem melhor prognóstico é:","options":{"A":"Carcinoma folicular","B":"Carcinoma mucoepidermoide","C":"Carcinoma papilífero","D":"Carcinoma estromal"},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-275977","number":"275977","sourceNumber":"275977","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente com 55 anos de idade apresenta, ao exame físico, nódulo na tireóide de 4,5\ncm que movimenta-se à deglutição. Que exames devem ser solicitados para o diagnóstico?","options":{"A":"Ultrassonografia da tireóide e punção guiada por ultrassom.","B":"T3, T4, livre e TSH.","C":"Exames pré-operatórios de rotina e Rx de tórax.","D":"Não é necessário nenhum exame, somente acompanhamento clínico.","E":"Ultrassonografia da tireóide."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-275980","number":"275980","sourceNumber":"275980","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Na classificação morfológica dos tumores do estômago, Bormann 4, é:","options":{"A":"Tumor ulcerado.","B":"Infiltrativo local.","C":"Infiltrativo difuso (Linite).","D":"Escavado.","E":"Ulcerado e infiltrativo local."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-275981","number":"275981","sourceNumber":"275981","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"No paciente cirrótico é necessário fazer o rastreamento periódico na pesquisa de\nhepatocarcinoma. Como fazer esse rastreamento?","options":{"A":"Ultrassonografia e dosar antígeno carcinogênico embrionário (CEA) a cada três meses.","B":"Tomografia de seis em seis meses.","C":"Dosar alfafetoproteína, CEA e CA 19-9 de seis em seis meses.","D":"Ultrassonografia e dosar alfafetoproteína a cada seis meses.","E":"Ultrassonografia e dosar CA 19-9 a cada seis meses."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-275986","number":"275986","sourceNumber":"275986","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Na neoplasia da cabeça de Pâncreas, qual o primeiro sinal ou sintoma que geralmente\napresenta?","options":{"A":"Emagrecimento.","B":"Icterícia.","C":"Sinal de Cullen.","D":"Dor no hipocôndrio direito.","E":"Massa palpável."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-283730","number":"283730","sourceNumber":"283730","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente, sexo feminino, 45 anos de idade, é encaminhada ao ambulatório de cirurgia\npor apresentar nódulo palpável em região cervical\nanterior. A paciente nega comorbidades ou uso\nde medicações. Ao exame, bom estado geral, presença de nódulo palpável na topografia da\nglândula tireoide, medindo cerca de 1,2cm no maior diâmetro. Foi realizada uma ultrassonografia\nda região cervical. Indique a principal suspeita diagnóstica para o nódulo cervical.","options":{"A":"Metástase linfonodal.","B":"Carcinoma papilífero de tireoide.","C":"Cisto tireoidiano.","D":"Lipoma de subcutâneo."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-283731","number":"283731","sourceNumber":"283731","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente, sexo feminino, 45 anos de idade, é encaminhada ao ambulatório de cirurgia\npor apresentar nódulo palpável em região cervical\nanterior. A paciente nega comorbidades ou uso\nde medicações. Ao exame, bom estado geral, presença de nódulo palpável na topografia da\nglândula tireoide, medindo cerca de 1,2 cm no maior diâmetro. Foi realizada uma ultrassonografia\nda região cervical. Determine a conduta mais adequada para confirmar o diagnóstico.","options":{"A":"Realizar tomografia computadorizada de cabeça, pescoço e tórax.","B":"Orientar a paciente que se trata de doença benigna e que não há necessidade de outro exame\ncomplementar.","C":"Realizar punção aspirativa, com agulha fina, do nódulo.","D":"Indicar exérese do nódulo."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-252891","number":"252891","sourceNumber":"252891","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente, sexo masculino, 50 anos de idade, dá entrada no Pronto Socorro com a\nqueixa de dispneia e tosse pouco produtiva\nhá três meses, com piora, há três dias. Refere piora\ndos sintomas ao se deitar. Relata também cefaleia e náuseas. Refere tabagismo de 40 maços/ano.\nAo exame físico, regular estado geral, pletora facial, estase de jugulares, Temperatura axilar:\n36,5°C, FC: 78bpm, PA: 122x78mmHg, FR: 24imp; ausculta cardíaca sem alterações; ausculta\nrespiratória com murmúrios vesiculares bem distribuídos com roncos e crépitos difusamente\nbilateral; abdome plano, flácido e indolor; edema dos menbros superiores +2/ +4. Após o exame\ninicial, indique a principal suspeita diagnóstica que levou o paciente a procurar o Pronto Socorro.","options":{"A":"Tamponamento cardíaco.","B":"Síndrome da veia cava superior.","C":"Tromboembolismo pulmonar.","D":"Pneumonia com derrame pleural."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-252892","number":"252892","sourceNumber":"252892","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente, sexo masculino, 50 anos de idade, dá entrada no Pronto Socorro com a\nqueixa de dispneia e tosse pouco produtiva\nhá três meses, com piora, há três dias. Refere piora\ndos sintomas ao se deitar. Relata também cefaleia e náuseas. Refere tabagismo de 40 maços/ano.\nAo exame físico, regular estado geral, pletora facial, estase de jugulares, Temperatura axilar:\n36,5°C, FC: 78bpm, PA: 122x78mmHg, FR: 24imp; ausculta cardíaca sem alterações; ausculta\nrespiratória com murmúrios vesiculares bem distribuídos com roncos e crépitos difusamente\nbilateral; abdome plano, flácido e indolor; edema dos menbros superiores +2/ +4. Indique a principal\nsuspeita etiológica que gerou a condição clínica desse paciente.","options":{"A":"Trombose venosa profunda.","B":"Derrame pericárdico.","C":"Neoplasia de pulmão.","D":"Doença Pulmonar Obstrutiva Crônica."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-252893","number":"252893","sourceNumber":"252893","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente, sexo masculino, 50 anos de idade, dá entrada no Pronto Socorro com a\nqueixa de dispneia e tosse pouco produtiva\nhá três meses, com piora, há três dias. Refere piora\ndos sintomas ao se deitar. Relata também cefaleia e náuseas. Refere tabagismo de 40 maços/ano.\nAo exame físico, regular estado geral, pletora facial, estase de jugulares, Temperatura axilar:\n36,5°C, FC: 78bpm, PA: 122x78mmHg, FR: 24imp; ausculta cardíaca sem alterações; ausculta\nrespiratória com murmúrios vesiculares bem distribuídos com roncos e crépitos difusamente\nbilateral; abdome plano, flácido e indolor; edema dos menbros superiores +2/ +4. Indique o exame\nmais adequado para completar a investigação diagnóstica.","options":{"A":"Ultrassonografia com doppler venoso dos membros superiores.","B":"Ecocardiografia transtorácica.","C":"Tomografia computadorizada de tórax.","D":"Radiografia de tórax."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-231376","number":"231376","sourceNumber":"231376","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente com 45 anos de idade, assintomática, apresenta no exame físico nódulo na\ntireóide medindo aproximadamente 4,0 cm de diâmetro, que se movimenta com a deglutição. Que\nexames devem ser solicitados como propedêutica de diagnóstico e estadiamento?","options":{"A":"Ultrassom da tireóide e a punção por agulha fina dirigida por ultrassom do nódulo da tireoide.","B":"T3, T4, TSH e T4Live.","C":"Exames pré-operatórios de rotina e Rx de tórax.","D":"Avaliação cardiológica de rotina pré-operatório.","E":"Não faria nenhum exame de laboratório, somente exame clínico físico."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-249421","number":"249421","sourceNumber":"249421","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O tratamento curativo do carcinoma medular de tireoide é a tireoidectomia importante\npara ressecção de possíveis lesões metastáticas.\nNa tireoidectomia total por carcinoma medular de\ntireoide, mesmo de forma profilática, deve-se esvaziar o nível cervical:","options":{"A":"II","B":"III","C":"V","D":"VI"},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-249233","number":"249233","sourceNumber":"249233","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"A lesão tireoidiana que é associada a um aumento dos níveis de calcitonina é:","options":{"A":"Tireoidite de Hashimoto.","B":"Carcinoma papilífero.","C":"Carcinoma medular.","D":"Tireoidite esclerosante."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-249235","number":"249235","sourceNumber":"249235","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Das lesões polipóides abaixo, a que apresenta maior potencial de degeneração maligna\né:","options":{"A":"Adenoma tubular.","B":"Pólipo hiperplásico.","C":"Adenoma viloso.","D":"Hamartoma."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-212151","number":"212151","sourceNumber":"212151","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 62 anos, masculino, obeso e sedentário, diabético, etilista e tabagista, com\nquadro de astenia e perda ponderal significativa. História prévia de sangramento retal e\nconstipação intestinal. Ao exame físico, apresentava-se em regular estado geral, eupneico,\nhidratado, hipocorado (2+/4+), frequência cardíaca = 84 bpm, abdome flácido, doloroso à palpação\nprofunda no quadrante inferior direito, sem sinais de irritação peritoneal. Inspeção e toque retal\nevidenciaram coxins hemorroidários, presença de fezes na ampola, sem lesões. Foi submetido a\nretossigmoidoscopia, que não evidenciou nenhuma alteração. Sobre o caso apresentado, assinale\na alternativa CORRETA.","options":{"A":"A colonoscopia está indicada.","B":"O paciente em questão apresenta, apenas, dois fatores de risco para neoplasia.","C":"A dosagem do antígeno carcinoembrionário (CEA) está indicado para rastreamento e\ndiagnóstico.","D":"Caso o diagnóstico do paciente seja neoplasia colorretal, está indicado PET-CT de rotina para\nesse paciente.","E":"O diagnóstico de câncer colorretal pode ser excluído, visto que o sangramento retal está\njustificado pela doença hemorroidária."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-219874","number":"219874","sourceNumber":"219874","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"D.N.E., sexo masculino, 26 anos, mecânico, notou massa palpável na região cervical\nanterior que teve crescimento relativamente\nrápido nos últimos 2 meses, sem outros sinais ou\nsintomas. Não sabe precisar casos semelhantes na família. Exames laboratoriais de rotina estão\nnormais e dosagem de calcitonina elevada. Foram solicitados alguns exames de marcadores\ntumorais e de função tireoidiana. A PAAF com imuno-histoquímica confirmou carcinoma medular da\ntireoide. Sobre este paciente e seu tumor, assinale alternativa INCORRETA:","options":{"A":"A ausência de antecedentes familiares direciona o diagnóstico para a forma esporádica, que é\nmais rara e tem melhor prognóstico a longo prazo.","B":"As células deste tipo de tumor não concentram iodo radioativo e não são sensíveis ao hormônio\ntireoestimulante (TSH).","C":"Entre os marcadores tumorais que podem estar elevados nesta situação está o antígeno\ncarcinoembrionário (CEA).","D":"Tem indicação de tireoidectomia total com linfadenectomia (dissecção linfonodal)."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-219864","number":"219864","sourceNumber":"219864","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"RDD, 30 anos, sexo masculino, casado, balconista, iniciou alteração do hábito intestinal\ne sangramento nas fezes. A retossigmoidoscopia\nmostrou mamilos hemorroidários de IIIo grau e\nvários pólipos no reto. Foi realizada colonoscopia que mostrou inúmeros pólipos em todo o intestino\ngrosso. O exame de fundo de olho confirmou hipertrofia congênita do epitélio pigmentar da retina\n(CHRDE). Apresentava também osteoma de face (mandibular) e cistos epidérmicos em região\n\npré-tibial, mas não sabe precisar a época de seus aparecimentos. Foi solicitada EDA e está\nproposta a realização de colectomia total. Em\nrelação aos desdobramento deste caso, assinale a\nalternativa INCORRETA:","options":{"A":"A realização de coletomia total, previne o aparecimento de câncer ligado à polipose\nadenomatosa familiar.","B":"A realização de laparotomia aumenta o risco de aparecimento de tumor desmoide.","C":"As manifestações extraintestinais podem proceder ao aparecimento dos pólipos do intestino\ngrosso.","D":"Os pólipos do estômago acometem principalmente o antro e têm baixo risco de malignização."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-212140","number":"212140","sourceNumber":"212140","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Assinale a alternativa correta sobre o carcinoma hepatocelular.","options":{"A":"O carcinoma do tipo fibrolamelar, na maioria das vezes, não está associado à cirrose.","B":"No ocidente, o principal fator de risco para a doença é a cirrose por álcool.","C":"O rastreamento padrão da doença é ressonância magnética semestralmente.","D":"Pacientes Child B são os melhores candidatos à ressecção hepática.","E":"Hipertensão portal não contraindica ressecção em lesões grandes."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-219892","number":"219892","sourceNumber":"219892","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"DDK, 32 anos, sexo feminino, decoradora, realizou uma série de exames pois tem\nintenção de interromper o uso de\nanticoncepcional para engravidar. Os exames laboratoriais foram\nnormais, porém a ultrassonografia mostrou nódulo de 20 mm no segmento IV do fígado. Foi\nsolicitada tomografia, que evidenciou massa heterogênea bem delimitada com realce precoce na\nfase arterial. Em relação a esta situação, assinale a alternativa CORRETA:","options":{"A":"A paciente tem risco de ruptura espontânea do nódulo caso se confirme uma gravidez.","B":"Depois de instalada, a lesão não regride mesmo após a suspensão do anovulatório.","C":"Estas lesões são benignas, geralmente reproduzindo a arquitetura hepática em nódulos isolados\nautônomos.","D":"Não há necessidade de ressecção do nódulo, pois não há risco de degeneração maligna"},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-219849","number":"219849","sourceNumber":"219849","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Em relação aos tumores malignos de localização hepática, assinale a alternativa\nINCORRETA:","options":{"A":"A cirrose, por quase todas etiologias, está associada a um aumento da ocorrência de carcinoma\nhepatocelular.","B":"O fígado cirrótico é mais suscetível ao implante de metástases de tumores de outros órgãos.","C":"Os hepatomas geralmente são mais vascularizados que o parênquima normal.","D":"Os níveis séricos de alfafetoproteína podem guardar relação com o prognóstico do câncer\nhepático."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-212185","number":"212185","sourceNumber":"212185","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 55 anos, ex-etilista, 20 g de álcool por 12 anos, parou há 20 anos, sem\noutras comorbidades, apresentando dor epigástrica\nem queimação, sem irradiação, sem relação\ncom alimentação há 2 meses. Emagreceu cerca de 8 kg desde então. Fazia uso de hidróxido de\nmagnésio com pouca melhora do quadro. Em consulta médica observa-se paciente em bom estado\ngeral, hipocorado, hidratado, pouco emagrecido. Abdome plano, flácido, indolor, sem cicatrizes\ncirúrgicas nem massas palpáveis. Não são identificadas adenopatias à palpação axilar, cervical e\ninguinal. É realizada endoscopia digestiva alta onde se observa lesão ulcerada, bordos elevados e\nbem delimitados, com cerca de 3 cm de diâmetro em incisura angular, pequena curvatura. Biópsia\nde lesão diagnóstica adenocarcinoma moderadamente diferenciado, tipo intestinal. Tomografia de\nabdome e tórax evidencia espessamento parietal de porção antral do estômago, com densificação\nda gordura mesentérica e adenopatias maiores que 1 cm adjacentes a artéria gástrica esquerda,\nsem líquido livre. Assinale a alternativa correta sobre o caso.","options":{"A":"Trata-se de uma lesão Bormann II.","B":"Trata-se de uma neoplasia gástrica Siewert II.","C":"Quimioterapia neoadjuvante não altera sobrevida.","D":"É uma lesão passível de dissecção endoscópica submucosa, menos invasiva para esse tipo de\nlesão.","E":"Ultrassonografia endoscópica é o melhor exame para estadiamento locoregional dessa doença."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-215477","number":"215477","sourceNumber":"215477","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Os tumores de partes moles representam um grupo complexo e heterogêneo de\nneoplasias que se originam de células\nmesenquimais primitivas e localizam-se em qualquer região\nanatômica, exceto em ossos e cartilagens. Assinale a alternativa INCORRETA.","options":{"A":"O lipossarcoma bem diferenciado em regiões superficiais e extramusculares tem bom\nprognóstico e virtualmente não ocasiona metástases.","B":"O rabdomiossarcoma embrionário acomete, principalmente, pacientes com faixa etária acima de\n20 anos.","C":"O sarcoma de Kaposi está usualmente limitado à pele, mas com ocorrência em diversas\ntopografias.","D":"O sarcoma alveolar de partes moles ocorre em adultos nas regiões profundas de membros,\ncavidade oral, faringe e mediastino."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-216211","number":"216211","sourceNumber":"216211","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Sobre os Tumores Metastáticos do Pulmão, assinale a INCORRETA.","options":{"A":"A pior sobrevida é obtida nos pacientes portadores de metástase de carcinomas coloretais.","B":"São os principais sítios de metástases dos tumores sólidos.","C":"Radiologicamente estas lesões se apresentam como nódulos múltiplos e bem delimitados.","D":"A melhor sobrevida é obtida nos pacientes portadores de metástases de células germinativas."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-201791","number":"201791","sourceNumber":"201791","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O marcador tumoral mais específico para o carcinoma hepatocelular é:","options":{"A":"CA-19-9.","B":"CA-125-5.","C":"Alfafetoproteína.","D":"Antígeno Carcinogênico Embrionário (CEA).","E":"Anticorpos antimitocôndria."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-215526","number":"215526","sourceNumber":"215526","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"De acordo com o estadiamento dos tumores testiculares (Children´s Oncology Group),\nos pacientes que apresentam acometimento de\nlinfonodos retroperitoneais pertencem ao estádio","options":{"A":"I.","B":"II.","C":"III.","D":"IV."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-201794","number":"201794","sourceNumber":"201794","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"No estadiamento morfológico dos tumores do estômago, a classificação Bormann 4, é:","options":{"A":"Tumor ulcerado.","B":"Infiltrativo local.","C":"Infiltrativo difuso (Linite).","D":"Escavado.","E":"Ulcerado e infiltrativo local."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-216260","number":"216260","sourceNumber":"216260","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Sobre os tumores de esôfago é INCORRETO que","options":{"A":"a tomografia computadorizada é o principal método de estadiamento do câncer de esôfago.","B":"o melhor tratamento para câncer epidermoide do esôfago é a ressecção cirúrgica R0","C":"quimioterapia e/ou radioterapia associados ao tratamento cirúrgico não aumentam a\nsobrevivência.","D":"radioterapia terapêutica exclusiva não deve ser indicada com intenção paliativa."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-216301","number":"216301","sourceNumber":"216301","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Sobre as metástases hepáticas dos tumores colorretais é INCORRETO afirmar que","options":{"A":"metástases colorretais não tratadas apresentam prognóstico reservado com sobrevida média de\n6 a 12 meses.","B":"a presença de doença extra-hepática geralmente contraindica a ressecção cirúrgica.","C":"a principal indicação de embolização portal se dá nos casos onde a ressecção hepática não é\nviável.","D":"a ressecção é a modalidade mais efetiva e garante sobrevida de 5 anos em até 80% dos\npacientes."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-216312","number":"216312","sourceNumber":"216312","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"A Hiperplasia Nodular Focal representa o segundo mais frequente tumor hepático\nbenigno. É INCORRETO afirmar que","options":{"A":"a grande característica é lesão hipervascularizada com presença de cicatriz central radiada.","B":"a ocorrência de rotura e sangramento é extremamente rara.","C":"o tratamento cirúrgico é o tratamento de escolha.","D":"o mapeamento com radioisótopos apresenta baixa sensibilidade diagnóstica, mas alta\nespecificidade."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-215211","number":"215211","sourceNumber":"215211","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Sobre os Nódulos Pulmonares Solitários, assinale a INCORRETA.","options":{"A":"São definidas como lesões intrapulmonares menores que 3 centímetros do maior diâmetro, não\nassociado a outras anormalidades.","B":"Entre os diagnósticos diferenciais estão lesões neoplásicas, infecciosas, inflamatória,\nvasculares\ne traumáticas.","C":"A presença de calcificações e bordas lisas é característica de nódulos benignos.","D":"Um ganho maior que 20 UH na tomografia de tórax após a injeção de contraste venoso é\ncaracterístico de benignidade."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-215220","number":"215220","sourceNumber":"215220","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Com relação ao tratamento do tumor primário em tumores germinativos do testículo,\nassinale a alternativa INCORRETA.","options":{"A":"Nos casos de violação dos envoltórios escrotais, impõe-se tratamento preventivo que, em\nseminomas é feito por meio de radioterapia aplicada sobre o hemiescroto e a região inguinal\nhomolateral.","B":"A lesão testicular primária deve ser removida por meio de orquiectomia realizada por incisão\nescrotal.","C":"Quando a intervenção é executada por incisão escrotal, existe risco de derramamento de células\nneoplásicas, com recidiva local da neoplasia em 10 a 20% dos pacientes.","D":"Nos tumores não-seminomatosos, até recentemente se preconizava a realização de\nhemiescrotectomia, mas o caráter mutilante\ndesse procedimento fez com que, na maioria dos\ncentros, esses doentes passassem a ser acompanhados clinicamente instituindo-se quimioterapia\ncitotóxica nos casos de recidiva local comprovada."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-215538","number":"215538","sourceNumber":"215538","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação aos nódulos tireoideanos em crianças.","options":{"A":"Cerca de70% dos nódulos tireoideanos em crianças são neoplasias malignas.","B":"De modo geral, a primeira manifestação clínica é a presença de massa tumoral no pescoço, o\nque motiva a consulta ao pediatra.","C":"Em caso de dúvida diagnóstica após a punção aspirativa, indica-se cirurgia para biópsia, com\nexame do tumor sob congelação, para que se\npossa tomar conduta no mesmo ato.","D":"A biópsia aspirativa da massa com agulha fina, para análise citológica do material obtido,\napresenta sensibilidade de apenas 20% para confirmação diagnóstica."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-187820","number":"187820","sourceNumber":"187820","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Em relação aos nódulos tireoidianos, assinale alternativa ERRADA:","options":{"A":"A malignidade de um nódulo pode ser definida com base na captação de radioisótopos","B":"A Punção Aspirativa por Agulha Fina (PAAF) não é eficiente para confirmação de câncer folicular","C":"Presença de coloiode e macrófagos dentro do aspirado -Punção Aspirativa por Agulha Fina\n(PAAF)- é altamente sugestivo de benignidade","D":"Todo paciente com nódulo tireoidiano deve ser submetido a teste da função tireoidiana"},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-181327","number":"181327","sourceNumber":"181327","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 91 anos, hipertenso, diabético, amputação de membros inferiores\ninfragenicular há 2 anos, apresenta quadro\nde icterícia, adinamia e perda ponderal. Refere dispneia\nem repouso. Ao exame físico, regular estado geral, consciente, orientado, ictérico 3/4+, fc 82 bpm,\nfr 26. ECOG 3. Abdome globoso, flácido, fundo de vesícula palpável em rebordo costal direito,\nindolor. Propedêutica revela ausência de litíase em vesícula e via biliar, lesão em cabeça de\npâncreas de 4,5 cm em seu maior diâmetro, artérias mesentérica e hepática livres e veia\nmesentérica em íntimo contato com lesão em mais de 180 graus, adenopatias inter aorta-cavais.\n\nQual a conduta mais adequada para esse paciente?","options":{"A":"Drenagem biliar percutânea.","B":"Duodenopancreatectomia cefálica.","C":"Drenagem endoscópica de via biliar.","D":"Ecoendoscopia para estadiamento e biópsia de lesão para início de neoadjuvância.","E":"Ecoendoscopia para estadiamento e biópsia de lesão e drenagem de via biliar no mesmo ato."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-183590","number":"183590","sourceNumber":"183590","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"De acordo com a Oitava Edição do Sistema de Estadiamento de Câncer de Pulmão\n(2015), assinale a alternativa CORRETA com relação aos tumores tipo T3.","options":{"A":"Tumores entre 1 e 2 cm.","B":"Tumores entre 2 e 3 cm.","C":"Tumores entre 5 e 7 cm.","D":"Tumores entre 3 e 5 cm."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-183568","number":"183568","sourceNumber":"183568","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente masculino, 50 anos, assintomático, foi diagnosticado um carcinoma\nespinocelular pela broncoscopia com biópsia\ntransbrônquica. Na tomografia de tórax foi observado\num nódulo de 3 cm na topografia segmento VI do pulmão direito, mediastino sem adenomegalias e\nnão havia evidência de doença à distância. A prova funcional respiratória e cardíaca normal, sendo\nindicado tratamento cirúrgico. Qual a cirurgia preconizada deve ser realizada em associação com\nesvaziamento mediastinal linfonodal?","options":{"A":"Lobectomia média.","B":"Lobectomia inferior direita.","C":"Lobectomia superior direita.","D":"Língulectomia."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-183063","number":"183063","sourceNumber":"183063","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Quais são os principais sítios de metástases à distância no câncer de pulmão?","options":{"A":"Fígado, cérebro, suprarrenal e ossos.","B":"Mediastino, fígado e baço.","C":"Baço, cérebro e osso.","D":"Linfonodos mediastinais, baço e osso."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-183613","number":"183613","sourceNumber":"183613","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"A Síndrome de Horner é caracterizada por:","options":{"A":"enoftalmia, ptose palpebral e miose.","B":"exoftamia, miose e ptose palpebral.","C":"enoftalmia, midríase e anidrose.","D":"exoftalmia, midríase e ptose palpebral."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-183106","number":"183106","sourceNumber":"183106","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Qual dos achados abaixo se considera como critério sugestivo de benignidade no\nnódulo pulmonar solitário?","options":{"A":"Presença de gordura.","B":"Margens espiculadas.","C":"Captação no PET-CT com SUV maior que 2,5.","D":"Tamanho maior que 2 cm."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-183091","number":"183091","sourceNumber":"183091","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Em qual situação um paciente com neoplasia pulmonar está fora de protocolo para\ntratamento cirúrgico curativo?","options":{"A":"Metástase linfonodal em cadeia XI ipsilateralmente.","B":"Presença de derrame pleural maligno.","C":"Lesão maior do que 5 cm.","D":"Envolvimento de mais de um dos lobos pulmonares ipsilateralmente."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-183615","number":"183615","sourceNumber":"183615","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"É INCORRETO afirmar sobre o carcinoma esofágico:","options":{"A":"Pacientes com a Síndrome de Plummer-Vinson tem risco aumentado para desenvolver câncer\nde células escamosas do esôfago cervical.","B":"Menos da metade dos pacientes que se apresentam com câncer esofágico são elegíveis para\nressecção cirúrgica.","C":"O Adenocarcinoma é mais sensível à quimiorradioterapia.","D":"Na esofagectomia em bloco uma linfadenectomia torácica radical é realizada, e todos os\nlinfonodos mediastinais (incluindo paratraqueal direito, subcarinal, paraesofágico e ligamento\npulmonar inferior esquerdo e direito) e linfonodos diafragmáticos, bem como tecidos linfáticos\nligados ao ducto torácico, são removidos."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-183076","number":"183076","sourceNumber":"183076","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente em pós-operatório imediato de tireoidectomia total apresenta estridor laríngeo\nlogo após a extubação e insuficiência\nrespiratória. Qual é a principal hipótese diagnóstica?","options":{"A":"Lesão do nervo vago.","B":"Lesão da traqueia.","C":"Lesão da laringe.","D":"Lesão do nervo laríngeo recorrente bilateral."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-161396","number":"161396","sourceNumber":"161396","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Sobre os tumores endócrinos pancreáticos funcionais, aponte a alternativa\nINCORRETA.","options":{"A":"O Insulinoma é o tumor funcionante mais comum do pâncreas endócrino, a idade média de\napresentação é de 45 anos, a localização predominante é corpo, cauda e cabeça pancreática.\nPodendo também se localizar, em menor incidência, no duodeno, hilo esplênico ou ligamento\ngastrocólico.","B":"A tríade de Whipple se caracteriza por sintomas de hipoglicemia neuroglicopênicos induzidos por\njejum, baixos níveis de glicose e alívio dos sintomas após administração de glicose.","C":"O Glucagonoma também tem incidência elevada. São mais comuns em homens, com tendência\na ser maior. Quase sempre se originam no\npâncreas. Apresentação clássica inclui diabetes,\ndermatite, trombose venosa profunda e depressão, e também\n\nestado catabólico grave.","D":"A síndrome de Zollinger-Ellison é decorrente da superprodução de gastrina, deve ser investigada\nnos pacientes com ulceração péptica grave\nrefratária, diarreia secretória persistente, esofagite\ngrave. Nível sérico elevado de gastrina, juntamente com pH inferior a 2 no aspirado gástrico, é\nquase diagnóstico da síndrome."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-158788","number":"158788","sourceNumber":"158788","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Suponha que você está realizando uma gastrectomia subtotal oncológica, seguindo\ntodos os passos técnicos corretamente. Depois\nde realizar o descolamento intercoloepiploico,\nligadura dos vasos gastroepiploicos direitos e dos vasos gástricos esquerdos e suas respectivas\nlinfadenectomias, inadvertidamente, promove uma lesão esplênica durante linfadenectomia desta\nregião. Você tenta realizar hemostasia, esplenorrafia, confecção de patch, todas sem sucesso e\nopta, finalmente, por esplenectomia para não comprometer a estabilidade clínica e hemodinâmica\ndo paciente. Após todos esses passos técnicos, qual será sua próxima conduta para continuação\nda cirurgia?","options":{"A":"Gastrectomia a 4/5.","B":"Cirurgia de Traverso-Longmire.","C":"Gastrectomia total com reconstrução em Y de Roux.","D":"Gastrectomia subtotal com reconstrução em Y de Roux.","E":"Abortar cirurgia para controle de dano e nova abordagem em 48 hs."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-158781","number":"158781","sourceNumber":"158781","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente, 70 anos, tabagista, procura atendimento com relato de cianose, edema\ncervicofacial e distensão das veias do\npescoço. Diante da possibilidade de uma Síndrome da veia\ncava superior (SVCS), dadas as afirmativas, I. O câncer do pulmão é responsável por cerca de 70%\ndos casos de SVCS, sendo o tipo histológico mais comum o carcinoma indiferenciado de pequenas\ncélulas.; II. O tratamento da SVCS requer o estabelecimento do diagnóstico etiológico. Medidas\nclínicas como manter o paciente em posição de Trendelemburg, oxigênio, diuréticos, antibióticos e\nanti-inflamatórios não esteroidais são recomendadas.; III. O paciente com SVCS pode apresentar:\ndispneia, dor torácica, edema peribrônquico e periesofagiano, tontura, síncope, coma e circulação\ncolateral na parede torácica.; IV. Fibrose mediastinal secundária à histoplasmose, bócio subesternal\nde grandes proporções são causas não neoplásicas da SVCS. Os cateteres implantados no\nsistema cava superior assim como o Swan-Ganz e os marca-passos podem levar a trombose e\nSVCS. Verifica-se que está(ão) correta(s) apenas:","options":{"A":"III.","B":"I e II.","C":"II e IV.","D":"I, II e IV.","E":"I, III e IV."},"answer":"E","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-152629","number":"152629","sourceNumber":"152629","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O principal diagnóstico diferencial ao raio X de tórax do carcinoma pulmonar é:","options":{"A":"Tuberculose.","B":"Abscesso.","C":"Bola fúngica.","D":"Todas as anteriores.","E":"NDA."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-161409","number":"161409","sourceNumber":"161409","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O câncer de pulmão é um dos tumores malignos mais frequentes no Brasil e no mundo;\né também a principal causa de morte oncológica\nem homens. Assinale a alternativa INCORRETA.","options":{"A":"No momento do diagnóstico, mais de 50% dos pacientes com câncer de pulmão já têm doença\nmetastática.","B":"Quanto às manifestações clínicas, tosse, dispneia, hemoptise, dor torácica e rouquidão são\nsintomas frequentes.","C":"Tosse geralmente está presente em 50-75% dos pacientes.","D":"Dispneia também é um sintoma comum já no momento do diagnóstico, ocorrendo em\naproximadamente 90% dos casos."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-152667","number":"152667","sourceNumber":"152667","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"No estadiamento morfológico dos tumores do estômago, a classificação Bormann 4, é:","options":{"A":"Tumor ulcerado.","B":"Infiltrativo local.","C":"Infiltrativo difuso (Linite).","D":"Escavado.","E":"Ulcerado e infiltrativo local."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-152670","number":"152670","sourceNumber":"152670","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"No paciente cirrótico, como se faz o rastreamento na pesquisa de hepatocarcinoma?","options":{"A":"Ultrassonografia + dosar alfa-fetoproteína a cada seis meses.","B":"Ultrassonografia + dosar antígeno carcinogênico embrionário (CEA) a cada três meses.","C":"Tomografia de seis em seis meses.","D":"Dosar alfa-fetoproteína, CEA e CA 19-9 de seis em seis meses.","E":"Ultrassonografia + dosar CA 19-9 a cada seis meses."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-134810","number":"134810","sourceNumber":"134810","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 32 anos, cuja ultrassonografia abdominal revela tumor cístico de 2 cm de\ndiâmetro, situado na cabeça do pâncreas. A próxima etapa para investigação diagnóstica deve ser","options":{"A":"Ressonância nuclear magnética.","B":"Tomografia computadorizada com punção percutânea.","C":"Ultrassonografia endoscópica com punção do cisto para dosagem de CA19.9, CEA e citologia.","D":"Colangiopancreatografia retrógrada."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-134113","number":"134113","sourceNumber":"134113","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"A técnica de Ivor Lewis é uma técnica consagrada, caracterizada por","options":{"A":"Gastrectomia parcial e reconstrução com gastrojejunostomia pré-cólica.","B":"Gastrectomia parcial e reconstrução com gastrojejunostomia transmesocólica.","C":"Gastrectomia proximal e esofagectomia distal.","D":"Gastrectomia total e reconstrução com Y de Roux."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-134842","number":"134842","sourceNumber":"134842","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Indique a alternativa que contenha, CORRETAMENTE, o tipo histológico mais\ncomum de neoplasia gástrica e a classificação de neoplasia avançada.","options":{"A":"Linfoma e classificação de Boorman.","B":"Adenocarcinoma e classificação de Boorman.","C":"Carcinoma espinocelular e classificação de Boorman.","D":"Adenocarcinoma e classificação de Rezende."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-134048","number":"134048","sourceNumber":"134048","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Manoel, 70 anos, com anemia microcítica hipocrômica. A endoscopia digestiva\nalta revelou gastrite inespecífica difusa. O\nteste respiratório foi positivo para presença do H.\npylori e exame histopatológico das biópsias gástricas mostrou linfoma Malt. A conduta MAIS\nadequada é","options":{"A":"Quimioterapia.","B":"Radioterapia.","C":"Gastrectomia.","D":"Tratar o H. pylori e estadiar a doença."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-134897","number":"134897","sourceNumber":"134897","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Jandira, 80 anos, em bom estado geral, procura o Médico por aumento do volume\nabdominal e plenitude pós-prandial. Exame\nfísico: volumosa massa abdominal supraumbilical de\nconsistência indefinida, indolor à palpação, com manobra do rechaço positiva. Exames laboratoriais\nnormais. Tomografia de abdome: grande massa envolvendo corpo e cauda do pâncreas. A conduta\nMAIS apropriada é","options":{"A":"realizar gastro-jejunostomia paleativa.","B":"pancreatectomia corpo-caudal + esplenectomia.","C":"drenagem percutânea da massa.","D":"quimioterapia e radioterapia neoadjuvantes."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-131369","number":"131369","sourceNumber":"131369","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O câncer colorretal, que ocorre durante a gravidez, é mais comum no:","options":{"A":"Reto.","B":"Sigmoide.","C":"Descendente.","D":"Transverso.","E":"Ascendente."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-110001","number":"110001","sourceNumber":"110001","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente do sexo feminino, 25 anos, é internada por episódios de Hipoglicemia. Não é\ndiabética e não faz uso de hipoglicemiantes orais ou insulina. Apresenta índice de massa corporal\nde 25 kg/m2. Nega regimes dietéticos ou uso de outras medicações. Qual é o diagnóstico MAIS\nprovável para o caso?","options":{"A":"Tumor pancreático produtor de insulina (insulinoma).","B":"Jejum prolongado por não fracionamento da dieta (paciente somente toma café da manhã e\njanta, em decorrência do trabalho).","C":"Gliconeogênese insuficiente por substituição do parênquima hepático por metástases.","D":"Síndrome de Cushing."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-109719","number":"109719","sourceNumber":"109719","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O câncer gástrico precoce é definido como lesão que:","options":{"A":"atinge mucosa ou até submucosa.","B":"sempre só atinge mucosa.","C":"atinge mucosa ou até submucosa e, nunca ocorre comprometimento de linfonodos.","D":"atinge até a serosa."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-109742","number":"109742","sourceNumber":"109742","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"A Técnica de Stamm é empregada:","options":{"A":"para correção de Hérnias Ventrais.","B":"na realização de Gastrostomia.","C":"na realização de Colostomia.","D":"na realização de Jejunostomia."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-110614","number":"110614","sourceNumber":"110614","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O marcador tumoral mais específico para o carcinoma hepatocelular é:","options":{"A":"CA 19-9.","B":"CA 125-5.","C":"Alfa-fetoproteína.","D":"Antígeno carcinogênico embrionário (CEA).","E":"Anticorpos anti-mitocôndria."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-110550","number":"110550","sourceNumber":"110550","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma paciente com 60 anos de idade, vai ao médico para avaliação de rotina. Esse,\nao examinar fisicamente a paciente, detecta uma\nnodulação, medindo aproximadamente 5,0\ncm, que se movimenta ao deglutir. Responda às questões abaixo com uma alternativa certa.\nQuais os exames que devem ser solicitados para o diagnóstico correto?","options":{"A":"Ultrassom e a punção por ultrassom.","B":"T3, T4, TSH e T4Live.","C":"Exames pré-operatórios de rotina e RX de tórax.","D":"Avaliação cardiológica de rotina.","E":"Ultrassom e a punção sem ultrassom."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-110577","number":"110577","sourceNumber":"110577","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma paciente com 60 anos de idade, vai ao médico para avaliação de rotina. Esse\nao examinar fisicamente a paciente, detecta uma\nnodulação, medindo aproximadamente 5,0\ncm, que se movimenta ao deglutir. Responda às questões abaixo com uma alternativa certa.\nApós a análise dos resultados de exames na paciente acima, concluído o diagnóstico de\ncarcinoma papilar, qual a conduta?","options":{"A":"Tireoidectomia parcial.","B":"Lobectomia mais istmectomia.","C":"Tireoidectomia total podendo optar também com esvaziamento profilático central.","D":"Tireoidectomia total mais esvaziamento jugular profilático.","E":"Seguiria com ultrassons mensalmente."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-110613","number":"110613","sourceNumber":"110613","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O tumor de Klatskin é de origem:","options":{"A":"Biliar.","B":"Esplênica.","C":"Gástrica.","D":"Pancreática.","E":"Duodenal."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-110551","number":"110551","sourceNumber":"110551","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Neoplasia maligna do 1/3 médio do esôfago, o tipo histológico mais frequente é:","options":{"A":"Carcinoma epidermoide.","B":"Adenocarcinoma.","C":"Linfoma.","D":"Sarcoma.","E":"NDR."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-86846","number":"86846","sourceNumber":"86846","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Efeitos adversos em uso de opioides endovenoso como morfina, por exemplo, é o\nprurido generalizado, relatado em torno de 10% dos casos. Marque a alternativa abaixo da\nterapêutica utilizada como melhor resposta:","options":{"A":"Ondasetron;","B":"Naloxona;","C":"Dexclorfeniramina;","D":"Loratadina;","E":"Maleato de Mepiramina."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-86788","number":"86788","sourceNumber":"86788","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Sobre o rastreamento do câncer de próstata, escolha a alternativa correta.","options":{"A":"O rastreamento com PSA está indicado em\nhomens com mais de 45 anos assintomáticos;","B":"O PSA tem um alto valor preditivo positivo;","C":"O PSA é um exame laboratorial doença-específico;","D":"Recomenda-se repetir o PSA, para confirmação, antes da realização da biópsia;","E":"A associação toque retal/PSA aumenta a\nespecificidade do rastreamento."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-86673","number":"86673","sourceNumber":"86673","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Senhora J., 50 anos, realizou exames de rastreamento e ultrassonografia de abdome\nidentificando tumoração cística no corpo do pâncreas medindo 5 cm. Progrediu investigação e\nrealizou ecoendoscopia com punção aspirativa do conteúdo. Qual marcador tumoral deve ser\ndosado no líquido para suspeita de malignidade?","options":{"A":"CA 19.9.","B":"CA-125.","C":"CEA.","D":"Fosfatal Alcalina.","E":"CA 15.3."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-86678","number":"86678","sourceNumber":"86678","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Correlacione a primeira coluna com a segunda conforme seus conhecimentos: 1. CEA;\n\n2. CA 72.4; 3. CA 19.9; 4. Alfafetoproteína; 5. CA-125. ( ) CA de ovário ( ) Hepatocarcinoma ( ) CA\nde cólon ( ) CA gástrico ( ) CA de pâncreas","options":{"A":"5-4-2-3-1.","B":"4-5-3-2-1.","C":"3-4-5-2-1.","D":"1-3-5-4-2.","E":"5-4-1-2-3."},"answer":"E","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-86681","number":"86681","sourceNumber":"86681","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente do sexo masculino apresenta nódulo tireóideo único, de aproximadamente 2\ncm, acompanhado por adenomegalia cervical, ipsilateral. Calcitonina normal. Qual dos diagnósticos\nabaixo é o mais compatível?","options":{"A":"Adenocarcinoma papilífero.","B":"Adenocarcinoma folicular.","C":"Adenocarcinoma medular.","D":"Adenocarcinoma anaplásico.","E":"Metástase em tireoide."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-158431","number":"158431","sourceNumber":"158431","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"As neoplasias malignas do esôfago podem ser divididas em epiteliais e não-epiteliais.\nDentre as lesões não epiteliais identificam-se,\nEXCETO:","options":{"A":"Sarcomas.","B":"Linfomas.","C":"Apudomas.","D":"Adenocarcinomas.","E":"Melanoma Primário."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-158439","number":"158439","sourceNumber":"158439","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O estômago é a sede de tumores malignos e menos frequentemente de neoplasias\nbenignas. O adenocarcinoma é o tipo mais comum\nde neoplasia maligna do estômago. Uma vez\nestabelecido o diagnóstico, a ressecção cirúrgica se impõe. O estudo dos linfonodos dissecados e\nacometidos permite a classificação segundo a proposta da Union Internationale Contre le Cancer\n(UICC). Marque a CORRETA:","options":{"A":"Nx: sem linfonodos regionais acometidos.","B":"N0: linfonodos regionais não estão disponíveis para classificação.","C":"N3a: 1 a 6 linfonodos regionais não estão disponíveis para classificação.","D":"N2: 3 a 6 linfonodos regionais acometidos.","E":"N1: mais de 15 linfonodos acometidos."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-158441","number":"158441","sourceNumber":"158441","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O carcinoma hepatocelular é a neoplasia primária do fígado mais comum, responsável\npor pelo menos meio milhão de mortes\nanualmente no mundo. Com relação ao tratamento cirúrgico\nde ressecção hepática, marque a INCORRETA:","options":{"A":"A ressecção hepática não é bem tolerada em pacientes cirróticos (Child-Pugh C).","B":"No que se refere a pacientes com função hepática ruim, estes não devem ser operados.","C":"Constitui fator prognóstico negativo: tumores grandes (> 5 cm), multifocais, invasão vascular,\nalto grau de diferenciação celular.","D":"Constitui contraindicação para ressecção hepática a presença de metástases extra-hepáticas\nlinfonodos regionais.","E":"Tempo de protrombina é um dos critérios da classificação Child-Pugh."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-158395","number":"158395","sourceNumber":"158395","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"João da silva, 62 anos, deu entrada no hospital de Emergências apresentando quadro\nde dor abdominal difusa há 10 dias, que veio\naumentando de intensidade, associado à distensão do\nabdome e episódios de vômitos e parada de eliminação de flatos e fezes. Relata também perda de\npeso nos últimos meses, entretanto não sabe precisar o quanto perdeu. Ao exame físico:\nconsciente, desidratado ++\\++++, dispneico, FR: 30 irpm, anictérico, afebril. Abdome globoso,\ndistendido, doloroso à palpação difusamente, timpânico. Toque retal: ausência de fezes, sangue ou\ntumorações em dedo de luva. Marque a assertiva INCORRETA:","options":{"A":"O quadro descrito pode ter diagnóstico sindrômico de câncer de reto com metástase pulmonar, o\nque justificaria a dispneia do paciente.","B":"O toque retal é extremamente importante, pois permite detectar 50% dos tumores de reto e canal\nanal.","C":"A colonoscopia é indicada na presença de sintomas, bem como no seguimento de doentes que,\nrastreados para Cancer Colo Retal, apresentam resultado positivo de pesquisa de sangue oculto\nnas fezes.","D":"As metástases por via sanguínea são pouco comuns e ocorrem com mais frequência no fígado e\nmenos no pulmão, nos rins, nos ossos e no cérebro.","E":"A ressecção cirúrgica deve incluir o tumor e a área de drenagem linfática locorregional\ncorrespondente com margens parietal e distal de no\nmínimo 5 cm para o cólon e 2 cm para o reto\nquando a intenção for curativa."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-108567","number":"108567","sourceNumber":"108567","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Em relação aos tumores estromais (GIST) do aparelho digestivo, marque a alternativa\nCORRETA. A ressecção do GIST gástrico e/ou de reto deve ser:","options":{"A":"Com margem de segurança de no mínimo 5 cm.","B":"Enucleação é suficiente.","C":"Sempre ressecção total do órgão.","D":"Ressecção segmentar.","E":"Não é necessária."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-108586","number":"108586","sourceNumber":"108586","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Marque a resposta INCORRETA em relação ao tumor de Pancoast e a Síndrome de\nHorner?","options":{"A":"O tumor de Pancoast localiza-se em bases pulmonares e a síndrome de Horner tem como\ncaracterística a enoftalmia, ptose palpebral, miose e cianose de extremidades;","B":"O tumor de Pancoast localiza-se posteriormente no ápice dos lobos superiores, junto ao plexo\nbraquial. Comumente causam sintomas e sinais relacionados à infiltração neoplásica das raízes do\noitavo nervo cervical e do primeiro e segundo nervos torácico, de crescimento lento e raramente\nproduz metástases a distância, associa-se à síndrome\n\nde Horner;","C":"Os sintomas mais frequentes são: dor, alteração na temperatura cutânea e atrofia muscular do\nombro e das porções do membro superior secundária ao\n\ncomprometimento nervoso, o tumor pode invadir a pleura e a parede torácica, destruindo a primeira\ne a segunda costelas, causando intensa dor;","D":"Devido o acometimento da cadeia simpática e do gânglio estrelado, é comum o parecimento da\nsíndrome de Horner, que se caracteriza por: enoftalmia unilateral, ptose palpebral, miose e anidrose\nda face e do membro superior.","E":"Todas estão corretas."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-362503","number":"362503","sourceNumber":"362503","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente do sexo feminino, 62 anos, tabagista e diabética, apresenta quadro de icterícia\nprogressiva há cerca de 1 mês, associada a prurido cutâneo e emagrecimento, sendo internada\npara investigação diagnóstica. Seu exame físico apresentava icterícia +++/4 e massa palpável,\nindolor, de contornos bem definidos em HD. Ausência de linfonodos cervicais palpáveis. Sua\navaliação laboratorial evidenciou leucograma e transaminases normais, bilirrubina total: 12mg/dI,\nbilirrubina direta: 11 ,5mg/dI, fosfatase alcalina: 840mg/dl, gama GT: 1.200mg/dl e CA 19-9:\n250U/mI. Optou-se pela solicitação de tomografia computadorizada com contraste venoso que\nevidenciou volumosa dilatação da vesícula biliar e das vias biliares intra e extra-hepáticas, além\nde\nmassa sólida de 5cm em cabeça do pâncreas que invade colédoco distal e tem íntima relação com\nos vasos mesentéricos. Sobre o caso, assinale a alternativa CORRETA:","options":{"A":"Caso observemos envolvimento menor que 180 graus da circunferência da artéria mesentérica\nsuperior, a quimioterapia neoadjuvante pode\ntornar a ressecção tumoral factível.","B":"A definição da conduta frente a esta tumoração depende de biópsia aspirativa por agulha,\nrealizada via radiologia intervencionista.","C":"Não existe possibilidade de tratamento curativo sem a duodenopancreatectomia e, apesar deste\nprocedimento ter morbidade elevada, ele é amplamente acessível já que a maior parte dos\npacientes apresenta doença ressecável ao diagnóstico.","D":"Caso constatada a irressecabilidade do tumor, o tratamento endoscópico paliativo da icterícia\ndeste paciente é contraindicado."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-327237","number":"327237","sourceNumber":"327237","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Sobre a avaliação por imagem de nódulo de Tireoide (NT), assinale a alternativa\nCORRETA:","options":{"A":"Ao diagnosticar um NT menor de 1,0cm em exame ultrassonográfico de rotina, deve-se\nprosseguir investigação com tomografia computadorizada\ncervical, uma vez que esta possibilita\nmelhor caracterização do nódulo quando comparada a ultrassonografia.","B":"Diante de paciente com NT no qual se observam níveis supressos de TSH, a recomendação é\nseguir investigação com cintilografia de tireoide.","C":"Os achados ultrassonográficos de NT associados a maior risco de malignidade incluem:\nhipoecogenicidade, bordas irregulares, diâmetro transverso maior que anteroposterior e presença\nde macrocalcificações.","D":"A tomografia por emissão de pósitrons é superior a tomografia computadorizada, ressonância\nnuclear magnética e cintilografia na avaliação de\nNT."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-327248","number":"327248","sourceNumber":"327248","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente do sexo masculino, 65 anos, sobrepeso, tabagista e diabético, procura\natendimento médico devido a quadro de icterícia progressiva e inapetência há cerca de 1 mês.\nNega dor abdominal ou vômitos. Ao exame físico, apresenta-se em BEG, eupneico, afebril,\nnormotenso, ictérico +++/4, com abdome plano, flácido, indolor à palpação. Sinal de\nCurvoisier-Terrier presente. Sinal de Murphy negativo. Perfil laboratorial: Hematócrito 32%,\nHemoglobina 11g/dl; Bilirrubinas totais: 18mg/dl, Bilirrubina direta: 15mg/dl, Fosfatase alcalina:\n\n634mg/dl e GamaGT: 1.200mg/dl. Foi submetida a USG de abdome que evidenciou ausência de\ncálculos na vesícula biliar, dilatação expressiva do colédoco e massa sólida na cabeça do\npâncreas. Sobre o caso descrito, assinale a alternativa INCORRETA:","options":{"A":"Os dados acima não nos permitem avaliar adequadamente o diagnóstico e o estadiamento da\npatologia em questão, estando indicada tomografia computadorizada helicoidal contrastada com\ncortes finos na topografia pancreática e a dosagem sérica de CA 19-9.","B":"A avaliação do envolvimento dos vasos mesentéricos e veia portal é crucial para a definição da\nmodalidade de tratamento cirúrgico, seja a duodenopancreatectomia curativa ou modalidades\ncirúrgicas paliativas como a anastomose bilio-digestiva e alcoolização do plexo celíaco.","C":"Estudos recentes demonstram que a avaliação tomográfica de massas na cabeça do pâncreas\ntem acurácia superior a ultrassonografia\nendoscópica, sobretudo em nodulações de pequeno\nvolume, limitando a sua indicação para a realização de biópsia de pacientes com doença avançada.","D":"Caso o paciente apresente massas passíveis de ressecção ou em situação borderline, com\ninvasão parcial dos vasos mesentéricos e veia porta, a conduta terapêutica inicial para o caso é a\nquimioterapia neoadvuvante associada ou não a radioterapia."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-327253","number":"327253","sourceNumber":"327253","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente do sexo feminino, 62 anos, tabagista, hipertensa e diabética, com queixa de\nsintomas dispépticos há cerca de 6 meses. Em atendimento médico prévio, foi prescrito Omeprazol\n40mg diário, o qual fez uso por 4 meses, sem resposta satisfatória da sua sintomatologia, evoluindo\ncom anorexia. Evolui com emagrecimento de cerca de 5kg no período. Nega febre, uso crônico de\nanti-inflamatórios não hormonais e história familiar de neoplasias do trato gastrointestinal. Você\nsolicita endoscopia digestiva alta e esta evidencia lesão plana, com ulceração rasa e bordas\nelevadas, de cerca de 2cm, em incisura angularis. Qual das conclusões a seguir sobre o caso\ndescrito é falsa?","options":{"A":"Os dados fornecidos não nos permitem diferenciar com segurança diagnósticos como úlcera\nbenigna, neoplasia gástrica precoce ou neoplasia gástrica avançada.","B":"A observação de anorexia e perda de peso, associada ao fato de ulceração gástrica persistente\na despeito do tratamento com inibidor de bomba\nde prótons pode sugerir etiologia maligna para a\nlesão descrita.","C":"A cromoscopia com uso de corantes, a ecoendoscopia e a injeção de solução salina na camada\nsubmucosa abaixo da lesão podem fornecer\ndados referentes a possível ressecabilidade\nendoscópica da lesão.","D":"Uma vez que a endoscopia não evidenciou lesão tipo Borrmann IV, a conduta mais segura é o\ntratamento empírico para Helicobacter pylori, a troca do omeprazol pelo esomeprazol e a repetição\nda endoscopia após 4 meses."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-298220","number":"298220","sourceNumber":"298220","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente do sexo feminino, 42 anos, queixa dor abdominal de início súbito em\nhipocôndrio direito associada a mal-estar e\ntontura, há cerca de 2 horas. Nega episódios anteriores,\nfebre, vômitos e sintomas urinários. Nega comorbidades e a única medicação que faz uso regular é\nde anticoncepcional oral há 20 anos. Apresenta-se em BEG, anictérica, hipocorada, FC: 110bpm,\nFR: 26irpm e P.A.: 90x70mmHg, que normalizaram após infusão em bolus de 1.000ml de Ringer\nLactato. Seu abdome é plano, flácido, moderadamente doloroso à palpação do HD, sem irritação\nperitoneal. Leucograma normal, hemoglobina 7g/dl, hematócrito 22%. Demais exames laboratoriais\nnormais. Foi submetida a tomografia de abdome que evidenciou fígado de aspecto homogêneo,\nlesão tumoral de 6cm em lobo direito do fígado com sinais de sangramento recente e moderada\nquantidade de líquido livre na cavidade abdominal. Sobre o caso descrito, assinale a alternativa\nCORRETA:","options":{"A":"O caso ilustra clássica complicação de hiperplasia nodular focal, estando indicada a ressecção\ntumoral de urgência.","B":"Após estabilização do quadro de sangramento, há indicação de ressecção tumoral eletiva devido\na considerável potencial de malignidade.","C":"O quadro de sangramento sugere fortemente o diagnóstico de hemangioma hepático, estando\nindicado tratamento quimioterápico após recuperação do quadro urgente.","D":"A paciente deve ser submetida a colonoscopia para investigação de neoplasia primária de cólon."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-286722","number":"286722","sourceNumber":"286722","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente do sexo feminino, 45 anos, vem à consulta porque palpou nodulação na\nregião anterior do pescoço. Nega dor local,\ndisfagia e disfonia. Nega histórico de neoplasias na\nfamília e de doenças cervicais prévias, porém refere discreta perda de peso e fadiga progressiva há\ncerca de 1 ano. Ao exame físico, a paciente apresenta-se ansiosa, emagrecida, taquicárdica e\nhipertensa. Apresenta pequeno nódulo sólido palpável em lobo direito da tireoide, que é móvel à\ndeglutição. Não há linfadenomegalia cervical palpável. Solicitada a dosagem dos hormônios\ntireoidianos, observou-se elevados níveis de T3 e T4 livre e baixos níveis de TSH. Sobre a\ncondução deste caso, assinale a alternativa CORRETA:","options":{"A":"Os dados acima nos permitem afirmar que a ultrassonografia provavelmente evidenciará nódulo\nhipoecogênico de margens irregulares com microcalcificações, confirmando a tireoidectomia total\ncomo próximo passo na conduta desta paciente.","B":"Caso a cintilografia confirme nodulação hipercaptante com tireoide hipocaptante, a lobectomia\ntireoidiana seria opção terapêutica adequada para o caso.","C":"A Punção Aspirativa por Agulha Fina (PAAF) guiada por ultrassom é contraindicada no caso\ndevido a possibilidade de carcinoma medular.","D":"A ressonância magnética cervical deve substituir a ultrassonografia neste caso, já que evidencia\ncom maior acurácia o envolvimento da\ntraqueia e esôfago na doença, além de apresentar maior\nsensibilidade para diagnósticos diferenciais."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-256583","number":"256583","sourceNumber":"256583","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Sobre o câncer gástrico difuso, as afirmações estão CORRETAS, EXCETO:","options":{"A":"Pode acometer pacientes mais jovens.","B":"Acometem mais o corpo gástrico e o cárdia.","C":"Pode estar associado ao grupo sanguíneo ?O?.","D":"Tendência a invadir precocemente toda a espessura da parede gástrica."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-256587","number":"256587","sourceNumber":"256587","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Qual das alternativas abaixo NÃO é considerada de alto risco para malignidade em\npacientes com nódulos tireoidianos diagnosticados ao ultrassom?","options":{"A":"Passado de exposição à radiação na infância ou adolescência.","B":"Nódulo sólido-cístico.","C":"Nódulo incidentalmente detectado no FDG-PET (captação focal).","D":"História familiar de câncer de tireoide."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-256588","number":"256588","sourceNumber":"256588","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Sobre o rastreio do câncer coloretal (CCR), qual das opções não se relaciona aos\npacientes com risco intermediário de desenvolvimento de CCR?","options":{"A":"Idade inferior a 50 anos","B":"Paciente sem história de adenoma, pólipo séssil ou CCR","C":"Paciente sem história de doença inflamatória intestinal","D":"Paciente com história familiar negativa para CCR"},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-256589","number":"256589","sourceNumber":"256589","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"A incidência e mortalidade de câncer gástrico tem reduzido substancialmente em\ngrande parte do mundo desenvolvido nas\núltimas décadas. Entretanto, cânceres do trato\ngastrointestinal superior originados no estômago, esôfago ou junção esofagogástrica ainda\nconstituem o maior problema mundial de saúde, especialmente nos países de baixa e média renda.\nGlobalmente, havia uma estimativa de 1,03 milhão de casos resultando em 780.000 mortes em\n2018, tornando o câncer gástrico o 5º câncer diagnosticado mais frequente e o 3º relacionado a\nmortes no mundo. Mais de 95% dos cânceres gástricos são Adenocarcinomas, que são\nclassificados baseados na localização anatômica, como Distal e Proximal, e tipo histológico, como\nDifuso e Intestinal. Sobre o câncer gástrico intestinal, qual a questão que não mostra um fator\nambiental relacionado ao risco desse tipo de câncer gástrico?","options":{"A":"Ingesta rica em sal","B":"Tabagismo","C":"Associação com álcool","D":"Infecção pelo Helicobacter pilory"},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-252227","number":"252227","sourceNumber":"252227","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"No diagnóstico precoce do câncer de tireoide é importante a avaliação do nódulo\ntireoidiano de forma a estabelecer riscos. Para tal, devem ser utilizados métodos que sejam\nacurados, precisos, seguros e de baixo custo. Sabendo disso, qual o método que melhor se\nencaixa nessas características?","options":{"A":"Punção aspirativa por agulha fina (PAAF) do nódulo.","B":"Captação e cintilografia da tireoide com radioisótopo.","C":"Ultrassonografia de tireoide.","D":"Dosagem de TSH, calcitonina e tireoglobulina séricas."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-252230","number":"252230","sourceNumber":"252230","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente feminino, 32 anos, solteira, natural e procedente de Manacapuru. Há 3 meses\nem exames de controle com a ginecologista\nrealizou ultrassonografia de tireoide que evidenciou no\nlobo direito um nódulo de 1,2 cm, hipoecoico, bordas regulares, limites precisos, sem\nmicrocalcificação, vascularização apenas periférica (CHAMMAS II). Ao exame físico: PESCOÇO:\ntireoide não palpável e sem linfonodomegalia. Realizou a punção guiada por ultrassom e teve o\nresultado da citologia de Bethesda I. Qual o próximo passo?","options":{"A":"Repetir a punção da tireoide em 3 meses.","B":"Tireoidectomia total.","C":"Tireoidectomia parcial.","D":"Iodoterapia com 100 mCi."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-252231","number":"252231","sourceNumber":"252231","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O câncer de pâncreas é a quarta causa mais comum de morte relacionada ao câncer\nentre homens e mulheres nos Estados Unidos\n(EUA). A sua incidência aumentou de 1999 a 2008,\npossivelmente por causa do aumento da prevalência de obesidade, idade da população e outros\nfatores desconhecidos. Qual a opção CORRETA sobre o rastreio dos tumores pancreáticos?","options":{"A":"Pacientes diabéticos, com diagnóstico acima de 50 anos, devem ser seguidos anualmente.","B":"Não há recomendação de rastreio para pacientes assintomáticos.","C":"Solicitação anual de biomarcador (CA-19-9) a partir dos 50 anos.","D":"Rastreio anual para pacientes com Síndrome de Lynch."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-208431","number":"208431","sourceNumber":"208431","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente do sexo masculino, 55 anos, foi submetido a colectomia direita há 1 ano para\ntratamento de adenocarcinoma de cólon ascendente. Durante seu acompanhamento, o cirurgião\nobservou elevação das titulações de CEA e solicitou ultrassonografia que evidenciou 3 nódulos\nsólidos em segmentos V e VI do fígado. Assinale a alternativa INCORRETA:","options":{"A":"História de alcoolismo, doenças hepáticas e sintomatologia neurológica, assim como a\ninvestigação de ascite, dosagens de bilirrubina, albumina e TAP estão indicados para o caso.","B":"Os dados acima nos permitem concluir que não há curabilidade possível para o caso, restando o\ntratamento cirúrgico paliativo como melhor opção terapêutica.","C":"A tomografia com contraste venoso e a ressonância magnética com estudo dinâmico com\ncontraste hepatobiliar são os exames de imagem\npré-operatórios de escolha para a avaliação da\nressecabilidade das lesões hepáticas.","D":"O paciente deve se beneficiar com a associação de quimioterapia adjuvante após a ressecção\ndas lesões hepáticas."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-176061","number":"176061","sourceNumber":"176061","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Feminino, 50 anos, chega à consulta muito ansiosa devido a ?massa no pescoço?.\nHistórico familiar de irmão com câncer de tireoide. À palpação, nota-se nodulação em região\ncervical esquerda, de mais ou menos 2,0 cm, discretamente endurecida, móvel, indolor. Traz\ndosagem TSH = 0,11 (VR = 0,5-4,5 mUI/L) e T4 livre = 1,7 ng/dl (VR = 0,7-1,5 ng/dl). Qual o\npróximo passo na avaliação desta paciente?","options":{"A":"Solicitação de cintilografia de tireoide.","B":"Dosagem de tireoglobulina e calcitonina.","C":"Solicitação de Punção Aspirativa por Agulha Fina (PAAF) do nódulo.","D":"Solicitação de ultrassonografia de tireoide."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-176103","number":"176103","sourceNumber":"176103","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente do sexo masculino, 55 anos, apresenta disfagia progressiva de sólidos para\nlíquidos há 4 meses, associada a perda ponderal. Traz consigo esofagograma contrastado que\nrevela imagem de subtração com contornos irregulares em terço médio do esôfago. Marque a\nalternativa CORRETA:","options":{"A":"A lesão é compatível com leiomioma e deve-se proceder à esofagectomia.","B":"Deve-se realizar endoscopia digestiva alta com biópsia, sendo o resultado mais provável\ncarcinoma epidermoide.","C":"Essa imagem se trata de uma provável complicação do esôfago de Barrett.","D":"Uma boa opção terapêutica é realizar endoscopia associada à dilatação com balão."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-176009","number":"176009","sourceNumber":"176009","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Qual o sintoma mais comum no câncer de esôfago?","options":{"A":"Disfagia e perda ponderal.","B":"Tosse e vômitos.","C":"Odinofagia e tosse.","D":"Hematêmese e pneumonia de aspiração."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-176017","number":"176017","sourceNumber":"176017","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Qual a localização mais comum do tumor estromal gastrointestinal?","options":{"A":"Intestino delgado.","B":"Mesentério.","C":"Esôfago.","D":"Estômago."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-151896","number":"151896","sourceNumber":"151896","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 69 anos, com diagnóstico de carcinoma de células escamosas, apresenta\nna tomografia de tórax massa tumoral de 5 cm de\ndiâmetro, situada em brônquio central esquerdo e\ndistando 4 cm da carina. Sobre esse caso, assinale a alternativa INCORRETA:","options":{"A":"A fibrobroncoscopia, nesse caso, tem indicação tanto para diagnóstico do tumor quanto para\nestadiamento.","B":"Se o paciente realizar um PET-scan e este mostrar ausência de lesões com hipercaptação de\nglicose, o tratamento indicado será o cirúrgico, com melhor prognóstico.","C":"Habitualmente, todas as metástases do câncer de pulmão são sintomáticas, o que geralmente\ntorna a história clínica e o exame físico\ngrandes marcadores da disseminação da doença.","D":"Caso o paciente apresente linfonodo supraclavicular palpável à esquerda, este deve ser\nacessado para pesquisa de acometimento neoplásico, pois sua presença torna o tumor\npotencialmente inoperável."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-151916","number":"151916","sourceNumber":"151916","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente do sexo masculino, 58 anos, vem à consulta queixando-se de quadro de\nicterícia progressiva há cerca de 1 mês,\nassociada à plenitude pós-prandial, principalmente após\ningesta de alimentos sólidos, desconforto abdominal e perda de peso não quantificada. Nega crises\nde dor abdominal aguda. Ao exame físico, apresentava-se emagrecido, desidratado, ictérico +++/4,\nhemodinamicamente estável. Seu abdome é plano, flácido, indolor à palpação, com vesícula biliar\npalpável. Traz consigo exames laboratoriais que evidenciaram leucograma de 5.600; hematócrito\nde 30%; hemoglobina de 10 g/dl; TGO e TGP discretamente elevadas; bilirrubina total de 12 mg/dl;\nbilirrubina conjugada de 10,5 mg/dl; bilirrubina não conjugada de 1,5 mg/dl; e dosagem de CA =\n\n19-9: 225 mg/dl. Sobre o caso acima, assinale a alternativa CORRETA:","options":{"A":"A técnica cirúrgica de escolha depende do diagnóstico histopatológico, estando indicada a\npunção aspirativa por agulha fina guiada por TC.","B":"A TC helicoidal com cortes finos é o exame de imagem de escolha para diagnóstico, porém não\navalia satisfatoriamente o grau de ressecabilidade da lesão.","C":"Caso haja envolvimento importante dos vasos mesentéricos superiores pela lesão, a\nanastomose biliodigestiva é opção de tratamento para o caso.","D":"A ultrassonografia endoscópica é opção adequada para avaliação local da lesão e envolvimento\nde estruturas adjacentes."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-151878","number":"151878","sourceNumber":"151878","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Define-se como carcinoma gástrico precoce:","options":{"A":"Limitado à mucosa e submucosa com linfonodo não contaminado.","B":"Limitado somente à mucosa e sem envolvimento de linfonodo.","C":"Limitado à mucosa e submucosa, independentemente do estado do linfonodo.","D":"Limitado à parede gástrica, sem invadir a serosa ou órgãos vizinhos."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-139096","number":"139096","sourceNumber":"139096","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"As diretrizes atuais da American Cancer Society classificam a triagem para a população\nde risco médio de desenvolvimento do câncer\ncolorretal: assintomática, sem histórico familiar de\ncarcinoma colorretal, nenhuma síndrome familiar a partir de:","options":{"A":"35 anos.","B":"40 anos.","C":"50 anos.","D":"60 anos."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-129795","number":"129795","sourceNumber":"129795","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"OGM, 67 anos, masculino, procedência Santa Isabel do Rio Negro-AM, vem evoluindo\ncom disfagia progressiva com piora extrema há\n90 dias, aproximadamente, associada a um quadro\nde tosse produtiva e sialorreia intensa. Concomitante ao quadro, foi tratado de pneumonia com\ninternação recente. Emagrecimento de 15 kg. Constipação de 7 dias desde a faixa dos seus 30 - 40\nanos, aliviando com laxativos e enteroclismas. Cardiopatia, fazendo uso de anti-arrítmicos. Nega\nhematêmese e ou melena; fumante desde os 16 anos, alcoolismo crônico (cachaça e cerveja). Ao\nexame físico apresenta-se: MEG, emagrecido, dispneico, com sialorreia freqüente, sem sangue de\npermeio, anictérico, afebril. Anemia +/+++, língua saburrosa, sem linfonodomegalia, perda muscular\n(cervical, torácica, abdominal, mmiis): sem linfonomegalia cervical e ou fúrculas; ausculta pulmonar\nnotadamente caracterizada por estertores creptantes em terço médio do HTE, arritmias cardíacas\nesparsas; abdome distendido, desconfortável, sem cicatrizes, indolor, sem visceromegalias,\ntimpanismo em trajeto colônico. Toque retal apresentando volumoso fecaloma, pétreo;\n\ndedo-de-luva sem sangue. Submetido à radiografia do esôfago com contrastre iodado que revelou\nfistula esôfago-brônquica em contiguidade com o\nsegmento de pulmão esquerdo; endoscopia\ndigestiva alta apresentando uma lesão estenosante (impedia a passagem do aparelho), a 25\ncentímetros da ADS; laudo anátomo-patológico revelou carcinoma escamocelular; TC de tórax:\npresença de linfonodomegalias paratraqueais e interbrônquios circundando uma massa sólida de 5\ncm no seu maior diâmetro em topografia de hilo pulmonar esquerdo. Clíster opaco: dolicocolon e\nfecaloma segmentar em sigmoide e reto. Pelo exposto e considerando o manejo clínico dos\ntumores do esôfago, responda a questão: Considerando a inoperabilidade do caso acima, são\nmétodos paliativos para os tumores do esôfago, EXCETO:","options":{"A":"Terapia Nutricional Parenteral.","B":"Stent Esofágico.","C":"Quimioradioterapia.","D":"Jejunostomia e Esôfago-Gastro-Coloplastia."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-129784","number":"129784","sourceNumber":"129784","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Desde muitas décadas passadas, vem sendo observada uma diminuição espetacular\nna taxa de morte e na incidência de câncer\ngástrico nos EUA e nos países desenvolvidos do\nOcidente. Considerando a classificação de Lauren, qual a forma de câncer que mais se reduziu\nneste processo de involução?","options":{"A":"Carcinoma em \"anel de sinete\".","B":"Tipo difuso.","C":"Tipo intestinal.","D":"Carcinoide."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-103864","number":"103864","sourceNumber":"103864","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Mais comum, tumor primário maligno peritoneal:","options":{"A":"sarcomas.","B":"tumor desmoide.","C":"pseudomixoma peritoneal.","D":"mesotelioma maligno."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-107891","number":"107891","sourceNumber":"107891","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 55 anos, sexo masculino, portador de cirrose hepática pelo VHC,\napresenta-se no seu consultório com história\nde seis semanas com fadiga e distensão abdominal.\nPortador de varizes de esôfago. Exames bioquímicos: bilirrubinas: 2,3mg/dl (normal < 1,0);\nfosfatase alcalina = 176 U/L (normal < 150); AST = 165 U/L (normal < 36); ALT = 90 U/L (normal <\n36) albumina sérica = 2,9g/dl (normal =3,5-5,0) e alfafetoproteína = 224 ng/dl (normal < 10). Diante\ndessa situação, qual seria a sua indicação?","options":{"A":"Ultrassonografia do abdômen superior com Doppler do sistema portal.","B":"Tomografia do abdômen com contraste endovenoso.","C":"Colangiopancreatografia retrógrada endoscópica (CPRE).","D":"Biópsia hepática."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-107661","number":"107661","sourceNumber":"107661","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente do sexo masculino, 54 anos, será submetido à gastrectomia subtotal por\nadenocarcinoma de estômago. É diabético, hipertenso e faz uso de glibenclamida, losartana e AAS,\nalém do uso crônico de prednisona para o tratamento de artrite reumatoide. Sobre os cuidados\n\npré-operatórios deste paciente, assinale a alternativa INCORRETA:","options":{"A":"O paciente deve suspender o uso do hipoglicemiante oral durante o período da internação e seu\ncontrole glicêmicos será feito com medidas regulares de glicemia capilar e uso de insulina NPH de\nacordo com o resultado das glicemias.","B":"A paciente deve continuar o uso do anti-hipertensivo oral, mesmo no dia do procedimento\ncirúrgico e no pós-operatório imediato.","C":"A Prednisona deve ser suspensa no dia da cirurgia, porém devemos substitui-la por\nhidrocortisona venosa devido ao risco de insuficiência adrenal aguda.","D":"O uso do AAS deve ser suspenso 7 dias antes do procedimento cirúrgico devido ao risco de\nsangramento, porém há indicação precisa do uso de heparina de baixo peso molecular subcutânea\ndurante a internação."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-107826","number":"107826","sourceNumber":"107826","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente do sexo masculino, 28 anos, deu entrada no pronto atendimento\napresentando quadro de dor abdominal tipo\ncólica, difusa, progressiva há cerca de 5 dias,\nassociado à parada de eliminação de gases e fezes. Nega febre. Refere náuseas e vômitos\namarelados, de odor fétido. Encontra-se em regular estado geral, taquicárdico, discretamente\nhipotenso, dispneico e desidratado. Refere não urinar há cerca de 8 horas. Seu abdome é bastante\ndistendido, difusamente doloroso à palpação, sem irritação peritoneal. Ruídos hidroaéreos em\nestalido metálico. O toque retal evidenciou massa estenosante há cerca de 10 cm acima do rebordo\nanal. Referente à avaliação e proposta terapêutica deste paciente, assinale a alternativa\nINCORRETA:","options":{"A":"Apesar de não haver irritação peritoneal, podemos afirmar que há indicação de tratamento\ncirúrgico paliativo urgente.","B":"Acidose metabólica, pneumoperitôneo e elevação de escórias nitrogenadas são achados\nesperados na avaliação complementar do caso\nacima.","C":"Os dados acima não nos permitem afirmar se há possibilidade de tratamento curativo definitivo\npara este paciente.","D":"Tanto a colostomia em alça quanto a colostomia terminal são opções para o tratamento cirúrgico\ninicial do paciente acima."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-107945","number":"107945","sourceNumber":"107945","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente do sexo masculino, 55 anos, tabagista inveterado, apresenta quadro de tosse\ncrônica, dispneia leve e perda de peso há cerca de 1 mês. Refere 1 episódio de hemoptise. Ao\nexame físico, apresentava linfonodo supraclavicular e sibilos à ausculta pulmonar. A radiografia de\ntórax evidenciou massa hilar à direita, volumosa e derrame pleural moderado. Foi então submetido\nà broncoscopia com biópsia que evidenciou neoplasia indiferenciada com células em \"grão de\naveia\". Sobre as características deste tumor, seu prognóstico e tratamento, assinale a alternativa\nINCORRETA:","options":{"A":"A mediastinoscopia, a tomografia de tórax e crânio são exames que podem auxiliar o\nestadiamento da lesão.","B":"Os dados apresentados nos permitem afirmar que o prognóstico do paciente é muito ruim,\nestando indicado apenas o tratamento paliativo.","C":"Mesmo que não haja metástases à distância, a doença é provavelmente classificada como\navançada.","D":"O tratamento de escolha para o caso é a mediastinoscopia com linfadenectomia e a ressecção\npulmonar."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-107922","number":"107922","sourceNumber":"107922","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente do sexo feminino, 20 anos, vem ao consultório queixando-se de pequena\nnodulação palpável, de cerca de 12 mm e\nconsistência firme, em região anterior do pescoço, em\ntopografia do lobo esquerdo da tireoide. A paciente nega dor, disfonia, disfagia e dispneia. Refere\nque uma tia apresentou quadro semelhante (diagnóstico ignorado pela paciente) com necessidade\nde tratamento cirúrgico. O médico que a examinou observou, ainda, linfonodo palpável em cadeia\ncervical esquerda. Analise as assertivas abaixo e assinale a alternativa CORRETA:\n\nI. O TSH sérico de valor normal não exclui a possibilidade de doença maligna;\n\nII. Já que não há queixa clínica de alerta (dor, disfagia, dispneia e disfonia), podemos afirmar\nque a\nmelhor conduta para o caso seria observação clínica sem maior investigação complementar;\n\nIII. A ultrassonografia da tireoide com Doppler tem maior sensibilidade para suspeita de\nmalignidade que a ressonância magnética cervical;\n\nIV. A Punção Aspirativa por Agulha Fina (PAAF), tanto do nódulo quanto do linfonodo, é o método\npadrão-ouro para o diagnóstico da possível malignidade do caso acima.","options":{"A":"Há apenas uma assertiva incorreta.","B":"Há apenas uma assertiva correta.","C":"As assertivas II e III são incorretas.","D":"As assertivas II e IV são corretas."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-87450","number":"87450","sourceNumber":"87450","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente do sexo feminino, 45 anos, chega ao pronto-socorro com quadro de\nhematêmese. Apresenta história de epigastralgia\nem queimação com evolução de vários anos e\nassociação com alimentos ácidos e com temperos fortes. Evoluiu há cerca de 4 meses com\naumento discreto da dor e plenitude pós-prandial progressiva. Vômitos alimentares. Perda de peso\nde 15 kg nos últimos 2 meses. Ao exame físico, apresenta-se ansiosa, pálida, emagrecida e\nanictérica. O abdome é plano, flácido, com massa palpável pouco dolorosa em epigástrio. Não\nhavia linfadenomegalias. Toque retal sem alterações. A paciente acima foi submetida à laparotomia\nexploradora, que evidenciou massa gástrica volumosa a nível de região pilórica não aderida a\nplanos profundos, moderada quantidade de ascite, linfonodomegalia adjacente à aorta abdominal e\nlesões nodulares difusas em peritônio e mesocólon. Assinale a alternativa CORRETA:","options":{"A":"Já que a massa gástrica é restrita ao antro e não invade planos profundos, podemos afirmar que\nhá chance de cura para esta paciente.","B":"A presença de ascite não interfere no prognóstico desta paciente.","C":"A gastrectomia parcial não faz parte das opções terapêuticas para esta paciente.","D":"Já que o paciente não apresentava linfonodo de Virchow, linfonodo de Sister Mary Joseph ou\nprateleira de Blummer, o prognóstico é bom.","E":"A USG no estadiamento pré-operatório indicaria provável tratamento paliativo."},"answer":"E","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-81091","number":"81091","sourceNumber":"81091","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"<p>Paciente com 75 anos, hipertenso, diabético, com sequela de AVC e IAM com\nmenos de 6 meses. Apresenta câncer de\ncabeça de pâncreas, Estadiamento clínico (Ec) T1N0M0,\nsem invasão de estruturas adjacentes. Responda a alternativa CORRETA abaixo:</p>","options":{"A":"Irressecável, encaminhado para neoadjuvância e reavaliação.","B":"Inoperável, encaminhado para quimioterapia paliativa.","C":"Inoperável, encaminhado para adjuvância.","D":"Irressecável, encaminhado para quimioterapia paliativa.","E":"Irressecável, encaminhado para adjuvância."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-81111","number":"81111","sourceNumber":"81111","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"<p>Paciente do sexo feminino vem ao consultório do cirurgião portando endoscopia\ndigestiva alta com diagnóstico de processo\nmitótico ulceroinfiltrativo em pequena curvatura gástrica,\nsem confirmação histopatológica até o momento. Ao exame físico, apresenta-se emagrecida,\nhipocorada ++/4, anictérica e normotensa. Apresenta linfonodo palpável supraclavicular esquerdo.\nSeu abdome é plano, flácido, indolor à palpação. Não há massa epigástrica palpável, mas\nevidencia-se discreta ascite à palpação. Toque retal normal. Assinale a alternativa\nINCORRETA:</p>","options":{"A":"Espera-se que a biópsia da lesão revele adenocarcinoma gástrico.","B":"Os dados clínicos acima nos permitem afirmar que se trata de neoplasia gástrica incurável,\nporém não há dados suficientes para avaliar\nsua ressecabilidade.","C":"O toque retal normal exclui a possibilidade de tumoração de Krukenberg no caso acima.","D":"A paciente acima pode evoluir com hemorragia digestiva alta ou abdome agudo perfurativo.","E":"O próximo passo para estadiamento adequado deste paciente é a tomografia computadorizada."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-81957","number":"81957","sourceNumber":"81957","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"São fatores de risco para carcinoma de vesícula, EXCETO:","options":{"A":"Cálculos biliares.","B":"Vesícula em porcelana.","C":"Cistos de colédoco.","D":"Fístula biliar.","E":"Colangite esclerosante primária."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-354415","number":"354415","sourceNumber":"354415","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Mulher, 65 anos de idade, procura o ambulatório de cirurgia geral com queixa de azia e\nempachamento há cinco meses, com piora nas últimas semanas e perda ponderal. Refere dor em\nepigástrio após a alimentação. Nega náusea, vômitos ou hematêmese. Ao exame físico, bom\nestado geral, descorada +1/+4, FC: 68bpm, PA: 124x72mmHg; abdome plano, flácido, com dor à\npalpação profunda de epigástrio e com descompressão brusca negativa; toque retal sem\nalterações. A paciente foi submetida à endoscopia digestiva alta (imagem da endoscopia). Diante\ndesse caso clínico, indique a principal suspeita diagnóstica para a paciente:","options":{"A":"Úlcera péptica.","B":"Neoplasia maligna de estômago.","C":"Gastrite erosiva intensa.","D":"Tumor estromal (GIST) ulcerado."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-354416","number":"354416","sourceNumber":"354416","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Mulher, 65 anos de idade, procura o ambulatório de cirurgia geral com queixa de azia e\nempachamento há cinco meses, com piora nas últimas semanas e perda ponderal. Refere dor em\nepigástrio após a alimentação. Nega náusea, vômitos ou hematêmese. Ao exame físico, bom\nestado geral, descorada +1/+4, FC: 68bpm, PA: 124x72mmHg; abdome plano, flácido, com dor à\npalpação profunda de epigástrio e com descompressão brusca negativa; toque retal sem\nalterações. A paciente foi submetida à endoscopia digestiva alta (imagem da endoscopia). Indique\no exame complementar que deve ser realizado em associação com a endoscopia digestiva alta:","options":{"A":"Tomografia computadorizada do abdome com contraste","B":"Ultrassonografia endoscópica.","C":"Biópsia da lesão.","D":"Pesquisa de H. Pylori"},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-354417","number":"354417","sourceNumber":"354417","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Mulher, 65 anos de idade, procura o ambulatório de cirurgia geral com queixa de azia e\nempachamento há cinco meses, com piora nas últimas semanas e perda ponderal. Refere dor em\nepigástrio após a alimentação. Nega náusea, vômitos ou hematêmese. Ao exame físico, bom\nestado geral, descorada +1/+4, FC: 68bpm, PA: 124x72mmHg; abdome plano, flácido, com dor à\npalpação profunda de epigástrio e com descompressão brusca negativa; toque retal sem\nalterações. A paciente foi submetida à endoscopia digestiva alta (imagem da endoscopia).\n\nIdentifique a conduta mais adequada, caso a suspeita diagnóstica seja confirmada.","options":{"A":"Orientação nutricional e prescrever inibidor de bomba de próton.","B":"Prescrever inibidor de bomba de próton, amoxicilina e claritromicina.","C":"Realizar arteriografia com embolização.","D":"Realizar estadiamento com tomografia computadorizada de tórax e abdome."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-324674","number":"324674","sourceNumber":"324674","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente, sexo feminino, 65 anos de idade, procura o Pronto Socorro por\nempachamento e distensão abdominal há cinco\ndias. A paciente apresentou náuseas e alguns\nepisódios de vômitos nas últimas 24 horas. Relata, também, hiporexia, perda de peso e obstipação\nprogressiva, há três meses, não sendo investigada previamente. A paciente realizou artroplastia\ntotal de quadril esquerdo há 5 anos. Ao exame físico, regular estado geral, corada, desidratada, T\naxilar: 36ºC, FC: 88bpm, PA: 128x78mmHg, FR: 24imp; ausculta cardíaca e respiratória sem\nalterações; abdome distendido, tenso, com dor à palpação difusa e com descompressão brusca\nnegativa; toque retal sem alterações. Foi realizada radiografia de abdome. Diante desse caso\nclínico e da análise do exame de imagem, indique a principal suspeita etiológica que levou a\npaciente a procurar o Pronto Socorro.","options":{"A":"Aderência intestinal.","B":"Volvo de sigmoide.","C":"Neoplasia maligna de cólon.","D":"Fecaloma."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-324675","number":"324675","sourceNumber":"324675","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente, sexo feminino, 65 anos de idade, procura o Pronto Socorro por\nempachamento e distensão abdominal há cinco\ndias. A paciente apresentou náuseas e alguns\nepisódios de vômitos nas últimas 24 horas. Relata, também, hiporexia, perda de peso e obstipação\nprogressiva, há três meses, não sendo investigada previamente. A paciente realizou artroplastia\ntotal de quadril esquerdo há 5 anos. Ao exame físico, regular estado geral, corada, desidratada, T\naxilar: 36ºC, FC: 88bpm, PA: 128x78mmHg, FR: 24imp; ausculta cardíaca e respiratória sem\nalterações; abdome distendido, tenso, com dor à palpação difusa e com descompressão brusca\nnegativa; toque retal sem alterações. Foi realizada radiografia de abdome. Indique o exame\ncomplementar que deveria ter sido realizado há três meses, no momento em que se iniciaram os\nprimeiros sintomas.","options":{"A":"Tomografia computadorizada com contraste.","B":"Colonoscopia.","C":"Radiografia de abdome.","D":"Ultrassonografia de abdome."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-324676","number":"324676","sourceNumber":"324676","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente, sexo feminino, 65 anos de idade, procura o Pronto Socorro por\nempachamento e distensão abdominal há cinco\ndias. A paciente apresentou náuseas e alguns\nepisódios de vômitos nas últimas 24 horas. Relata, também, hiporexia, perda de peso e obstipação\nprogressiva, há três meses, não sendo investigada previamente. A paciente realizou artroplastia\ntotal de quadril esquerdo há 5 anos. Ao exame físico, regular estado geral, corada, desidratada, T\naxilar: 36ºC, FC: 88bpm, PA: 128x78mmHg, FR: 24imp; ausculta cardíaca e respiratória sem\nalterações; abdome distendido, tenso, com dor à palpação difusa e com descompressão brusca\nnegativa; toque retal sem alterações. Foi realizada radiografia de abdome. Indique a conduta\ncirúrgica mais adequada, caso a paciente não apresente melhora com o tratamento clínico\ninstituído no Pronto Socorro.","options":{"A":"Lavagem intestinal no centro cirúrgico.","B":"Peritoneostomia descompressiva.","C":"Videolaparoscopia para reversão do volvo.","D":"Retossigmoidectomia com colostomia."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-283846","number":"283846","sourceNumber":"283846","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O tipo histológico de neoplasia maligna do estômago mais frequente no Brasil é:","options":{"A":"Linfoma.","B":"Sarcoma.","C":"Adenocarcinoma.","D":"Carcinoma escamocelular.","E":"Tumor estromal (GIST maligno)."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-281877","number":"281877","sourceNumber":"281877","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"São o terceiro tipo de tumor sólido mais comum em crianças. Originam-se do\nmesênquima embrionário e representam mais da metade do total de sarcomas não ósseos de\ncrianças e adolescentes.","options":{"A":"Angiossarcomas.","B":"Lipossarcomas.","C":"Rabdomiossarcomas.","D":"Sarcomas alveolares."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-249717","number":"249717","sourceNumber":"249717","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Sobre as neoplasias gástricas, é correto afirmar que","options":{"A":"o adenocarcinoma corresponde a 50% dos tumores malignos do estômago.","B":"os tumores gástricos no antro devem ser sistematicamente tratados com gastrectomia total.","C":"o subtipo intestinal, na classificação de Lauren, tem disseminação predominantemente linfática.","D":"a esplenectomia associada à gastrectomia não está associada ao aumento de morbimortalidade\ne deve ser feita com objetivo de aumentar a\nchance de cirurgia R0.","E":"o consumo aumentado de nitratos, a infecção pelo Helicobacter Pylori, a cirurgia gástrica prévia,\no tabagismo e o gênero masculino são fatores\nassociados ao risco aumentado de desenvolvimento\nde câncer gástrico."},"answer":"E","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-249724","number":"249724","sourceNumber":"249724","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"A alternativa que contém a patologia mais frequentemente relacionada ao carcinoma\npulmonar de pequenas células é:","options":{"A":"Dislipidemia.","B":"Diabetes mellitus.","C":"Sarcoma de Kaposi.","D":"Hipocalemia primária.","E":"Síndrome da Secreção Inapropriada de Hormônio Antidiurético (SIADH)."},"answer":"E","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-250001","number":"250001","sourceNumber":"250001","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Sobre neoplasias pulmonares, assinale a correta:","options":{"A":"Nódulo bem circunstrito, com calcificação periférica de padrão irregular com imagem tipo\n\n?pipoca? é sugestiva de hamartoma pulmonar, neoplasia de caráter maligno.","B":"Nódulo bem circunstrito, com calcificação periférica de padrão irregular com imagem tipo\n\n?pipoca? é sugestivo de hamartoma pulmonar, neoplasia de caráter benigno.","C":"Nódulo irregular, espiculado, com calcificação central, de disposição pleural é patognomômico\nde carcinoma espinocelular.","D":"Nódulo irregular, espiculado, com calcificação central, de disposição pleural é patognomômico\nde carcinoma de pequenas células."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-250003","number":"250003","sourceNumber":"250003","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"É um marcador sensível e específico do carcinoma medular de tireóide, que pode ser\nmedido no sangue no estado basal ou após a administração de secretagogos como cálcio e\npentagastrina:","options":{"A":"Tireoglobulina.","B":"Gastrina.","C":"Hormônio Folículo Estimulante.","D":"Calcitonina."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-215590","number":"215590","sourceNumber":"215590","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação ao carcinoma indiferenciado ou\nanaplásico de tireoide.","options":{"A":"É o segundo tumor mais comum da tireoide e é considerado o mais agressivo.","B":"Incide em pacientes mais idosos, com mais de 60 anos e com frequência um pouco maior em\nmulheres.","C":"Há associação com bócios de longa duração, com alteração aguda do ritmo de crescimento.","D":"Sintomas clínicos associados à infiltração tumoral, como disfagia, dispneia, tosse, rouquidão e\ndor estão presentes."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-181172","number":"181172","sourceNumber":"181172","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Sobre o Pseudomixoma Peritoneal, assinale a alternativa INCORRETA:","options":{"A":"Carcinomatose mucinosa tem o pior prognóstico com sobrevida de 14% em cinco anos.","B":"O tratamento envolve a ressecção máxima possível do tumor e quimioterapia sistêmica.","C":"Ocorre mais frequentemente em pacientes com 40 e 50 anos.","D":"Pacientes geralmente são assintomáticos no período inicial da doença."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-157601","number":"157601","sourceNumber":"157601","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Em relação aos carcinomas da tiróide, aponte a alternativa em que a afirmação esteja\nCORRETA.","options":{"A":"O Carcinoma Papilífero é o mais comum, é mais frequente em mulheres entre terceira e quarta\ndécada de vida, é pouco agressivo, e em crianças e adolescentes não apresenta alto índice de\nmetástase.","B":"O Carcinoma Anaplásico é o mais raro, incide mais em idosos, e tem boa resposta à\nquimioterapia e radioterapia.","C":"O Carcinoma Medular pode estar associado à Neoplasia Endócrina Múltipla 2a, onde a doença é\nbilateral, e pode ser acompanhada por hiperparatiroidismo, feocromocitoma ou hiperplasia medular\nadrenal.","D":"Na associação NEM 2b, a doença pode ser familiar ou esporádica, há comprometimento\nglandular bilateral eganglioneuromas\n\nmucosos. Tem melhor prognóstico quando comparado ao NEM 2a."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-157618","number":"157618","sourceNumber":"157618","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Sobre a vascularização do estômago, indique a alternativa INCORRETA.","options":{"A":"Os ramos da A. Esplênicas são A. Gastro-omental esquerda e A. Hepática.","B":"A. Gastro-omental esquerda pode originar-se da A. Esplênica ou de seus ramos.","C":"A. Gástrica direita em geral se origina no tronco da A. Hepática própria.","D":"A. Gastro-omental direita origina-se na bifurcação da A. Gastroduodenal, que por sua vez é\nramo da A. Hepática Comum."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-157631","number":"157631","sourceNumber":"157631","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Em relação ao Adenocarcinoma de Pâncreas, assinale a alternativa INCORRETA.","options":{"A":"Nos EUA, cerca de 80% dos casos novos de câncer de pâncreas apresentam doença avançada\nnão suscetível ao tratamento cirúrgico. Isso\ntorna a cirurgia paliativa tão importante quanto o\ntratamento curativo.","B":"O controle da dor pode ser feito com narcóticos orais e por meio de neurólise esplâncnica que\npode ser realizada durante o ato cirúrgico\natravés da injeção de álcool absoluto bilateralmente ao\nplexo celíaco.","C":"A sobrevida geral em cinco anos dos pacientes com câncer de pâncreas submetidos à\nressecção pancreática de doença não metastática é de cerca de 5%.","D":"A sobrevivência média dos pacientes que são submetidos à ressecção pancreática com doença\nnão metastática é de 11 a 20 meses."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-157675","number":"157675","sourceNumber":"157675","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"É indicação relativa de Tiroidectomia:","options":{"A":"a suspeita de malignidade pelo exame físico, ultrassonográfico e citológico.","B":"Os bócios pequenos com alteração estética importante.","C":"O bócio tóxico.","D":"O bócio de grande volume."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-157726","number":"157726","sourceNumber":"157726","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Quais são os critérios histológicos para malignidade e marcadores tumorais\nrelacionados ao GIST, RESPECTIVAMENTE?","options":{"A":"Aumento da relação núcleo citoplasma e CD54.","B":"Índice Mitótico > 2 por 10 CGA e CD34.","C":"Infiltração da mucosa pelo tumor e Proteína S100.","D":"Aumento da relação núcleo membrana e C-kit."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-157733","number":"157733","sourceNumber":"157733","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Sobre os tumores urogenitais, aponte a alternativa INCORRETA.","options":{"A":"Aproximadamente 85% dos tumores renais são representados pelos Carcinomas de Células\nRenais, e nos demais casos outros tumores\nmalignos como Carcinoma de Células Transicionais da\nPelve Renal, ou benignos como o Angiomiolipoma, Oncocitomas e Adenomas.","B":"Os Adenocarcinomas de Próstata se localizam na zona transicional em sua maioria, seguido de\nzona periférica e, por último, zona central.","C":"Carcinoma de Células Renais predominam, no sexo masculino, em indivíduos de 50 a 70 anos,\noriginam-se das células dos túbulos renais e apresentam histologicamente sob cinco diferentes\nformas, sendo predominante o tipo denominado Carcinoma de Células Claras.","D":"Mais de 95% das neoplasias de próstatas são representadas pelo Adenocarcinoma e o restante\ncompreende casos de Sarcoma, Carcinoma Epidermoide, Carcinoma de Células Transicionais."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-157725","number":"157725","sourceNumber":"157725","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Sobre as síndromes polipoides, indique a alternativa falsa:","options":{"A":"A polipose adenomatosa familiar está associada à mutação no gene APC, situado no braço\nlongo do cromossomo 5q21. Essa mutação determina polipose gastrointestinal e diversas\nmanifestações extracolônicas.","B":"Desde a descrição original de polipose associada a cistos epidermoides e osteoma, a\ncombinação de polipose adenomatosa familiar e\nmanifestações extracolônicas é conhecida como\nSíndrome de Turcot.","C":"Todas as células do epitélio colunar em portadores da polipose adenomatosa familiar possuem\nmutação germinativa do gene APC, por esta razão é indicado colectomia profilática.","D":"A associação de pigmentação mucocutânea e polipose gastrointestinal é encontrada na\nsíndrome de Peutz-Jeghers. O potencial de\nmalignidade já foi descrita por numerosos autores,\nacumulando evidências suficientes que sugerem um risco aumentado para desenvolver neoplasias\nno trato digestivo."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-157736","number":"157736","sourceNumber":"157736","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Sobre o câncer de pulmão, indique a alternativa INCORRETA.","options":{"A":"Carcinoma de pulmão não pequenas células é um grupo formado por 4 tipos histológicos:\ncarcinoma epidermoide, adenocarcinoma, carcinoma\nindiferenciado de grandes células e carcinoma\nadenoescamoso.","B":"A principal disseminação dos tumores pulmonares é linfática, os primeiros linfonodos acometidos\nsão: intrapulmonares, hilares, paratraqueais e, por\nfim, metástase à distância.","C":"Os pulmões são os principais sítios de metástases de todos os tumores sólidos malignos, exceto\ntumores colorretais.","D":"Carcinoma de pulmão pequenas células é muito mais agressivo e, geralmente, tem metástases\nà distância no momento do diagnóstico. A\noperação de modo isolado é superior a outras formas de\ntratamento."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-139768","number":"139768","sourceNumber":"139768","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Bento, 69 anos, tabagista e etilista crônico, apresenta disfagia progressiva. Endoscopia\ndigestiva alta: lesão infiltrante e ulcerada em 1/3 médio do esôfago. Indique a alternativa que\napresenta o diagnóstico PROVÁVEL para esse caso.","options":{"A":"Carcinoma escamoso.","B":"Adenocarcinoma.","C":"Carcinosarcoma.","D":"Tumor carcinoide."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-134685","number":"134685","sourceNumber":"134685","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"É CERTO dizer que o adenoma é o tumor benigno mais comum do intestino delgado:","options":{"A":"acometendo, preferencialmente, o duodeno.","B":"acometendo, preferencialmente, o jejuno.","C":"acometendo, preferencialmente, o íleo.","D":"acometendo, preferencialmente, o duodeno e o jejuno."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-134704","number":"134704","sourceNumber":"134704","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Termina-se uma gastrectomia total com uma:","options":{"A":"Jejunostomia, para alimentar o paciente, protegendo a esôfago-êntero anastomose.","B":"Jejunostomia, para alimentar o paciente, utilizando a esôfago-êntero anastomose.","C":"Ileostomia, para alimentar o paciente, protegendo a esôfago-êntero anastomose.","D":"Todas as anteriores estão erradas."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-111818","number":"111818","sourceNumber":"111818","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Sobre Hepatectomia videolaparoscópica, indique a alternativa CORRETA.","options":{"A":"Pode ser opção vantajosa para ressecções hepáticas, de acordo com a localização e volume da\nlesão.","B":"Deve ser realizada sob critérios estritos em centros especializados.","C":"Vantagens habitualmente reconhecidas como menor dor pós-operatória, íleo adinâmico menos\nprolongado e melhor resultado estético não são encontrados neste procedimento.","D":"Conversão não deve ser visto como complicação ou fracasso, mas como medida de segurança."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-111834","number":"111834","sourceNumber":"111834","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"A Manobra de Kocher consiste na secção e na abertura coalescência peritoneal:","options":{"A":"lateralmente ao arco duodenal, penetrando-se na região retroduodenal, que é pouco\nvascularizada, basculando-se o arco duodenal em direção à linha média.","B":"Medialmente ao arco duodenal, penetrando-se na região retroduodenal, que é pouco\nvascularizada, basculando-se o arco duodenal em direção à linha média.","C":"Lateralmente ao arco duodenal, penetrando-se na região supraduodenal, que é pouco\nvascularizada, basculando-se o arco duodenal em direção à linha média.","D":"Lateralmente ao arco duodenal, penetrando-se na região retroduodenal, que é bem\nvascularizada, basculando-se o arco duodenal em direção à linha média."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-350869","number":"350869","sourceNumber":"350869","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente de 53 anos realizou uma endoscopia que identificou uma lesão gástrica,\nelevada de 2 cm, na grande curvatura,\nregião do corpo alto. A biopsia foi compatível com\nadenocarcinoma bem diferenciado. A tomografia de tórax e abdome com contraste não mostrou\nlíquido livre, blocos linfonodais suspeitos ou nódulos hepáticos. Suspeitando de um câncer gástrico\nprecoce, qual dos seguintes métodos deve contribuir mais para o planejamento do tratamento\ndesse paciente?","options":{"A":"Ultrassonografia endoscópica.","B":"Biopsia excisional endoscópica com alça.","C":"Anatomopatológico da gastrectomia parcial.","D":"Tomografia por emissão de pósitrons de corpo inteiro."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-350863","number":"350863","sourceNumber":"350863","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Homem de 30 anos, praticante de exercícios físicos, apresenta dor abdominal súbita e\nintensa em hipocôndrio direito. Realizou tomografia abdominal com contraste que demonstrou lesão\nhepática arredondada circunscrita com realce na fase arterial associada à área heterogênea\nadjacente sugestiva de hematoma contido. A lesão tem cerca de 3 cm, incluindo área líquida\nadjacente, corresponde a 5 cm no total em segmento VI. O paciente está estável há 24 horas, sem\nqueda de hemoglobina e apresenta melhora da dor quando é administrado analgésico. Familiares\ninformam que o paciente faz uso de anabolizantes. Qual a melhor conduta nesse caso?","options":{"A":"Suspender anabolizantes e repetir tomografia após 3 meses.","B":"Biopsia percutânea, com agulha, guiada por ultrassom.","C":"Embolização arterial hepática.","D":"Hepatectomia segmentar."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-321282","number":"321282","sourceNumber":"321282","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"A incidência de adenocarcinoma esofágico vem aumentando nas últimas 4 décadas em\nvários países, como Estados Unidos. Qual a principal explicação para esse fato?","options":{"A":"Aumento da incidência de obesidade.","B":"Aumento no consumo de cigarro e álcool.","C":"Aumento da qualidade de notificação dos casos.","D":"Aumento do consumo de café e bebidas quentes."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-321286","number":"321286","sourceNumber":"321286","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Há pelo menos 5 anos, um jovem de 25 anos, sexo masculino, é submetido à\ncolonoscopia pois sua família é acompanhada por mutação genética do gene APC. Os achados\nforam: ausência de pólipos no reto, cerca de 20 pólipos colônicos principalmente a direita, sendo\num de cerca de 3 cm, no cécum, de aspecto vegetante e sessil que foi biopsiado. Alguns pólipos\nremovidos foram compatíveis com pólipos adenomatosos, tipo tubular e a lesão vegetante foi\ncompatível com adenocarcinoma bem diferenciado. A tomografia de abdome foi normal. Qual\nopção cirúrgica é mais adequada para esse paciente?","options":{"A":"Proctocolectomia total com linfadenectomia e anastomose ileoanal manual.","B":"Proctocolectomia total com linfadenectomia e confecção de ileostomia definitiva.","C":"Colectomia direita com linfadenectomia e confecção de anastomose ileotransversa.","D":"Colectomia total com linfadenectomia e anastomose colorretal ao nível do promontório."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-321291","number":"321291","sourceNumber":"321291","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Homem de 36 anos procura atendimento médico para avaliação de aumento do volume\ndo testículo esquerdo. O paciente refere que\napós um jogo de futebol, notou um aumento do\nvolume da bolsa escrotal esquerda. Ao exame, bolsa escrotal esquerda baixa em relação ao lado\ndireito, testículo esquerdo cerca de três vezes aumentado em relação ao direito, não doloroso a\npalpação. Teste de translucência negativo. Qual a principal hipótese para esse paciente?","options":{"A":"Hidrocele traumática.","B":"Hérnia inguinocrural.","C":"Tumor de célula germinativa.","D":"Persistência do conduto peritoniovaginal."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-321296","number":"321296","sourceNumber":"321296","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"No ambulatório de cirurgia oncológica, uma paciente de 54 anos com história de perda\nde peso recente, traz uma endoscopia com\nachados de lesão gástrica de 1 cm ulcerada. O exame\nhistopatológico da biópsia endoscópica é compatível com adenocarcinoma moderadamente\ndiferenciado. Qual exame complementar para estadiamento é mais acurado para detectar\nprogressão locorregional da neoplasia?","options":{"A":"Tomografia por emissão de prótons (PET - CT).","B":"Tomografia abdominal com contraste.","C":"Laparoscopia diagnóstica.","D":"US endoscópico."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-321311","number":"321311","sourceNumber":"321311","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Homem de 86 anos é admitido na emergência com quadro de redução do nível de\nconsciência, náuseas, vômitos, distensão abdominal e constipação há uma semana. Exame físico:\nPA 100x60mmHg / FC 110bpm / FR 24irpm / SpO2 95% em ar ambiente. Ectoscopia: hipocorado\n2+/4+, desidratado 2+/4+, parcialmente orientado. Glasgow 14 por conta da desorientação.\n\nAusculta cardiopulmonar sem alterações. Abdome: distendido, RHA hipoativos, hipertimpânico,\ndoloroso difusamente à palpação, sem sinais de\nperitonite. Exames laboratoriais: Hb 8,5g/dL /\nLeucócitos 8.000/mm3 / Plaquetas 168.000/mm3 / VHS 110mm na primeira hora / Ureia 120mg/dL /\nCreatinina 1,8mg/dL / Sódio 145mEq/L / Potássio 3,5mEq/L / Cálcio total 14mg/dL / Albumina\n2,0g/dL. Qual a conduta inicial, nesse caso?","options":{"A":"Hidratação.","B":"Furosemida.","C":"Denosumab.","D":"Pamidronato."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-292792","number":"292792","sourceNumber":"292792","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Após tratamento neoadjuvante, uma paciente de 54 anos, com diagnóstico de\nadenocarcinoma tipo intestinal de 2 cm no antro gástrico, realiza tomografia que demonstra\nadenopatias em tronco celíaco, ausência de metástases hepáticas ou ascite. Atualmente,\napresenta-se com bom estado geral e sem outras comorbidades. Para essa paciente, qual o\npróximo passo para o seu tratamento?","options":{"A":"Gastrectomia parcial com linfadenectomia D1 e reconstrução a BII.","B":"Gastrectomia parcial com linfadenectomia D2 e reconstrução a BII.","C":"Gastrectomia total com linfadenectomia D2 e reconstrução em Y de Roux.","D":"Gastrectomia subtotal com linfadenectomia D2 e reconstrução em Y de Roux."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-259711","number":"259711","sourceNumber":"259711","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Homem, 51 anos, hipertenso, fumante, realizou Ultrassonografia (US) Doppler de\ncarótidas sendo detectado nódulo tireoidiano.\nRealizou US da tireoide, que revelou a presença de\nnódulos em ambos os lobos da tireoide: Nódulo 1 (N1), misto, hiperecoico, medindo 1,1 x 0,7 cm\nem lobo esquerdo e Nódulo 2 (N2) sólido, hipoecoico, sem microcalcificações na transição do\nistmo/lobo direito 0,8 x 0,5 cm. Para prosseguir a investigação dos nódulos do paciente, qual o\npróximo exame a ser realizado?","options":{"A":"Cintilografia de tireoide.","B":"Dosagem de TSH sérico.","C":"Punção aspirativa de N1.","D":"Punção aspirativa de N2."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-234005","number":"234005","sourceNumber":"234005","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Anto?nio Carlos, me?dico da atenc?a?o prima?ria, realiza visita domiciliar ao Sr. Jose?\nMaria, de 60 anos, que e? portador de neoplasia de pa?ncreas inopera?vel, em vige?ncia de\nquimioterapia, utilizando metadona 30mg por dia e mantendo EVN 8 de 10. Na u?ltima semana,\nesteve por duas vezes na UPA para controle da dor e das na?useas intensas e passou a ficar todo\no tempo acamado, incapaz e totalmente dependente para todas as atividades. A ingesta de\nalimentos encontra-se reduzida. Esta? alerta, sem conscie?ncia da gravidade de sua situac?a?o,\nem profundo sofrimento psi?quico e espiritual. Tem boa estrutura familiar, rede de apoio e\ncondic?o?es socioecono?micas esta?veis, de baixa vulnerabilidade. LEGENDA: EVN: escala visual\nnume?rica de dor. Qual a proposta mais apropriada para se discutir com o paciente e familiares,\nneste caso?","options":{"A":"Manter o enfoque na cura, mas orientar possibilidade de cuidados paliativos.","B":"Internar para controle dos sintomas, novos exames e reestadiamento da doenc?a.","C":"Reagendar consulta com o oncologista para intensificar esquema de quimioterapia.","D":"Manter em domici?lio com equipe interdisciplinar exclusivamente em cuidado paliativo."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-234009","number":"234009","sourceNumber":"234009","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma paciente com 35 anos de idade procurou a demanda esponta?nea de\natendimentos em unidade ba?sica de sau?de\npois queria fazer uma colonoscopia e estava muito\npreocupada com o diagno?stico de ca?ncer colorretal em sua irma? de 37 anos. Ela era totalmente\nassintoma?tica e relatava que o pai faleceu aos 58 anos por uma obstruc?a?o intestinal provocada\npor um ca?ncer colorretal, e que um tio paterno foi operado em decorre?ncia de um tumor de ceco,\naos 55 anos. A paciente negava comorbidades e seu exame fi?sico foi completamente normal.\n\nConsiderando a situac?a?o cli?nica apresentada, qual deve ser a forma proposta para\nrastreamento de ca?ncer colorretal a essa paciente?","options":{"A":"Solicitar pesquisa de sangue oculto nas fezes e a colonoscopia, se for positiva.","B":"Orientar a realizac?a?o de colonoscopia a partir dos 40 anos, repetindo o exame a cada 5 anos.","C":"Solicitar colonoscopia e mediante resultado normal repetir o exame a cada um ou dois anos.","D":"Orientar a realizac?a?o de colonoscopia a partir dos cinquenta anos, repetindo o exame a cada\ndez anos."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-199687","number":"199687","sourceNumber":"199687","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente de 53 anos, portador de neoplasia gástrica distal, foi submetido a uma\ngastrectomia subtotal com reconstrução em y de Roux. Na descrição cirúrgica foi descrito que\n\n?toda a doença macroscópica foi removida e que houve intenção curativa?. Na consulta de retorno,\no anatomopatológico trouxe as seguintes informações:\nproduto de gastrectomia parcial, com tumor\nem antro distal infiltrando até a camada muscular do órgão, margem distal com comprometimento\nmicroscópico e presença de neoplasia metastática em 1 linfonodo entre 20 dissecados. A citologia\ndo líquido peritoneal foi positiva para células neoplásicas. Com base nas informações descritas\npode-se afirmar:","options":{"A":"A amostra linfonodal foi suficiente para o estadiamento.","B":"A ressecção realizada pode ser classificada como D1.","C":"Trata-se de um tumor T4 pela classificação TNM.","D":"Deve-se classificar a ressecção como R0."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-199750","number":"199750","sourceNumber":"199750","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma jovem de 23 anos, atendida pela equipe de saúde da família, apresenta um nódulo\nna porção anterior baixa do pescoço, móvel à\ndeglutição e com diâmetro aproximado de 1,5 cm.\n\nNão apresenta taquicardia, dor à palpação ou sinais flogísticos. Nega perda de peso ou\npalpitações. Qual o próximo exame na investigação diagnóstica?","options":{"A":"Cintilografia da tireoide.","B":"Punção com agulha fina e citologia.","C":"Ultrassonografia cervical com Doppler.","D":"Dosagem de hormônio tireoestimulante (TSH)."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-199817","number":"199817","sourceNumber":"199817","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente masculino, 66 anos, ex-tabagista (40 maços/ano, cessou há 8 meses),\nrealizou radiografia de tórax para exame\nadmissional que mostrou nódulo pulmonar em lobo\nsuperior esquerdo, sem outros achados. Foi orientado a realizar TC de tórax com contraste que\nconfirmou a presença de lesão nodular com padrão em vidro fosco, de 1,5 cm, periférico (a 1 cm da\nsuperfície pleural) e com contornos espiculados. A densidade medida antes do contraste era de 42\nUH e sofreu um incremento de 18 UH após injeção de contraste. O paciente não apresenta\nsintomas respiratórios, comorbidades e nega passado de neoplasia. LEGENDA: TC: Tomografia\nComputadorizada. Diante das características clinicorradiológicas aqui apresentadas, qual a melhor\nconduta a ser tomada, dentre as relacionadas abaixo?","options":{"A":"Realizar nova TC de tórax em 6 meses e solicitar biópsia se aumento do tamanho.","B":"Indicar videotoracoscopia com biópsia e ressecção se congelação positiva para câncer.","C":"Manter conduta expectante pela ausência de sintomas e baixa probabilidade de neoplasia.","D":"Solicitar biópsia percutânea e interromper segmento se o resultado for negativo para câncer."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-172959","number":"172959","sourceNumber":"172959","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 60 anos, sexo feminino, apresenta hematoquezia e alteração do hábito\nintestinal. Durante investigação, o toque\nretal revelou uma lesão circunferencial de aspecto\nneoplásico a 3 cm da linha pectínea com biópsia de adenocarcinoma. A colonoscopia não\ndemonstrou outras lesões sincrônicas no restante do cólon. Os exames de estadiamento não\nrevelaram metástases sistêmicas. A ressonância do reto demonstrou que a lesão infiltra para além\nda muscular própria e com um linfonodo suspeito no mesorreto (cT3, cN1). Qual a melhor\nabordagem terapêutica inicial para o caso?","options":{"A":"Amputação abominoperineal do reto.","B":"Radioterapia associada à quimioterapia.","C":"Ressecção local por abordagem transanal.","D":"Ressecção anterior do reto com preservação esfincteriana."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-172970","number":"172970","sourceNumber":"172970","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma paciente de 35 anos comparece ao seu consultório com uma ultrassonografia e\nexames laboratoriais de rotina solicitados pelo ginecologista. A paciente gostaria de sua opinião\nsobre um nódulo que foi detectado na tireoide. A ultrassonografia mostra lesão de aspecto\n\ncístico-sólido de 1,4 cm. Os exames laboratoriais mostram TSH e T4 normais. Ao exame, o nódulo\né impalpável. A paciente nega história familiar de\nlesões semelhantes e qualquer tratamento\nradioterápico. Você, então, solicita um PAAF. Em qual das seguintes situações, referentes aos\nachados do PAAF, a paciente deve ser orientada a retornar para repetir a ultrassonografia no\nperíodo dos próximos 6 a 12 meses?","options":{"A":"Material amorfo de aspecto coloide com raros macrófagos.","B":"Células em arranjo folicular de característica indeterminada.","C":"Células em arranjo papilífero com anisocitose e mitoses atípicas.","D":"Células multiformes de contornos irregulares com mitoses atípicas e aberrantes."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-172948","number":"172948","sourceNumber":"172948","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O câncer gástrico precoce (T1) apresenta elevadas taxas de cura e pode ser tratado\natravés de ressecção endoscópica. Porém,\npara tal tratamento ser seguro, é necessária a seleção\nde casos que não apresentam infiltração neoplásica na camada submucosa do órgão. Qual o\nmelhor método de estadiamento para realizar essa avaliação específica?","options":{"A":"Ecoendoscopia.","B":"Videolaparoscopia.","C":"Tomografia computadorizada.","D":"Ressonância nuclear magnética."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-150825","number":"150825","sourceNumber":"150825","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Mulher de 25 anos procura aconselhamento médico por ter sido tratada de carcinoma\nmedular da tireoide diagnosticado durante investigação de hipercalcemia. Foi submetida a teste\ngenético para Neoplasia Endócrina Múltipla (NEM), o qual apresentou mutação germinativa\npatogênica do gene RET. História familiar: pai com neoplasia neuroendócrina pancreática e tia\nfalecida por câncer de tireoide. Ela tem um filho de 4 anos e está preocupada com o risco de ele\ndesenvolver neoplasia. Qual a melhor orientação para o filho?","options":{"A":"Tireoidectomia total, se hipercalcemia.","B":"Dosagens periódicas do nível sérico de calcitonina.","C":"Monitorização com ultrassonografia cervical periódica.","D":"Teste genético para NEM e avaliação de mutação do gene RET."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-150845","number":"150845","sourceNumber":"150845","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 60 anos, ex-etilista pesado (parou há 10 anos) e portador de hepatopatia\ncrônica. Durante acompanhamento clínico\nperiódico, apresentou elevação do marcador\nalfafetoproteína. Realizou tomografia de abdome que revelou 2 nódulos heterogêneos em lobo\ndireito do fígado medindo 3 cm e 2 cm com captação do contraste na fase arterial. Durante\navaliação da função hepática, foi classificado como Child-Pugh B. Qual a melhor conduta para o\ncaso?","options":{"A":"Hepatectomia direita.","B":"Biópsia da lesão hepática.","C":"Transplante hepático ortotópico.","D":"Ablação das lesões por radiofrequência."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-150850","number":"150850","sourceNumber":"150850","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Mulher de 68 anos, ativa, há cerca de 2 meses vem apresentando adinamia\nprogressiva, interferindo na realização de suas\natividades. Refere cansaço fácil, diminuindo seu\nrendimento nos exercícios aeróbicos. Em consulta de rotina com ginecologista, mencionou essas\nqueixas, sendo solicitados exames bioquímicos. Os exames foram normais, exceto as hemáceas:\n3,8 milhões/mm3 e Hb-9,8 g/dl e pesquisa de sangue nas fezes ++. A paciente nega quaisquer\noutros sintomas e ao exame clínico rigoroso, a médica só constatou palidez cutânea-mucosa (+/4).\nDiante do exposto, qual a sequência de exames a ser realizada?","options":{"A":"Videocolonoscopia e seguindo, tomografia abdominal.","B":"Esofagogastroduodenoscopia, videocolonoscopia e seguindo, tomografia abdominal.","C":"Tomografia abdominal, esofagogastroduodenoscopia e seguindo, videocolonoscopia.","D":"Repetir sangue oculto nas fezes, videocolonoscopia e seguindo, ultrassonografia abdominal."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-150802","number":"150802","sourceNumber":"150802","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Mulher de 65 anos apresenta-se com história de dor em andar superior do abdome de 2\nmeses de evolução. Refere que nos últimos 20 dias passou a apresentar icterícia de caráter\nprogressivo. Nega febre. Durante o exame físico, além da icterícia, encontra-se uma vesícula\npalpável e indolor. A TC de abdome trifásica demonstra vesícula biliar distendida, dilatação das\nvias\nbiliares e do ducto de Wirsung com afilamento abrupto. Qual o diagnóstico mais provável?","options":{"A":"Coledocolitíase.","B":"Pancreatite crônica.","C":"Neoplasia do pâncreas.","D":"Neoplasia da vesícula biliar."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-126936","number":"126936","sourceNumber":"126936","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 60 anos, com diagnóstico de câncer de mama estádio clínico III e tratada\ncom mastectomia radical há 4 anos, seguida de\nquimioterapia e radioterapia adjuvantes,\ndesenvolve quadro de tosse e dispneia aos esforços. Após investigação, foi evidenciado derrame\npleural moderado à direita. Assinale a melhor conduta inicial nessa situação.","options":{"A":"Pleurodese química.","B":"Pleurodese mecânica.","C":"Toracocentese e biópsia pleural.","D":"Drenagem torácica em selo d'água."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-126983","number":"126983","sourceNumber":"126983","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente, 63 anos, masculino, tabagista importante há 40 anos, procurou o ambulatório\ncom queixa de disfagia progressiva e perda de\npeso. Há 3 meses começou a sentir dificuldade para\naceitação de dieta sólida e, atualmente, só consegue aceitar dieta líquida sem resíduo. No período\nperdeu 18 Kg (peso habitual 72 Kg). No momento encontra-se emagrecido, pálido (++/4+); abdome\nescavado, flácido e indolor; extremidades com edema de membros inferiores com cacifo positivo.\n\nApresenta ainda Hb 9,1g/dl, Ht 30%, leucócitos de 11.200 mm³ com 930 mm³ linfócitos, transferrina\nde 153 mg/dl (VR 215 a 365 mg/dl) e albumina\nsérica de 2,8g/dl. Realizou EDA que evidenciou\nlesão ulcerada e friável a 32 cm da arcada dentária superior com câmara gástrica sem alterações.\nA lesão foi biopsiada e o resultado histopatológico conclui por malignidade na amostra. TC de tórax\nsem alterações em parênquima pulmonar. TC de abdome e broncoscopia normais. Em relação ao\ncaso, a melhor conduta pré-operatória seria:","options":{"A":"Ofertar, por sonda nasoenteral, dieta de cerca de 2.000 calorias/dia.","B":"Realizar hiperalimentação endovenosa com nutrição parenteral total.","C":"Administrar por via parenteral reposição de vitamina K por 3 dias.","D":"Indicar hemotransfusão de 3 concentrados de hemáceas."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-126998","number":"126998","sourceNumber":"126998","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 40 anos realizou endoscopia digestiva alta para investigação de dispepsia\nrefratária com achado de lesão ulcerada em\npequena curvatura do corpo gástrico distando 5 cm da\njunção esôfago-gástrica. A biópsia revelou adenocarcinoma gástrico do tipo difuso pela\nclassificação de Lauren. Os exames de estadiamento demonstraram pequeno espessamento da\nparede gástrica mas sem evidências de doença linfonodal ou a distância (estadiamento cT2 cN0\ncM0). Qual o melhor tratamento para esse caso?","options":{"A":"Ressecção endoscópica.","B":"Gastrectomia parcial com linfadenectomia D2.","C":"Gastrectomia total com linfadenectomia D2.","D":"Gastrectomia proximal com linfadenectomia D1."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-126968","number":"126968","sourceNumber":"126968","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente de 25 anos queixa-se de uma massa testicular indolor. US: nódulo sólido\nem testículo esquerdo de 2 cm. Qual dos seguintes exames deve ser solicitado para o\nesclarecimento diagnóstico?","options":{"A":"Doppler de testículo.","B":"Biópsia testicular a céu aberto.","C":"LDH, alfa-fetoproteína e beta-HCG.","D":"Punção de bolsa escrotal percutânea."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-126945","number":"126945","sourceNumber":"126945","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Mulher de 75 anos tem diagnóstico de adenocarcinoma de cólon (intestino grosso) com\nmetástase peritoneal e deverá submeter-se à quimioterapia. O serviço de oncologia considera a\npossibilidade de administrar, de forma associada, bevacizumabe, uma droga que age sobre o Fator\nde Crescimento Endotelial Vascular (VEGF). Qual o principal mecanismo de ação dessa\ndroga sobre a biologia celular do câncer dessa paciente?","options":{"A":"Aumento da permeabilidade vascular tumoral de modo seletivo aos quimioterápicos.","B":"\"Normalização\" dos vasos tumorais com aumento da ação dos quimioterápicos.","C":"Lesão direta da membrana basal dos vasos tumorais com apoptose tumoral.","D":"Efeito antitumoral direto em sinergismo com os quimioterápicos."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-102143","number":"102143","sourceNumber":"102143","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente masculino, 35 anos, assintomático, foi orientado por proctologista a\nsubmeter-se a uma videocolonoscopia, visto\nque sua mãe e irmão mais velho haviam falecido de\n\ncâncer de cólon. A mãe faleceu com 48 anos de idade e o irmão aos 33 anos. À videocolonoscopia\nrevelaram-se duas lesões ulceradas, ambas no\ncólon ascendente. A maior, com aproximadamente\n3 cm de diâmetro, e a menor com 1,5 cm. Foram feitas biópsias de ambas as lesões com\nhistopatológico demonstrando adenocarcinoma moderadamente diferenciado. Realizou\nestadiamento com tomografia abdominal, pélvica e de tórax sem anormalidades. O antígeno\ncarcinoembriogênico foi de 2,5 µg/L. Diante do achado, assinale a síndrome genética na qual o\npaciente se enquadra e o tratamento mais adequado:","options":{"A":"Lynch I e proctocolectomia com ileostomia definitiva.","B":"Lynch II e colectomia subtotal com ileorreto anastomose.","C":"Lynch I e colectomia subtotal com ileotransverso anastomose.","D":"Síndrome de Muir (associada a mutações dos genes MLH1 e MSH2) e proctocolectomia com\nbolsa ileal."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-102144","number":"102144","sourceNumber":"102144","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente, 43 anos, masculino, em tratamento quimioterápico para câncer de pulmão de\npequenas células, é trazido à emergência\napresentando confusão mental e sonolência, após um\nepisódio convulsivo no domicílio. Familiar refere que paciente estava queixando-se de náuseas,\nsentia-se fraco e estava menos ativo, há cerca de 15 dias. O exame neurológico não evidenciou\ndéficits focais. A tomografia computadorizada do crânio, realizada há menos de 30 dias, não\nevidenciava metástases cerebrais. Qual eletrólito deve ser dosado para confirmar a hipótese\ndiagnóstica mais provável?","options":{"A":"Potássio.","B":"Fósforo.","C":"Sódio.","D":"Cálcio."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-102180","number":"102180","sourceNumber":"102180","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Alminda, 87 anos, retorna à sua casa, após internação hospitalar de 7 dias, por uma\nobstrução intestinal onde diagnosticou-se um câncer de cólon em fase terminal. O agente\ncomunitário de saúde agenda uma visita domiciliar de toda a equipe que ao chegar na casa\nobservam a família muito aflita com toda a situação e sem saber o que fazer com as fortes dores\nque dona Alminda se queixa ? nota 8 na escala de dor. Nesse contexto, qual deve ser o Plano de\ncuidado para essa situação?","options":{"A":"Iniciar morfina, via oral, para a dor de Alminda, com reavaliação em 24 horas.","B":"Iniciar AINES para tratar a dor de Alminda e preparar a família para a terminalidade.","C":"Iniciar tramadol para tratar a dor de Alminda e preparar a família para a terminalidade.","D":"Iniciar antidepressivos tricíclicos para a dor de Alminda, com reavaliação em 72 horas."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-81268","number":"81268","sourceNumber":"81268","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Mulher de 25 anos, assintomática, em uso de anticoncepcional oral há 16 anos,\nprocurou consulta na ginecologista, com intuito\nde receber orientação, pois deseja engravidar no\npróximo ano. Em decorrência dessa consulta, foi detectado, após realização de ecografia\nabdominal, nódulo hepático em segmento VI de 4 cm e, após avaliação bioquímica, as provas de\nfunção hepática, dosagens de enzimas canaliculares e de Alfafetoproteína (AFP) foram normais. A\npaciente realizou tomografia computadorizada que evidenciou uma massa heterogênea e bem\ndelimitada em segmento VI do fígado, medindo 5 cm. Diante do exposto, a melhor conduta para a\npaciente é:","options":{"A":"Indicar tratamento com radiofrequência no nódulo hepático e acompanhar dosagem de AFP.","B":"Recomendar a realização de ressecção da lesão hepática antes da gravidez programada.","C":"Realizar embolização da artéria hepática e observar a paciente com tomografia\ncomputadorizada.","D":"Suspender o uso de contraceptivos orais e observar a paciente com ecografias abdominais\nseriadas."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-81279","number":"81279","sourceNumber":"81279","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 48 anos, sexo feminino, é submetida a uma endoscopia digestiva alta para\ninvestigação de queixas digestivas inespecíficas. O exame descobre pequena lesão elevada e não\nulcerada no esôfago, distante 25 cm da arcada dentária superior. O resultado do exame\nhistopatológico obtido por biópsia demonstra tratar-se de um carcinoma epidermoide que atinge a\ncamada muscular própria. Qual das opções abaixo apresenta: o estadiamento quanto à extensão\ndo tumor, o exame complementar de melhor acurácia para avaliação locorregional da doença e a\nopção terapêutica mais adequada?","options":{"A":"T2, ultrassonografia endoscópica e esofagectomia.","B":"T1, RM (Ressonância Magnética) e ressecção endoscópica.","C":"T2, TC (Tomografia Computadorizada) e radio/quimioterapia.","D":"T1, PET-TC (Tomografia por Emissão de Pósitrons) e esofagectomia."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-81228","number":"81228","sourceNumber":"81228","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 38 anos, sexo masculino, procura assistência médica com queixas de\nempachamento pós-prandial, motivo pelo qual é solicitada uma endoscopia digestiva alta, onde se\nobserva um abaulamento de aspecto tumoral, sem comprometimento da mucosa, de\naproximadamente 6 cm, na grande curvatura, transição corpo-antro. À ecoendoscopia, a lesão é\nbem delimitada na parede gástrica, sem comprometer serosa e mucosa, sugerindo tratar-se de\nTumor de Células Estromais (GIST). Qual das opções abaixo apresenta o tratamento mais\nadequado para esse caso e qual o critério diagnóstico mais específico para que o tumor seja\nrealmente um GIST?","options":{"A":"Gastrectomia subtotal e expressão imuno-histoquímica do oncogene HER2.","B":"Gastrectomia subtotal e expressão imuno-histoquímica do oncogene CD117.","C":"Gastrectomia em cunha e expressão imuno-histoquímica do oncogene c-KIT.","D":"Gastrectomia em cunha e expressão imuno-histoquímica do oncogene PDGFR- alpha."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-81275","number":"81275","sourceNumber":"81275","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Criança de 2 anos de idade, sexo masculino, apresenta anorexia e dor abdominal há 2\nmeses. Há 20 dias, queixa associada de dor em membros inferiores. Ao exame físico, observa-se\npalidez mucocutânea (2+/4+) e irritabilidade. Ultrassom abdominal revelou lesão retroperitoneal,\nsendo solicitado tomografia computadorizada de abdome (figura abaixo) para melhor\nesclarecimento da lesão. Mielograma demonstrou infiltração por células tumorais ?em roseta?. O\ndiagnóstico mais provável é: (VER IMAGEM)","options":{"A":"Neuroblastoma.","B":"Tumor de Wilms.","C":"Rabdomiossarcoma.","D":"Carcinoma de células renais."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":["question_bank/media/medcurso/med-cirurgia-med-cir-06/81275.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-81237","number":"81237","sourceNumber":"81237","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 55 anos, sexo feminino, é encaminhada ao ambulatório de cirurgia pelo\nendocrinologista, com uma massa palpável na região cervical anterior de aproximadamente 3 cm\nde diâmetro, com níveis de calcitonina basal de 600 pg/ml, sem outras alterações e sem casos\nsemelhantes na família. Qual o diagnóstico mais provável e qual o tratamento recomendado para\nessa paciente?","options":{"A":"Carcinoma folicular da tireoide e tireoidectomia total.","B":"Carcinoma medular da tireoide e tireoidectomia total.","C":"Carcinoma papilar da tireoide e tireoidectomia subtotal.","D":"Carcinoma de anaplásico da tireoide e tireoidectomia subtotal."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-141612","number":"141612","sourceNumber":"141612","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Em relação aos tumores sólidos na infância, é CORRETO afirmar:","options":{"A":"Tumor de Wilms, bolo de ascaris e cisto de ovário são massa abdominais benignas que fazem\ndiagnóstico diferencial com neoplasias malignas.","B":"O teste do reflexo vermelho no período neonatal não contribui com a identificação precoce do\nretinoblastoma.","C":"O tumor do sistema nervoso central é o mais frequente na população pediátrica.","D":"O Tumor de Wilms é o tumor retroperitonial benigno mais frequente na infância."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-349677","number":"349677","sourceNumber":"349677","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Em relação ao tema manifestações paraneoplásicas relacionadas ao câncer de pulmão,\nassinale a alternativa INCORRETA.","options":{"A":"A neuropatia periférica aguda é mais prevalente como síndrome paraneoplásica pulmonar no\nsubtipo não pequenas células.","B":"Síndrome de Lambert-Eaton está associada ao quadro de síndrome miastênica, frequentemente\nassociado ao carcinoma indiferenciado de\npequenas células.","C":"A síndrome de Cushing foi descrita como secreção ectópica do ACTH pelo tumor do pulmão,\nsendo frequente no carcinoma de pequenas células.","D":"A SIADH (Síndrome da Secreção Inadequada do Hormônio Antidiurético) está correlacionada ao\ncarcinoma indiferenciado de pequenas células.","E":"A osteoartropatia pulmonar hipertrófica pode preceder os sintomas pulmonares do câncer de\npulmão em meses."},"answer":"E","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-349773","number":"349773","sourceNumber":"349773","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Assinale a alternativa que apresenta alguns dos principais genes mutados que\ncontribuem para o surgimento do câncer\ncolorretal hereditário e um dos fatores que pode contribuir\npara a prevenção do câncer colorretal esporádico.","options":{"A":"BRCA 1 e BRCA 2 / Consumo diário de grandes quantidades de proteína.","B":"VHL e KRAS / Ingestão diária de ômega 3.","C":"BRAF e MEN1 / Dieta restrita em carnes vermelhas e gorduras.","D":"APC e MSH2 / Atividade física regular.","E":"BRCA 2 e p53 / Alimentação rica em frutas e vegetais."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-349765","number":"349765","sourceNumber":"349765","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente será submetido a uma tireoidectomia total devido a um câncer de tireoide.\nDiante disso, as principais complicações que podem ocorrer após o procedimento e devem ser\ninformadas ao paciente pelo médico são:","options":{"A":"hipercalcemia e alteração da voz.","B":"hipocalemia e rouquidão.","C":"hipocalcemia e paresia dos músculos da face.","D":"hipercalemia e dificuldade de deglutição.","E":"hipocalcemia e alteração da voz."},"answer":"E","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-365648","number":"365648","sourceNumber":"365648","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"No que concerne à avaliação das disfunções e lesões tireoidianas, assinale a\nalternativa que apresenta uma recomendação para a avaliação da tireoide.","options":{"A":"Não há indicação de pesquisa de marcadores moleculares na avaliação do nódulo tireoidiano.","B":"Na avaliação inicial dos nódulos da tireoide, deve-se solicitar tireoglobulina sérica.","C":"Deve-se solicitar a dosagem de T3 reverso na avaliação da função tireoidiana.","D":"Deve-se repetir anualmente a dosagem do anticorpo anti-TPO nos pacientes com tireoidite de\nHashimoto com exame anterior positivo."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-322130","number":"322130","sourceNumber":"322130","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Assinale a alternativa que corresponde à sequência correta de marcadores mais\nrelacionados aos seguintes tipos de câncer, nesta ordem: câncer de pâncreas / câncer de ovário /\ncâncer colorretal / hepatocarcinoma.","options":{"A":"Ca 125 / CEA / Ca 19-9 / alfafetoproteína.","B":"Ca 19-9 / Ca 15-3 / CEA / LDH.","C":"CEA / Ca 125 / CEA / LDH.","D":"Ca 19-9 / Ca 15-3 / CEA / alfafetoproteína.","E":"Ca 19-9 / Ca 125 / CEA / alfafetoproteína."},"answer":"E","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-322134","number":"322134","sourceNumber":"322134","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente com uma massa em ápice pulmonar direito apresenta dor e perda de força\nem ombro e braço direitos, além de ptose\npalpebral, miose e anidrose ipsilateral. A síndrome que\ninclui todos esses sinais e sintomas é denominada.","options":{"A":"síndrome de Claude Bernard-Horner.","B":"síndrome da veia cava superior.","C":"síndrome de Kaposi.","D":"síndrome de Pancoast.","E":"síndrome do desfiladeiro torácico."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-322140","number":"322140","sourceNumber":"322140","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Durante uma cirurgia de abordagem para ressecção da cabeça do pâncreas, qual das\nestruturas vasculares a seguir está presente nessa região e é de suma importância para o paciente,\ndevendo-se, por isso, realizar o máximo de esforço para que seja preservada?","options":{"A":"Artéria mesentérica inferior.","B":"Artéria gastroduodenal.","C":"Artéria pancreatoduodenal posterior.","D":"Artéria mesentérica superior.","E":"Artéria pancreatoduodenal superior."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-322145","number":"322145","sourceNumber":"322145","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma paciente de 32 anos teve, recentemente, diagnóstico de PAF (Polipose\nAdenomatosa Familiar) e possui aversão a cirurgias.\nQual é a orientação correta a ser feita nesse\ncaso?","options":{"A":"Orientar que a paciente possui uma síndrome genética de herança autossômica recessiva, que\ndificilmente será transmitida a outras gerações.","B":"Orientar que a paciente provavelmente precisará de intervenção cirúrgica, já que tem grandes\nchances de desenvolver um câncer colorretal\nem algum momento de sua vida.","C":"Orientar a paciente que o manejo da Polipose geralmente é feito por meio de acompanhamento\nclinico, com colonoscopia a cada 5 anos até os 80\nanos, deixando para comentar, quando preciso,\nsobre a possível necessidade de cirurgia.","D":"Orientar que essa patologia é caracterizada pela existência de alguns pólipos na região do reto,\nque podem ser acompanhados e ressecados por\ncolonoscopia, já que a paciente possui aversão a\ncirurgias.","E":"Orientar que essa patologia ocorre por uma mutação no gene BRCA1 e, portanto, deve ser\nindicada também adenomastectomia profilática pelo alto risco de câncer de mama."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-322161","number":"322161","sourceNumber":"322161","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Qual neoplasia maligna é responsável pelo maior número de óbitos no Brasil?","options":{"A":"Neoplasia de pulmão.","B":"Neoplasia de intestino.","C":"Neoplasia de mama.","D":"Neoplasia de pele.","E":"Neoplasia de colo de útero."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-305269","number":"305269","sourceNumber":"305269","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Assinale a alternativa que relaciona corretamente a síndrome hereditária ao aumento\ndo risco de câncer colorretal.","options":{"A":"A síndrome de Peutz-Jeghers é uma síndrome autossômica recessiva, caraterizada por pólipos\nhamartomatosos intestinais e hiperpigmentação da mucosa labial.","B":"A síndrome de Turcot é caracterizada, principalmente, por pólipos colorretais e adenomas\ntireoideanos.","C":"A síndrome de Lynch é caracterizada por pequeno número de pólipos colorretais e aumento do\nrisco também de câncer de endométrio e ovário.","D":"A síndrome de Gardner é caracterizada pela presença de centenas a milhares de pólipos\ncolorretais associados, principalmente, ao aumento do risco de câncer de colo uterino.","E":"A Polipose Adenomatosa Familiar (PAF) está fortemente associada à mutação do gene MLH1."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-305280","number":"305280","sourceNumber":"305280","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Sobre o câncer gástrico, é CORRETO afirmar que:","options":{"A":"Afeta, com maior frequência, as mulheres e a faixa etária entre 40?50 anos, sendo também o\ntipo de câncer mais comum no Japão.","B":"O Helicobacter pylori pode ser considerado um dos fatores contribuintes para o câncer gástrico\npor gerar gastrite hipertrófica.","C":"O câncer gástrico difuso hereditário é uma forma herdada de carcinoma gástrico resultante da\nmutação do gene da E-caderina, com aproximadamente 80% de possibilidade de desenvolvimento\nde câncer gástrico durante a vida.","D":"Alimentos ricos em sal, como carnes defumadas, juntamente com o alto consumo de frutas\ncítricas e vegetais, são associados a um risco aumentado de câncer gástrico.","E":"Os pacientes com anemia perniciosa também têm um aumento no risco de desenvolvimento de\ncâncer gástrico. A hipercloridria é a característica definidora dessa condição."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-298852","number":"298852","sourceNumber":"298852","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente com 62 anos de idade apresenta alteração de hábito intestinal há um ano\ne perda ponderal de 15 kg em 2 meses. Nega\nter realizado exames de rotina. No momento,\napresenta diarreia intensa há 24 horas, com vários episódios de evacuações líquidas, associado a\ndor abdominal difusa. Ao exame físico, está desidratado, com FC = 115 bpm, FR = 19 irpm, SatO2\n\n= 97% e temperatura axilar = 37ºC. Considerando esse caso clínico e os conhecimentos médicos\ncorrelatos, julgue os itens a seguir. A tomografia computadorizada é o exame para diagnóstico\ndefinitivo do câncer colorretal enquanto a colonoscopia é utilizada para estadiamento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-298853","number":"298853","sourceNumber":"298853","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente com 62 anos de idade apresenta alteração de hábito intestinal há um ano\ne perda ponderal de 15 kg em 2 meses. Nega\nter realizado exames de rotina. No momento,\napresenta diarreia intensa há 24 horas, com vários episódios de evacuações líquidas, associado a\ndor abdominal difusa. Ao exame físico, está desidratado, com FC = 115 bpm, FR = 19 irpm, SatO2\n\n= 97% e temperatura axilar = 37ºC. Considerando esse caso clínico e os conhecimentos médicos\ncorrelatos, julgue os itens a seguir. Caso seja confirmado o diagnóstico de câncer colorretal, pode\nser indicada a cirurgia de Hartmann, que consiste na hemicolectomia esquerda e na reconstrução\ncom anastomose primária em dois planos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-298854","number":"298854","sourceNumber":"298854","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente com 62 anos de idade apresenta alteração de hábito intestinal há um ano\ne perda ponderal de 15 kg em 2 meses. Nega\nter realizado exames de rotina. No momento,\napresenta diarreia intensa há 24 horas, com vários episódios de evacuações líquidas, associado a\ndor abdominal difusa. Ao exame físico, está desidratado, com FC = 115 bpm, FR = 19 irpm, SatO2\n\n= 97% e temperatura axilar = 37ºC. Considerando esse caso clínico e os conhecimentos médicos\ncorrelatos, julgue os itens a seguir. O paciente em tela deve passar por avaliação nutricional\n\npré-operatória, pois, neste caso, diminui o risco de complicações pós-operatórias.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-298874","number":"298874","sourceNumber":"298874","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente de 35 anos de idade vem apresentando dor abdominal e disfagia para\nsólidos de forma progressiva. Além disso,\ndemonstra perda de peso, sendo 10% do peso corporal\nem três meses. O paciente fez uso de omeprazol de 40 mg sem melhora. Também há lesões\ndolorosas e descamativas nas mãos e nos pés dele, como mostra a figura a seguir. Observaram-se\nPA = 110 mmHg x 70 mmHg, SatO2 = 98% em ar ambiente e FC = 60 bpm. Endoscopia indicou\numa larga massa na mucosa esofagena. Diante disso, o endoscopista realizou uma biópsia. Acerca\ndesse caso clínico e considerando os conhecimentos médicos correlatos, julgue o item a seguir. A\npresença de disfagia sólida sugere uma perda de, pelo menos, 70% da luz esofágica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-298875","number":"298875","sourceNumber":"298875","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente de 35 anos de idade vem apresentando dor abdominal e disfagia para\nsólidos de forma progressiva. Além disso,\ndemonstra perda de peso, sendo 10% do peso corporal\nem três meses. O paciente fez uso de omeprazol de 40 mg sem melhora. Também há lesões\ndolorosas e descamativas nas mãos e nos pés dele, como mostra a figura a seguir. Observaram-se\nPA = 110 mmHg x 70 mmHg, SatO2 = 98% em ar ambiente e FC = 60 bpm. Endoscopia indicou\numa larga massa na mucosa esofageana. Diante disso, o endoscopista realizou uma biópsia.\n\nAcerca desse caso clínico e considerando os conhecimentos médicos correlatos, julgue o item a\nseguir. Possivelmente, o diagnóstico seja adenocarcinoma de esôfago.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-298876","number":"298876","sourceNumber":"298876","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente de 35 anos de idade vem apresentando dor abdominal e disfagia para\nsólidos de forma progressiva. Além disso,\ndemonstra perda de peso, sendo 10% do peso corporal\nem três meses. O paciente fez uso de omeprazol de 40 mg sem melhora. Também há lesões\ndolorosas e descamativas nas mãos e nos pés dele, como mostra a figura a seguir. Observaram-se\nPA = 110 mmHg x 70 mmHg, SatO2 = 98% em ar ambiente e FC = 60 bpm. Endoscopia indicou\numa larga massa na mucosa esofagena. Diante disso, o endoscopista realizou uma biópsia. Acerca\ndesse caso clínico e considerando os conhecimentos médicos correlatos, julgue o item a seguir. O\npaciente apresenta uma condição genética chamada tilose palmoplantar.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-298877","number":"298877","sourceNumber":"298877","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente de 35 anos de idade vem apresentando dor abdominal e disfagia para\nsólidos de forma progressiva. Além disso,\ndemonstra perda de peso, sendo 10% do peso corporal\nem três meses. O paciente fez uso de omeprazol de 40 mg sem melhora. Também há lesões\ndolorosas e descamativas nas mãos e nos pés dele, como mostra a figura a seguir. Observaram-se\nPA = 110 mmHg x 70 mmHg, SatO2 = 98% em ar ambiente e FC = 60 bpm. Endoscopia indicou\numa larga massa na mucosa esofagena. Diante disso, o endoscopista realizou uma biópsia. Acerca\ndesse caso clínico e considerando os conhecimentos médicos correlatos, julgue o item a seguir.\n\nTomografia de tórax apresenta acurácia maior que ultrassom endoscópico para a identificação de\ndoença localmente avançada.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-298878","number":"298878","sourceNumber":"298878","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente de 35 anos de idade vem apresentando dor abdominal e disfagia para\nsólidos de forma progressiva. Além disso,\ndemonstra perda de peso, sendo 10% do peso corporal\nem três meses. O paciente fez uso de omeprazol de 40 mg sem melhora. Também há lesões\ndolorosas e descamativas nas mãos e nos pés dele, como mostra a figura a seguir. Observaram-se\nPA = 110 mmHg x 70 mmHg, SatO2 = 98% em ar ambiente e FC = 60 bpm. Endoscopia indicou\numa larga massa na mucosa esofagena. Diante disso, o endoscopista realizou uma biópsia. Acerca\ndesse caso clínico e considerando os conhecimentos médicos correlatos, julgue o item a seguir. A\npresença de uma massa grande na mucosa é altamente sugestiva de neoplasia de esôfago.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-260870","number":"260870","sourceNumber":"260870","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma paciente de 60 anos de idade, que nunca fumou, compareceu à consulta por\ncausa de dor torácica atípica para angina.\nEm exames de imagem do tórax, identificaram-se lesão\nnodular com densidade de partes moles em topografia de lobo médio, além de linfonodos\naumentados peri-hilar à direita, paratraqueal à direita e subcarinal. A paciente foi submetida à\nbiópsia dos linfonodos mediastinais por mediastinoscopia cervical, com evidência de neoplasia\nmaligna nos linfonodos analisados. As tomografias de crânio e de abdome não evidenciaram leões\nmetastáticas. Em relação a esse caso clínico e tendo em vista os conhecimentos médicos\ncorrelatos, julgue os itens a seguir. Adenocarcinoma de pulmão é um diagnóstico possível tendo em\nvista a paciente ser não fumante.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-274352","number":"274352","sourceNumber":"274352","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Em relação ao câncer gástrico assinale a alternativa correta.","options":{"A":"Há uma maior prevalência geral entre as mulheres.","B":"Pacientes com anemia perniciosa têm risco aumentado de desenvolver câncer gástrico.","C":"A linite plástica é o termo usado para descrever o câncer gástrico tipo 3 de Borrmann.","D":"O sistema de Lauren classifica o câncer gástrico em tipo intestinal e anaplásico.","E":"O câncer gástrico do tipo intestinal de Lauren é mais comum em pacientes jovens."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-261218","number":"261218","sourceNumber":"261218","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente de 45 anos de idade foi encaminhado para avaliação de disfagia há cerca\nde seis meses, com sensação de \"parada da\ndescida do alimento\" no meio do tórax. O paciente\nrelata histórico de dispneia com piora progressiva e passado de tratamento irregular para febre\nreumática. Ao exame, observaram-se ritmo cardíaco regular em dois tempos, com sopro diastólico\naudível em ápice; FC = 86 bpm; FR = 20 ipm; e SatO2 = 95%. O esofagograma atual mostra\ncompressão extrínseca do esôfago. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. A presença de endocardite infecciosa com cultura positiva para\nS.\nbovis exige a investigação de neoplasia colônica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-274355","number":"274355","sourceNumber":"274355","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"A condição que se apresenta como massa heterogênea hepática, benigna, mais\ncomum em mulheres e que tem\ncaracteristicamente um aumento da incidência com o uso crônico\nde contraceptivo oral denomina-se:","options":{"A":"Linfangioma hepático.","B":"Adenocarcinoma hepático.","C":"Hemangioma hepático.","D":"Adenoma hepático.","E":"Abscesso hepático."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-274363","number":"274363","sourceNumber":"274363","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 50 anos, masculino, vai à consulta devido a quadro de dispepsia, sensação\nde plenitude pós-prandial, perda ponderal de\ncerca de 10Kg nos últimos 60 dias e dor abdominal\nesporádica. O paciente tem histórico de ser tabagista e hipertenso, atualmente em uso de\nhidroclorotiazida e losartan, e faz uso irregular de inibidor de bomba devido à gastrectomia parcial\ndecorrente de úlcera gástrica há 10 anos. Após investigação, o paciente recebeu diagnóstico de\nneoplasia gástrica. Sobre esse quadro, assinale a alternativa correta.","options":{"A":"O diagnóstico mais provável, nesse caso, é linfoma gástrico.","B":"A presença de massa palpável em fundo gástrico, nódulo axilar e periumbilical é indicação para\ncirurgia de urgência.","C":"No adenocarcinoma, a consanguinidade e o tipo sanguíneo não são fatores de risco para a\ndoença.","D":"A presença de gastrite atrófica e a cirurgia de gastrectomia parcial geralmente atrasam o\nsurgimento de neoplasias gástricas.","E":"Em fases iniciais da doença, o prognóstico de cura é acima de 90%."},"answer":"E","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-274375","number":"274375","sourceNumber":"274375","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O tipo histológico mais comum de neoplasia de tireoide e seu padrão de disseminação\nsão, respectivamente:","options":{"A":"carcinoma folicular, padrão linfonodal.","B":"carcinoma folicular, padrão hematogênico.","C":"carcinoma papilífero, padrão hematogênico.","D":"carcinoma papilífero, padrão linfonodal.","E":"carcinoma medular, padrão linfonodal."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-265562","number":"265562","sourceNumber":"265562","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente de 65 anos de idade, PS1, com histórico de perda de peso, anemia e\nemagrecimento, associados a alterações recentes do hábito intestinal, foi submetido a uma\ncolonoscopia, sendo diagnosticada uma tumoração no sigmoide de 3 cm, a cerca de 30 cm da\nmargem anal, com diagnóstico anatomopatológico compatível com adenocarcinoma de cólon\nmoderadamente diferenciado. O estadiamento clínico inicial não apresentou evidências de\nmetástases a distância. Acerca desse caso clínico e com base nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Os principais fatores de risco para o desenvolvimento do câncer\ncolorretal são idade superior a 50 anos, obesidade, dieta pobre em fibras alimentares, doença\ninflamatória intestinal e histórico familiar de neoplasia de cólon.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-265564","number":"265564","sourceNumber":"265564","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente de 65 anos de idade, PS1, com histórico de perda de peso, anemia e\nemagrecimento, associados a alterações recentes do hábito intestinal, foi submetido a uma\ncolonoscopia, sendo diagnosticada uma tumoração no sigmoide de 3 cm, a cerca de 30 cm da\nmargem anal, com diagnóstico anatomopatológico compatível com adenocarcinoma de cólon\nmoderadamente diferenciado. O estadiamento clínico inicial não apresentou evidências de\nmetástases a distância. Acerca desse caso clínico e com base nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. A cirurgia para esse paciente deve ser uma retossigmoidectomia\ncom linfadenectomia regional, com ligadura dos vasos na origem e anastomose primária.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-265565","number":"265565","sourceNumber":"265565","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente de 65 anos de idade, PS1, com histórico de perda de peso, anemia e\nemagrecimento, associados a alterações recentes do hábito intestinal, foi submetido a uma\ncolonoscopia, sendo diagnosticada uma tumoração no sigmoide de 3 cm, a cerca de 30 cm da\nmargem anal, com diagnóstico anatomopatológico compatível com adenocarcinoma de cólon\nmoderadamente diferenciado. O estadiamento clínico inicial não apresentou evidências de\nmetástases a distância. Acerca desse caso clínico e com base nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Se, durante o seguimento ambulatorial desse paciente, ele vier a\napresentar metástases hepáticas passíveis de tratamento cirúrgico, ele deve ser encaminhado para\na ressecção, pois o adenocarcinoma de cólon é das poucas neoplasias sólidas do trato\ngastrointestinal que se beneficiam, em termos de sobrevida global, de ressecções de focos de\ndoença metastática.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-255680","number":"255680","sourceNumber":"255680","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma paciente de 65 anos de idade está investigando uma massa cervical. Na consulta,\ndescobre que apresenta um tumor de tireoide. O exame anatomopatológico dela demonstra\nneoplasia folicular. Não há indícios de metástases. Além disso, a paciente apresentava hipertensão\nsecundária. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a\nseguir. Em geral, a cirurgia é o modo apropriado para o tratamento desse tipo de tumor.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-255681","number":"255681","sourceNumber":"255681","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma paciente de 65 anos de idade está investigando uma massa cervical. Na consulta,\ndescobre que apresenta um tumor de tireoide. O exame anatomopatológico dela demonstra\nneoplasia folicular. Não há indícios de metástases. Além disso, a paciente apresentava hipertensão\nsecundária. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a\nseguir. Tumores foliculares geralmente são uninodulares quando comparados a papilíferos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-255689","number":"255689","sourceNumber":"255689","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente com 65 anos de idade foi ao urologista por descobrir um tumor renal. Ele\napresenta múltiplas comorbidades de risco proibitivo cardiovascular no momento. Na avaliação, o\ntumor era localizado e sem metástases. Acerca desse caso clínico e com base nos conhecimentos\nmédicos correlatos, julgue o item a seguir. A resposta ao sorafenib é excelente no aumento da\nexpectativa de vida.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-239280","number":"239280","sourceNumber":"239280","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma paciente de 73 anos de idade, residente na cidade do Rio de Janeiro-RJ, é\ndiabética e hipertensa. Negou história de\ntabagismo ativo ou passivo. Procurou atendimento de\nemergência por dispneia, tosse produtiva, febre de 39°C e dor torácica ventilatório-dependente. Ao\nexame físico, apresentava-se em regular estado geral, alerta, PA = 80 mmHg X 50 mmHg, FC =\n115 bpm, SatO2 = 91% em ar ambiente, FR = 26 irpm; ausculta respiratória com crepitantes\npulmonares à direita. Exames complementares: Hb = 13,3g/dL, Ht = 39%, leucócitos = 19.000/mm3\ne 15% de bastões, 177 mil plaquetas, ureia = 108mg/dL, Cr = 1,6mg/dL, raio X de tórax com\nconsolidação em lobo inferior direito. Quanto ao caso clínico apresentado e tendo em vista os\nconhecimentos médicos correlatos, julgue o item a seguir. Em caso de diagnóstico de neoplasia de\npulmão para essa paciente, adenocarcinoma deve ser o tipo histológico encontrado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-239283","number":"239283","sourceNumber":"239283","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma paciente de 73 anos de idade, residente na cidade do Rio de Janeiro-RJ, é\ndiabética e hipertensa. Negou história de\ntabagismo ativo ou passivo. Procurou atendimento de\nemergência por dispneia, tosse produtiva, febre de 39°C e dor torácica ventilatório-dependente. Ao\nexame físico, apresentava-se em regular estado geral, alerta, PA = 80 mmHg X 50 mmHg, FC =\n115 bpm, SatO2 = 91% em ar ambiente, FR = 26 irpm; ausculta respiratória com crepitantes\npulmonares à direita. Exames complementares: Hb = 13,3g/dL, Ht = 39%, leucócitos = 19.000/mm3\ne 15% de bastões, 177 mil plaquetas, ureia = 108mg/dL, Cr = 1,6mg/dL, raio X de tórax com\nconsolidação em lobo inferior direito. Quanto ao caso clínico apresentado e tendo em vista os\nconhecimentos médicos correlatos, julgue o item a seguir. Um paciente com neoplasia de pulmão e\ntumor de tamanho de 7,5 cm possui estádio clínico II.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-212008","number":"212008","sourceNumber":"212008","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente adulto jovem, com quadro de linfoma maligno, com massa mediastinal\nsuperior, apresenta edema de face e do pescoço,\ndispneia e tosse, com queixa de rouquidão e\ncefaleia. A equipe de oncologia admitiu o quadro como síndrome da veia cava superior. Então\nforam ministrados diuréticos, com dieta hipossódica, e oxigenoterapia com alívio temporário dos\nsintomas. Em relação a esse caso clínico, quanto à opção de terapêutica para recidiva da síndrome\nde veia cava superior, assinale a alternativa correta.","options":{"A":"Radioterapia com tumorectomia descompressiva.","B":"Stent intravascular autoexpansível.","C":"Uso contínuo de corticoide e antibióticos.","D":"Soroterapia em bolus, para aumentar o volume intravascular.","E":"Realização de um shunt venoso para descomprimir."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-214511","number":"214511","sourceNumber":"214511","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente de 65 anos de idade, tabagista pesado (dois maços de cigarro por dia) há\nmais de 15 anos, apresenta tosse e dispneia em atendimento no pronto-socorro. Os raios X de\ntórax demonstram lesão de 2 cm no segmento anterior do lobo superior esquerdo. Ao exame físico,\nverificam-se sibilos expiratórios e estertores crepitantes em bases à ausculta pulmonar, frequência\nrespiratória de 28 mrpm, frequência cardíaca de 75 bpm e saturação de O? de 88% em ar\nambiente. Com base no caso clínico apresentado e nos conhecimentos médicos correlatos, julgue o\nitem a seguir. A maior parte dos casos de câncer de pulmão, atualmente, é diagnosticada antes do\naparecimento dos sintomas por causa dos recursos disponíveis.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-214512","number":"214512","sourceNumber":"214512","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente de 65 anos de idade, tabagista pesado (dois maços de cigarro por dia) há\nmais de 15 anos, apresenta tosse e dispneia em atendimento no pronto-socorro. Os raios X de\ntórax demonstram lesão de 2 cm no segmento anterior do lobo superior esquerdo. Ao exame físico,\nverificam-se sibilos expiratórios e estertores crepitantes em bases à ausculta pulmonar, frequência\nrespiratória de 28 mrpm, frequência cardíaca de 75 bpm e saturação de O? de 88% em ar\nambiente. Com base no caso clínico apresentado e nos conhecimentos médicos correlatos, julgue o\nitem a seguir. Em relação ao screening do câncer de pulmão, o paciente ideal para realização\ndesse procedimento é aquele tabagista entre 55 anos e 74 anos de idade, com carga tabágica de\npelo menos 30 maços.ano, que ainda fuma ou deixou de fumar há menos de 15 anos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-196597","number":"196597","sourceNumber":"196597","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Determinado paciente de 60 anos de idade, tabagista e etilista de longa data, vinha\napresentando, há seis meses, disfagia progressiva e perda de peso. Foi então realizada uma\nendoscopia que demonstrou lesão ulcerada em esôfago médio. O paciente foi submetido a\nestadiamento e manifestou doença local, sem sinais de doença linfonodal em tomografia\ncomputadorizada. A biópsia demonstrou carcinoma de células escamosas de esôfago. Em relação\nao caso clínico apresentado e aos conhecimentos médicos correlatos, julgue o item a seguir. O\npaciente deve ser submetido a cirurgia com ressecção de lesão tumoral e linfonodos regionais,\nalém da reconstrução do trânsito gastrointestinal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-196599","number":"196599","sourceNumber":"196599","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Determinado paciente de 60 anos de idade, tabagista e etilista de longa data, vinha\napresentando, há seis meses, disfagia progressiva e perda de peso. Foi então realizada uma\nendoscopia que demonstrou lesão ulcerada em esôfago médio. O paciente foi submetido a\nestadiamento e manifestou doença local, sem sinais de doença linfonodal em tomografia\ncomputadorizada. A biópsia demonstrou carcinoma de células escamosas de esôfago. Em relação\nao caso clínico apresentado e aos conhecimentos médicos correlatos, julgue o item a seguir. A\nultrassonografia endoscópica pode ajudar a avaliar a invasão de parede pelo tumor.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-211923","number":"211923","sourceNumber":"211923","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente de 32 anos de idade, apresenta achado incidental de nódulo 0,8 cm no\nlobo direito da tireoide, ao realizar ecografia cervical. A punção aspirativa por agulha fina (PAAF)\nmostra citologia compatível com Bethesda VI. A respeito desse caso clínico e considerando os\nconhecimentos médicos correlatos, no que concerne às patologias de tireoide, assinale a\nalternativa correta.","options":{"A":"A tireoidectomia parcial é uma opção de tratamento cirúrgico adequado para a patologia dessa\npaciente.","B":"Uma das desvantagens da tireoidectomia parcial são as taxas mais altas de hipocalemia.","C":"A punção aspirativa por agulha fina (PAAF) tem alta sensibilidade e especificidade para\nconfirmar patologia benigna de tireoide.","D":"A lobectomia seria uma opção terapêutica para essa paciente.","E":"O principal nervo lesado na tireoidectomia é o nervo vago."},"answer":"E","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-214470","number":"214470","sourceNumber":"214470","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma paciente de 56 anos de idade chega à emergência queixando-se de desconforto\nemU andar superior do abdome, com sensação de\nnáuseas, iniciados há cerca de três dias. Relata\nque hoje apresentou calafrios, náuseas e vômitos e que, no momento, está com mal-estar e\ntontura. Na avaliação inicial, encontra-se em regular estado geral, com fácies de dor, ictérica, com\nPA = 90 mmHg x 50 mmHg, temperatura axilar (Tax) = 38,4 °C, FR = 26 irpm e Sat = 96%. Ao\nexame, refere dor à palpação de quadrante superior direito do abdome e apresenta vesícula\npalpável. Durante anamnese, refere quadro prévio de diabetes mellitus tipo 2 insulinodependente,\nhipertensão arterial e obesidade (IMC = 32 kg/m²). Quando questionada a respeito da icterícia,\ncontou que, nos últimos três meses, respectivos familiares disseram frequentemente que ela\nprecisava de uma dieta melhor, pois \"parecia amarelada e estava emagrecendo muito rápido\".\n\nMenciona já ter apresentado um episódio com sintomas semelhantes há cerca de dois meses,\nporém com menor intensidade e sem a presença\nde febre e tontura. Relata que o episódio teve\nresolução espontânea e que a coloração amarelada da pele \"sumiu por um tempo\". Quanto a esse\ncaso clínico e com base nos conhecimentos correlatos, julgue o item a seguir. A presença de\nicterícia de caráter flutuante, no histórico da paciente, exclui a possibilidade de uma neoplasia da\npapila de Vater.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-214474","number":"214474","sourceNumber":"214474","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma paciente de 56 anos de idade chega à emergência queixando-se de desconforto\nemU andar superior do abdome, com sensação de\nnáuseas, iniciados há cerca de três dias. Relata\nque hoje apresentou calafrios, náuseas e vômitos e que, no momento, está com mal-estar e\ntontura. Na avaliação inicial, encontra-se em regular estado geral, com fácies de dor, ictérica, com\nPA = 90 mmHg x 50 mmHg, temperatura axilar (Tax) = 38,4 °C, FR = 26 irpm e Sat = 96%. Ao\nexame, refere dor à palpação de quadrante superior direito do abdome e apresenta vesícula\npalpável. Durante anamnese, refere quadro prévio de diabetes mellitus tipo 2 insulinodependente,\nhipertensão arterial e obesidade (IMC = 32 kg/m²). Quando questionada a respeito da icterícia,\nconto que, nos últimos três meses, respectivos familiares disseram frequentemente que ela\nprecisava de uma dieta melhor, pois \"parecia amarelada e estava emagrecendo muito rápido\".\n\nMenciona já ter apresentado um episódio com sintomas semelhantes há cerca de dois meses,\nporém com menor intensidade e sem a presença\nde febre e tontura. Relata que o episódio teve\nresolução espontânea e que a coloração amarelada da pele \"sumiu por um tempo\". Quanto a esse\ncaso clínico e com base nos conhecimentos correlatos, julgue o item a seguir. A presença de\nobesidade e de diabetes mellitus no histórico são fatores de risco para suspeitar de uma neoplasia\nde cabeça de pâncreas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-179168","number":"179168","sourceNumber":"179168","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Assinale a alternativa que apresenta a maior possibilidade de carcinoma diferenciado\nda tireoide, com indicação de realização de\npunção guiada por ultrassonografia, em paciente com\ndiagnóstico de doença nodular tireoidiana.","options":{"A":"TSH elevado e hipofunção por cintilografia","B":"TSH elevado e baixa ecogenicidade ecográfica","C":"TSH normal ou baixo e hiperfunção por cintilografia","D":"TSH baixo e nódulos impalpáveis detectados por ultrassom","E":"TSH baixo e nódulos múltiplos"},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-177591","number":"177591","sourceNumber":"177591","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"J.S.A., de 55 anos de idade, negra, viúva, com três filhos, hígida, com alimentação\nsaudável, assídua praticante de exercício\nfísico, vai à consulta para a realização de exames de\nrotina. Refere menopausa há 15 anos. Ao exame físico completo, não se encontra nenhuma\nalteração, exceto palidez de mucosas. Apresenta hemograma realizado em pronto atendimento por\nqueixas gripais, há 2 semanas, com anemia microcítica e índice de anisocitose aumentado. Com\nrelação à avaliação desse quadro, julgue o item a seguir. A retossigmoidoscopia é indicada para\nesse paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-154398","number":"154398","sourceNumber":"154398","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"A. A. C. 78 anos de idade, sexo feminino, comparece ao ambulatório com queixa de\nrouquidão progressiva há três meses. Refere que associadamente vem apresentando quadro de\ntosse com hemoptoico, dispneia e disfagia para sólidos, inclusive se alimentando no momento com\nalimentos liquidificados. Negou perda ponderal importante nos últimos seis meses, assim como\noutras queixas. Faz uso irregular de levotiroxina 88 mcg há 10 anos. Clinicamente é percebido\naumento difuso da tireoide de aspecto endurecido e com aparente nodulação que segue na direção\ndo estreito torácico, sendo os linfonodos cervicais palpáveis e sem alterações. Pela\nultrassonografia\ncervical, solicitada por outro clínico, observa-se parênquima heterogêneo com múltiplos pequenos\nnódulos, grande nodulação de crescimento expansivo em direção ao tórax, com aspecto misto e\ncom trama vascular periférica aumentada e medindo 12 cm no maior eixo. Acerca do caso clínico\nexposto, assinale a alternativa correta.","options":{"A":"Os sintomas de tosse com hemoptoico, dispneia e disfagia para sólidos sugerem invasão\nlocorregional e malignidade. A disfonia\nrelatada corresponde ao encarceramento do nervo laríngeo\ncolateral, responsável pela inervação da musculatura das pregas vocais.","B":"A hipercalcitoninemia está associada à disseminação dos carcinomas papilar e folicular de\ntireoide, podendo provocar manifestações a distância, como prurido, rubores e diarreia.","C":"No restreamento dos módulos tireoidianos aqueles que apresentam diâmetro máximo maior que\n1,0 cm e menor que 1,5 cm são elegíveis para biópsia por aspiração com agulha fina.\nEstatisticamente, 20% dessas biópsias produzem material citológico adequado, mas\ndiagnosticamente indeterminado. Para nódulos com essas características, considera-se que a\nrespectiva natureza histológica é maligna, sendo impositiva a realização de cirurgia.","D":"O carcinoma medular da tireoide origina-se das células C derivadas das cristas neurais, sendo\nclassificado como tumor epitelial com características neuroendócrinas. As células C têm atividade\nbiossimétrica diversa e secretam entre outros calcitonina e antígeno e carcinoembriogênio (CEA)\nimportantes marcadores séricos desse tipo histológico.","E":"A biópsia por aspiração com agulha fina é o exame mais preciso para excluir ou confirmar a\n\ndoença maligna em pacientes que apresentam nódulo suspeito e níveis de TSH normais. A\nultrassonografia cervical não é necessária antes da biópsia, mesmo considerando que o respectivo\nuso auxilia a definir precisamente o tamanho da lesão, se tem natureza estática ou sólida e se há\nnódulos adicionais."},"answer":"E","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-152155","number":"152155","sourceNumber":"152155","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Considere as três situações seguintes: Paciente 1 - O. S., 34 anos de idade, queixa-se\nde dispneia e desconforto respiratório leve, FR\n= 19 irpm, Sat O2 = 98% e PA de 130 x 80 mmHg;\nPaciente 2 - B. M. S., 65 anos de idade, trabalhador rural, vai à consulta para esclarecer dúvidas a\nrespeito de uma mancha escura na face, perda ponderal e massa palpável no abdome; Paciente 3 -\nAdolescente deu entrada na emergência, após acidente motociclístico, com sangramento ativo de\ndifícil controle em MSE, FC = 99 bpm, PA de 110 x 70 mmHg, consciente e manifestando sede.\n\nCom relação aos casos clínicos apresentados, julgue o item a seguir. Outro possível diagnóstico\npara o Paciente 2 seria o de sarcoma de partes\nmoles; estando a maioria situada nas vísceras,\nsendo que 2/3 das lesões ocorrem no retroperitônio.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-152140","number":"152140","sourceNumber":"152140","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Considere hipoteticamente que o paciente R. A. S., de 60 anos de idade, agenda\nconsulta ambulatorial de retorno para entregar\nresultados de uma endoscopia digestiva alta e de\numa ultrassonografia de rins e vias urinárias. O paciente trouxe receita do vizinho que teve o\nmesmo problema de saúde, porém melhorou após o uso de determinados medicamentos\nprescritos. R. A. S. apresenta antecedente pessoal de fratura exposta da tíbia com dano extenso às\npartes moles e antecedente familiar de acalasia no pai. Estava ansioso porque, após pesquisa na\ninternet, assemelhou os respectivos sintomas aos de alguns tipos de câncer. Com base nesse caso\nclínico, e considerando os conhecimentos médicos a ele relacionados, julgue o item a seguir.\n\nCâncer precoce de esôfago corresponde aos tumores limitados à camada mucosa, sem presença\nde metástases linfonodais, e essa categoria é\ndiferente do câncer superficial de esôfago.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-154331","number":"154331","sourceNumber":"154331","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente com hiporexia e perda ponderal, astenia, diarreia e vertigem comparece para\navaliação médica. Ao exame, observa-se paciente ictérico. Ele refere dorsalgia progressiva nos\núltimos anos, e nega antecedentes pessoais patológicos. Trouxe resultados de exames de rotina,\ntodos inalterados, exceto pela glicemia de jejum de 200 mg/dl. A respeito do caso exposto, e\nconsiderando os tumores pancreáticos, é CORRETO afirmar que o (a):","options":{"A":"Principal tumor pancreático é o neuroendócrino, e o tipo histológico mais comum é o infiltrante.","B":"Localização mais frequente é a cauda do pâncreas (70% dos casos).","C":"Sexo feminino é fator de risco e tem relação inquestionável com o uso de anticoncepcionais\nhormonais orais ? o tumor é mais comum entre\naqueles acima de 30 anos de idade, que fazem uso\nde anticoncepcionais por mais de cinco anos.","D":"Câncer de pâncreas é o tumor gastrointestinal mais agressivo e apenas 5% dos pacientes com\nesse quadro sobrevivem após cinco anos.","E":"Maioria é sintomática na respectiva fase inicial."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-154349","number":"154349","sourceNumber":"154349","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente, 60 anos de idade, em investigação de anemia por perda de origem\nindeterminada, comparece para mostrar resultados\nde exames de endoscopia digestiva alta e\ncolonoscopia. Queixa-se ainda de alteração do hábito intestinal, intercalando entre diarreia e\nconstipação, de distensão abdominal e cólicas, hematoquezia e de tenesmo anal. Em razão desse\nquadro, retorna ao consultório em busca de orientação médica quanto ao risco de cancer colorretal.\nConsiderando esse caso clinico, é correto afirmar que o fator de risco reconhecido para o\ndesenvolvimento de Câncer Colorretal (CCR) esporádico é a (o):","options":{"A":"Idade avançada.","B":"Polipose Adenomatosa Familiar (PAF).","C":"Câncer Colorretal Hereditário Não Associado a Polipose (HNPCC).","D":"Polipose juvenil.","E":"Síndrome de Peutz-Jeghers."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-154359","number":"154359","sourceNumber":"154359","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente com perda ponderal e anorexia, astenia, plenitude pós-prandial, vômitos,\nnáuseas e dispepsia crônica comparece para\ndefinição diagnóstica. Ao exame, há dor à palpação\nepigástrica, massa palpável em epigástrio, hepatomegalia e nódulos de Virchow e de Irmã Maria\nJosé, além de ascite. Paciente relata também episódio isolado de hematêmese e de melena.\n\nAcerca do caso apresentado, é correto afirmar que, no câncer gástrico, entre os sinais\npropedêuticos de doença avançada, o que mais se\ntraduz em carcinomatose peritoneal é o (a):","options":{"A":"Nódulo de Virchow.","B":"Nódulo de Irmã Maria José.","C":"Prateleira de Blummer.","D":"Gânglio de Irish.","E":"Ascite."},"answer":"E","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-135012","number":"135012","sourceNumber":"135012","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"No próximo item é apresentado um caso clínico seguido de uma assertiva a ser julgada.\nUma criança do sexo masculino de nove anos de idade foi levada pela mãe ao serviço médico por\napresentar nódulo no pescoço. Ao palpar a tireoide da criança, o médico observou um nódulo\nendurecido no lobo direito. Os exames laboratoriais revelaram dosagem de hormônios tireoidianos\nnormais. A cintilografia e a ultrassonografia da tireoide resultaram, respectivamente, em nódulos\nhipocaptante (frio) e nódulo sólido de 12 mm de diâmetro. A mãe da criança relatou que ela e a tia\nmaterna do paciente apresentaram tumores no pâncreas e na tireoide. Nesse caso, todos os\nelementos clínicos e de imagem não indicam a possibilidade de carcinoma da tireoide.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-131853","number":"131853","sourceNumber":"131853","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O câncer na infância e na adolescência é responsável por 1% das neoplasias\nidentificadas na população geral. Em relação às\nneoplasias na população pediátrica, assinale a\nalternativa correta.","options":{"A":"O tumor de Wilms é originário de tecidos embrionários do rim, carateriza-se por massa\nabdominal que não ultrapassa a linha média, e está associado à aniridia e a anormalidades\ngenitourinárias.","B":"O neuroblastoma é originário do sistema nervoso simpático periférico e é o tumor sólido fora do\nsistema nervoso central (SNC) mais incomum na infância.","C":"O tumor de fossa posterior mais frequente na infância é o astrocitoma e cursa com sintomas de\nhipertensão intracraniana e ataxia.","D":"A doença de Hodgkin é o grupo de linfoma mais frequente na infânica e sua célula característica\né chamada de Reed-Sternberg.","E":"As leucemias são a malignidade mais comum na infância, sendo a mieloide crônica o subtipo\nmais comum."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-135020","number":"135020","sourceNumber":"135020","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Com relação ao tratamento do paciente com câncer, julgue o próximo item. Situação\nhipotética: Um paciente de cinquenta anos\nde idade, sem história familiar de neoplasia colorretal,\ndurante rastreamento de câncer colorretal, foi submetido à mucosectomia devido à identificação de\ndois pólipos adenomastosos tubulares com displasia de baixo grau, sendo um de 4 mm e outro de\n5 mm. Assertiva: Nesse caso, deve-se submeter o paciente à realização de controle\nvideocolonoscópico em três anos. Caso não seja identificada a presença de pólipos nesse controle,\no novo segmento deverá ocorrer após dez anos.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-131813","number":"131813","sourceNumber":"131813","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente masculino de 60 anos de idade, sem comorbidades, deu entrada no\npronto-socorro com quadro de parada de eliminação de gazes e fezes, vômitos fecaloides e\ndistensão abdominal há três dias. Ao exame físico, apresentava-se em REG, desidratado,\n\ndescorado, e taquicárdico. O abdome se apresentava distendido, com ruídos de luta, com sinais de\nirritação peritoneal. O hemograma era de 20.000 leucócitos, com desvio à esquerda de 12%, e os\nraios X mostravam distensão com stop no sigmoide e sinal de Ridler. A respeito desse caso\nhipotético, assinale a alternativa que indica o diagnóstico mais provável.","options":{"A":"Neoplasia de sigmoide obstrutiva complicada com perfuração em cavidade peritoneal.","B":"Bridas.","C":"Íleo biliar.","D":"Apendicite complicada.","E":"Hérnia inguinal com sofrimento de alça e perfuração."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-140706","number":"140706","sourceNumber":"140706","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Em relação à oncologia cirúrgica dos órgãos intra-abdominais, julgue o item a seguir. O\nadenocarcinoma primário de cabeça do pâncreas tende a gerar sintomas mais precocemente que\nos tumores localizados no corpo ou na cauda desse órgão.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-131850","number":"131850","sourceNumber":"131850","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente masculino de 60 anos de idade, sem comorbidades, deu entrada no\npronto-socorro com quadro de parada de eliminação de gazes e fezes, vômitos fecaloides e\ndistensão abdominal há três dias. Ao exame físico, apresentava-se em REG, desidratado,\n\ndescorado, e taquicárdico. O abdome se apresentava distendido, com ruídos de luta, com sinais de\nirritação peritoneal. O hemograma era de 20.000 leucócitos, com desvio à esquerda de 12%, e os\nraios X mostravam distensão com stop no sigmoide e sinal de Ridler. Considere que o paciente do\ncaso hipotético tenha evoluído bem no pós-operatório, seu estadiamento anatomocirúrgico TNM foi\nT3N0M0, mas, ao realizar tomografia computadorizada de abdome de estadiamento, observou-se\numa lesão de 2 cm em lobo esquerdo e cujo PET-Scan mostrou captação de contraste e antígeno\ncarcinoembrionário (CEA) de 15 (normal até 5 para não fumantes). Com base nessa situação,\nassinale a alternattiva que indica a melhor conduta no caso clínico apresentado.","options":{"A":"Apenas seguimento.","B":"Quimioterapia neoadjuvante com Folfox ou Folfiri associado a biológicos + ablação por\nradiofrequência via laparoscópica.","C":"Ressecção imediata aberta da lesão com margem de 1 cm.","D":"Quimioembolização com lipiodol + doxorrubicina.","E":"Quimioterapia exclusiva com 5-fluoracil."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-131827","number":"131827","sourceNumber":"131827","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Considere hipoteticamente que certo paciente de 67 anos da idade, hígido, com boa\nperformance status, procurou o serviço de cirurgia com disfagia e emagrecimento. Na endoscopia\ndigestiva alta, observou-se lesão polipoide de 3 cm limitada a 20% da luz esofágica a 37 cm da\narcada dentária superior. Os exames de imagem indicaram lesão limitada ao esôfago sem\ndisseminação a distância, assim como PET-Scan, e a ecoendoscopia classificou como T4N1M0.\nCom base no exposto assinale a alternativa que indica a conduta mais apropriada nesse caso\nclínico.","options":{"A":"Quimioterapia exclusiva com cisplatina.","B":"Esofagectomia por toracotomia - Ivor-Lewis.","C":"Ressecção endoscópica por ecoendoscopia.","D":"Radioterapia e quimioterapia exclusivas.","E":"Esofagectomia subtotal transhiatal com gastric pull-up."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-131838","number":"131838","sourceNumber":"131838","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"No que se refere aos tumores de intestino delgado, assinale a alternativa correta.","options":{"A":"Apesar do longo comprimento do intestino delgado, as neoplasias são raras e constituem cerca\nde 2,8% dos tumores malignos do trato\ndigestório.","B":"Raramente ocorre doença a distância na respectiva apresentação inicial.","C":"O adenocarcinoma é o tipo histológico mais comum e de melhor prognóstico.","D":"O carcinoma é mais comum no jejuno proximal.","E":"O carcinoide, quando metastático para o fígado, é considerado fora de possibilidade para o\ntratamento cirúrgico e não deve ser ressecado, com exceção nos casos de obstrução ou\nhemorragia."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-131806","number":"131806","sourceNumber":"131806","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Com relação ao tumor desmoide, assinale a alternativa correta.","options":{"A":"Não tem relação com a polipose adenomatosa familiar (FAP).","B":"É um tumor maligno e metastatizante.","C":"É afecção de idosos.","D":"Pode ocorrer em até 30% dos casos de FAP.","E":"Após ressecção cirúrgica, apresenta baixos índices de recorrência, em torno de 5%."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-134974","number":"134974","sourceNumber":"134974","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Com relação à pesquisa clínica do câncer de intestino, julgue o item que se segue. A\npesquisa de sangue oculto nas fezes é dispensável para análise sobre lesões neoplásicas de\norigem colorretal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-135071","number":"135071","sourceNumber":"135071","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Em relação ao câncer na infância, julgue o próximo item. O pediatra deve promover\nações preventivas contra o câncer infantil, as\nquais incluem desde uma alimentação adequada até\norientações sobre como reduzir infecções causadas por agentes carcinogênicos, como a bactéria\nHelicobacter pylori e o vírus da hepatite B.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-105535","number":"105535","sourceNumber":"105535","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Assinale a alternativa que apresenta o tumor funcionante mais comum do pâncreas.","options":{"A":"Gastrinoma.","B":"VIPoma (síndrome de Verner-Morrison).","C":"Glucagonoma.","D":"Insulinoma.","E":"Somatostatinoma."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-105541","number":"105541","sourceNumber":"105541","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Acerca do câncer de próstata, assinale a alternativa CORRETA:","options":{"A":"Atualmente, na maioria dos casos, o toque retal alterado é o primeiro sinal clínico ou\nlaboratorial\nencontrado.","B":"Os valores aceitáveis como normais para o Antígeno Prostático Específico (PSA) diminuem em\nhomens mais velhos por conta da redução na\nprodução de andrógenos.","C":"Considerando-se indivíduos de mesma faixa etária, os valores de Antígeno Prostático Específico\n(PSA) podem ser um pouco maiores em pessoas\nde raça negra.","D":"O exame de ressonância magnética da pelve é o exame padrão-ouro para o diagnóstico.","E":"A queixa, pelo paciente, de urgência miccional e nictúria, praticamente exclui o diagnóstico\ndiferencial com hiperplasia prostática benigna."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-105536","number":"105536","sourceNumber":"105536","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um homem de 75 anos de idade foi atendido no posto de saúde com história de dor\nabdominal tipo cólica de leve a moderada intensidade há cerca de um mês. Referiu que\napresentava hematoquezia há cerca de três meses e que, há duas semanas, notou tumor na fossa\nilíaca esquerda de +/- 10 cm de diâmetro. Negou febre e referiu astenia e perda de cerca de 10%\nde seu peso habitual nos últimos dois meses. Negou antecedentes familiares de neoplasias,\ndiabetes e doenças cardiológicas. Considerando esse caso e a hipótese diagnóstica de câncer no\ncólon, assinale a alternativa CORRETA:","options":{"A":"Essa hipótese está enfraquecida, pois, ao contrário do caso descrito, na maior parte dos\npacientes com câncer colorretal o componente genético está presente.","B":"A colonoscopia com biópsia é o melhor exame para o diagnóstico.","C":"A dosagem de Antígeno Carcinoembrionário (CEA) é excelente no rastreamento dessas lesões.","D":"O diagnóstico diferencial com câncer de próstata impõe-se, no presente caso, considerando-se a\nfaixa etária do paciente.","E":"Caso se confirme o diagnóstico de câncer no cólon sigmoide, a terapia neoadjuvante (radio e\nquimioterapia) deverá ser indicada."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-105542","number":"105542","sourceNumber":"105542","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Na atualidade, está bem estabelecido que diversos tipos de cânceres representam\nsíndromes de câncer familiar, a maior parte\nherdada de modo autossômico dominante e com\npenetrância variável. Acerca dos cânceres que apresentam essas características, assinale a\nalternativa correta.","options":{"A":"A síndrome de von Hippel-Lindau é rara e caracterizada pelo desenvolvimento de tumores\naltamente vascularizados em múltiplos órgãos.","B":"A associação de cânceres de mama, colorretal e de cérebro caracterizam a síndrome de\nLi-Fraumeni.","C":"O retinoblastoma, cujo gene causador é o RB1, acomete, na grande maioria, indivíduos a partir\nda sexta década de vida.","D":"Ao contrário da maioria, a polipose adenomatosa familiar, ou síndrome de Lynch, é de herança\nrecessiva.","E":"A neoplasia endócrina múltipla do tipo 2A é caracterizada por feocromocitoma, tumores de\nhipófise e ilhotas pancreáticas."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-88660","number":"88660","sourceNumber":"88660","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"A propósito das doenças oncológicas, julgue o próximo item. O câncer colorretal tem\nmaior incidência em pessoas que se alimentam de gorduras saturadas e de alimentos com baixo\nteor de cálcio.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-352402","number":"352402","sourceNumber":"352402","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um homem de 57 anos de idade com histórico de Doença Pulmonar Obstrutiva Crônica\ne hipertensão arterial bem controlada com\nlosartana 100 mg por dia, e que deixou de fumar há 2\nanos após 50 anos de tabagismo (50 maços-ano), apresenta-se no ambulatório com uma queixa de\ndor lombar crônica persistente há 2 anos. Ele relata ter sofrido uma queda da própria altura durante\no banho, que resultou em uma dor intensa e súbita, acompanhada por uma limitação significativa\ndos movimentos. Isso o levou a se afastar do trabalho por um período de 7 dias. Embora tenha\nretomado suas atividades laborais, continua a experimentar dor lombar constante que, por vezes, o\nacorda durante a noite. O paciente menciona ter buscado assistência em múltiplos\n\nprontos-socorros, onde recebeu apenas tratamento sintomático. Ele faz uso de anti-inflamatórios,\nque proporcionam algum alívio, mas não resolvem o\nquadro. Além disso, recorre ao tramadol\nesporadicamente. Embora relate ocasional tosse, foi sua significativa piora na dor lombar na última\nsemana que o levou a procurar atendimento médico particular. Nesse atendimento particular, foram\nsolicitados exames complementares, um de imagem e um laboratorial, cujos resultados estão\napresentados abaixo. Considerando o quadro clínico exposto bem como os exames\ncomplementares e seus diagnósticos diferenciais, julgue o item a seguir. Caso o paciente em\nquestão apresentar uma súbita intensificação da dor, especialmente aquela que o acorda durante a\nnoite, juntamente com déficits motores, alterações no nível sensitivo ou anestesia em sela, isso\nconfigura uma emergência característica desse quadro cujo exame padrão-ouro para a\ninvestigação é a ressonância magnética da coluna lombar.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":["question_bank/media/medcurso/med-cirurgia-med-cir-06/352402.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-343440","number":"343440","sourceNumber":"343440","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Acerca dos sintomas da Síndrome de Lynch, é INCORRETO afirmar:","options":{"A":"Presença de tumores sincrônicos no cólon.","B":"Alteração do funcionamento do trato intestinal (diarreia e prisão de ventre alternados).","C":"Sangue nas fezes.","D":"Dor ou desconforto abdominal."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-307088","number":"307088","sourceNumber":"307088","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma paciente de 57 anos de idade tem diagnóstico recente de câncer de pulmão. O\nlaudo da biópsia transtorácica apresentou um adenocarcinoma primário pulmonar, estadiamento\nclínico I A 1, com boa reserva pulmonar, de acordo com o TNM, 8ª edição. No que concerne a essa\ndoença, assinale a alternativa correta.","options":{"A":"De acordo com esse estadiamento, a paciente tem indicação de quimioterapia de primeira linha,\nseguida de radioterapia.","B":"Para esse subtipo histológico, está indicada imunoterapia como padrão-ouro para tratamento.","C":"Essa paciente tem indicação de estadiamento invasivo do mediastino.","D":"Adenocarcinoma pulmonar pode ocorrer em pacientes não fumantes e, nesse caso, é mais\ncomum no sexo feminino.","E":"Tal subtipo histológico é raro, sendo necessária a confirmação por imuno-histoquímica."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-307094","number":"307094","sourceNumber":"307094","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Assinale a alternativa correspondente ao quadro de um paciente que pode ser\nsubmetido a cirurgia de ressecção de câncer primário de pulmão.","options":{"A":"Massa de 4,9 cm, com invasão de artéria pulmonar, átrio e esôfago.","B":"Nódulo pulmonar de 1,2 cm, linfonodos mediastinais aumentados e derrame pleural neoplásico.","C":"Nódulo pulmonar solitário, com duas metástases adrenais e uma em sistema nervoso central.","D":"Nódulo de 1,2 cm em lobo superior direito, com mediastinoscopia negativa e metástase única\nadrenal a distância, submetido a adrenalectomia sem intercorrências.","E":"Nódulo pulmonar com metástases ipsilaterais e contralaterais."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-268881","number":"268881","sourceNumber":"268881","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma paciente de 45 anos de idade procura atendimento após ter realizado uma\ntomografia com contraste de abdome total, com\nachado de nódulo com realce periférico durante\nfase arterial e impregnação centrípeta pelo meio de contraste na fase tardia. Com base nesse caso\nclínico, nos conhecimentos relativos aos tumores hepáticos benignos e nos assuntos correlatos,\nassinale a alternativa incorreta.","options":{"A":"Esse tumor hepático benigno trata-se de um adenoma hepático.","B":"A utilização de anticoncepcional combinado oral deve ser suspendida imediatamente, caso se\ndiagnostique um hemangioma hepático.","C":"A ruptura espontânea de um hemangioma é extremamente rara, não se justificando a realização\nde cirurgia pelo risco de sangramento.","D":"O hemangioma é o segundo tumor benigno hepático mais comum.","E":"O hemangioma hepático tem potencial de malignização superior ao do adenoma hepático."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-266409","number":"266409","sourceNumber":"266409","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente do sexo masculino, com 60 anos de idade, procurou ambulatório com\nqueixa de disfagia progressiva, existente\nhavia 10 anos, com piora importante 2 meses antes desse\natendimento ambulatorial. No momento, queixava-se de que não conseguia se alimentar nem de\nlíquidos, com perda ponderal de 8 kg no período. Como antecedentes importantes, apresentava\numa carga tabágica de 20 maços/ano, etilismo de meio litro de destilados ao dia, epidemiologia\npositiva para doença de Chagas, sem históricos de câncer na família. A partir do caso clínico\nhipotético apresentado, julgue o item a seguir. A sorologia para doença de Chagas é essencial para\na definição do tipo de tratamento a ser realizado nesse paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-268882","number":"268882","sourceNumber":"268882","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente de 55 anos de idade, ex-alcoolista, cirrótico, portador do vírus da hepatite\nB, inicia com dor em quadrante superior direito\ne apresenta perda ponderal de 15 kg em três\nmeses. Considerando os carcinomas hepatocelulares e os conhecimentos médicos correlatos,\nassinale a alternativa correta.","options":{"A":"Mais de 50% dos pacientes cirróticos desenvolverão risco para carcinoma hepatocelulares.","B":"Esse é o tumor de fígado mais comum.","C":"A cirrose por esteato-hepatite não alcoólica (NASH) não está relacionada com o carcinoma\nhepatocelular.","D":"O diagnóstico pode ser estabelecido radiologicamente. Na fase arterial, contrasta de maneira\nmais intensa do que o parênquima hepático ao seu redor; já na fase venosa e tardia, contrasta\nmenos que o parênquima.","E":"A ultrassonografia não é um método de escolha para monitoramento de nódulos no fígado."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-266410","number":"266410","sourceNumber":"266410","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente do sexo masculino, com 60 anos de idade, procurou ambulatório com\nqueixa de disfagia progressiva, existente\nhavia 10 anos, com piora importante 2 meses antes desse\natendimento ambulatorial. No momento, queixava-se de que não conseguia se alimentar nem de\nlíquidos, com perda ponderal de 8 kg no período. Como antecedentes importantes, apresentava\numa carga tabágica de 20 maços/ano, etilismo de meio litro de destilados ao dia, epidemiologia\npositiva para doença de Chagas, sem históricos de câncer na família. A partir do caso clínico\nhipotético apresentado, julgue o item a seguir. Câncer de esôfago é uma das possíveis hipóteses\ndiagnósticas, pois o paciente apresenta vários fatores de risco para essa doença.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-268883","number":"268883","sourceNumber":"268883","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente de 62 anos de idade procura atendimento em consultório por dor\nepigástrica, saciedade precoce e perda de 5 kg no\núltimo mês, sem alterações nos seus hábitos\nalimentares. É realizada uma endoscopia digestiva alta, associada a ultrassom endoscópico e a\nbiópsia. O resultado do anatomopatológico foi positivo para Helicobacter pylori e para\nadenocarcinoma gástrico que invade a submucosa. Os linfonodos regionais não apresentam\nmetástases. Em relação a esse caso clínico e ao adenocarcinoma gástrico, assinale a alternativa\nCORRETA.","options":{"A":"A classificação de tumor primário (T) é T2.","B":"As tomografias computadorizadas de crânio, tórax, abdome e pelve são mandatórias para a\navaliação de metástases.","C":"Múltiplas biópsias (de seis a oito) devem ser realizadas em áreas diferentes da lesão, a fim de\naumentar o rendimento para 98%.","D":"A tomografia computadorizada por emissão de pósitrons (PET-TC) é essencial para o\ndiagnóstico de metástases a distância, visto que 80% dos cânceres gástricos são PET-ávidos.","E":"A infecção de Helicobacter pylori não representa um agente cancerígeno, sendo desnecessário\no seu tratamento."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-266411","number":"266411","sourceNumber":"266411","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente do sexo masculino, com 60 anos de idade, procurou ambulatório com\nqueixa de disfagia progressiva, existente\nhavia 10 anos, com piora importante 2 meses antes desse\natendimento ambulatorial. No momento, queixava-se de que não conseguia se alimentar nem de\nlíquidos, com perda ponderal de 8 kg no período. Como antecedentes importantes, apresentava\numa carga tabágica de 20 maços/ano, etilismo de meio litro de destilados ao dia, epidemiologia\npositiva para doença de Chagas, sem históricos de câncer na família. A partir do caso clínico\nhipotético apresentado, julgue o item a seguir. O tratamento cirúrgico deve ser realizado de\nimediato, devido à impossibilidade de ingesta oral pelo paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-268884","number":"268884","sourceNumber":"268884","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma paciente de 67 anos de idade iniciou fezes escuras com sangue, dor abdominal e\ndisfagia há seis meses. Evoluiu com emagrecimento espontâneo de 5 kg em 15 dias. Realizou\ncolonoscopia e endoscopia para investigação da causa do melena. Na endoscopia digestiva alta,\nfoi encontrado um tumor de 6 cm liso, com ulceração central, localizado no estômago.\n\nConsiderando esse caso clínico, acerca dos tumores estromais gastrointestinais (GIST), assinale a\nalternativa correta.","options":{"A":"Os GIST podem se formar em qualquer segmento do trato gastrointestinal, principalmente, no\nestômago, no intestino delgado e no cólon.","B":"Os fatores de risco mais comuns para malignidade são o tamanho da lesão e os números de\nmetástases linfonodais.","C":"Os lugares mais propícios para a progressão do GIST são o cérebro e o pulmão.","D":"A ruptura do tumor intra-abdominal é extremamente comum e, com a devida estabilidade\nhemodinâmica, ele pode ser embolizado.","E":"A imuno-histoquímica não ajuda no diagnóstico diferencial para outros tumores gástricos."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-266412","number":"266412","sourceNumber":"266412","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente do sexo masculino, com 60 anos de idade, procurou ambulatório com\nqueixa de disfagia progressiva, existente\nhavia 10 anos, com piora importante 2 meses antes desse\natendimento ambulatorial. No momento, queixava-se de que não conseguia se alimentar nem de\nlíquidos, com perda ponderal de 8 kg no período. Como antecedentes importantes, apresentava\numa carga tabágica de 20 maços/ano, etilismo de meio litro de destilados ao dia, epidemiologia\npositiva para doença de Chagas, sem históricos de câncer na família. A partir do caso clínico\nhipotético apresentado, julgue o item a seguir. Os sinais e sintomas da acalasia são causados\nprincipalmente pela falha de relaxamento do esfíncter esofagiano inferior durante a deglutição.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-291467","number":"291467","sourceNumber":"291467","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 60 anos de idade, masculino, procura hospital de atenção secundária com\nhistória de \"olhos amarelados\" há cerca de 4 semanas. Refere \"desconforto\" discreto em epigástrio\ne hipocôndrio direito. Nega febre. Ao exame físico, paciente emagrecido, ictérico 4+/4+, eupneico,\nnormocorado. Abdome plano, flácido, depressível, com vesícula biliar palpável, indolor, sinal de\nMurphy negativo. Com base nessas informações, qual hipótese diagnóstica para o caso clínico\ndescrito?","options":{"A":"Pancreatite aguda.","B":"Colangite.","C":"Abscesso hepático.","D":"Neoplasia de cabeça de pâncreas."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-266418","number":"266418","sourceNumber":"266418","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma mulher de 55 anos de idade realizou um ultrassom de abdome de rotina, solicitado\npelo seu ginecologista em consulta anual. O\nultrassom evidenciou lesão cística de\naproximadamente 4 cm, contendo septações, em cauda pancreática. A mulher não apresenta\nqueixas abdominais nem antecedentes importantes. Com relação ao caso clínico precedente e às\nlesões císticas pancreáticas, julgue o próximo item. Entre as lesões císticas do pâncreas, há\npredomínio de lesões benignas.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-266419","number":"266419","sourceNumber":"266419","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma mulher de 55 anos de idade realizou um ultrassom de abdome de rotina, solicitado\npelo seu ginecologista em consulta anual. O\nultrassom evidenciou lesão cística de\naproximadamente 4 cm, contendo septações, em cauda pancreática. A mulher não apresenta\nqueixas abdominais nem antecedentes importantes. Com relação ao caso clínico precedente e às\nlesões císticas pancreáticas, julgue o próximo item. Para a paciente do caso relatado, há indicação\nde seguimento da lesão por ultrassom, pela alta sensibilidade, ou tomografia computadorizada de\nabdome.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-266420","number":"266420","sourceNumber":"266420","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma mulher de 55 anos de idade realizou um ultrassom de abdome de rotina, solicitado\npelo seu ginecologista em consulta anual. O\nultrassom evidenciou lesão cística de\naproximadamente 4 cm, contendo septações, em cauda pancreática. A mulher não apresenta\nqueixas abdominais nem antecedentes importantes. Com relação ao caso clínico precedente e às\nlesões císticas pancreáticas, julgue o próximo item. A neoplasia mucinosa papilar intraductal pode\nacometer o ducto pancreático principal e(ou) os ductos secundários, sendo o risco de malignização\nmaior quando ela acomete o ducto principal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-266421","number":"266421","sourceNumber":"266421","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma mulher de 55 anos de idade realizou um ultrassom de abdome de rotina, solicitado\npelo seu ginecologista em consulta anual. O\nultrassom evidenciou lesão cística de\naproximadamente 4 cm, contendo septações, em cauda pancreática. A mulher não apresenta\nqueixas abdominais nem antecedentes importantes. Com relação ao caso clínico precedente e às\nlesões císticas pancreáticas, julgue o próximo item. As lesões císticas mucinosas têm pouco risco\nde malignização e, em regra, não é necessário operá-las.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-263353","number":"263353","sourceNumber":"263353","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma paciente com 20 anos de idade notou nodulação na região central do pescoço.\nProcurou atendimento médico ambulatorial, no qual\nfoi solicitada dosagem de hormônio tireoidiano\n(com resultados normais) e ultrassonografia com Punção Aspirativa por Agulha Fina (PAAF) do\nnódulo. O resultado foi nódulo de 1 cm em lobo esquerdo da tireoide, hipoecoico, de margens\nirregulares, sem calcificação. A PAAF não conseguiu distinguir entre lesão maligna ou benigna\n(Bethesda IV). O resultado do Perfil de Expressão Gênica (PEG) indicou suspeita para malignidade.\nA conduta médica adequada para esse caso é:","options":{"A":"Observar clinicamente e repetir ultrassonografia a cada 3 meses.","B":"Repetir ultrassonografia e realizar nova punção aspirativa com agulha fina.","C":"Indicar tireoidectomia total com esvaziamento cervical do lado esquerdo.","D":"Indicar cirurgia com retirada apenas do lobo esquerdo sem linfadenectomia."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-273331","number":"273331","sourceNumber":"273331","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Dentre as síndromes de câncer familiar, é correto afirmar que:","options":{"A":"Polipose adenomatosa familiar está relacionada à mutação do gene BRCA 1 (17q12-3) e câncer\nde célula renal.","B":"A síndrome de Li Fraumeni está relacionada à mutação do gene P16 (3p21) e feocromocitoma.","C":"A Neoplasia Endócrina Múltipla tipo 2 (NEM 2) está relacionada à mutação do ret e câncer da\ntireóide, adenoma hipofisário e tumor de pâncreas.","D":"O câncer gástrico difuso hereditário está relacionado à mutação do CDH1 (16q22) e câncer\ngástrico."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-291479","number":"291479","sourceNumber":"291479","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um homem com 58 anos de idade foi atendido em ambulatório de hospital secundário.\nRelatava sangramento e muco nas fezes, referia também alteração do hábito intestinal, com o\naumento do número de evacuações há 5 meses. O exame físico geral não apresentava\nparticularidades e o toque retal evidenciou tumoração na parede posterior do reto,\naproximadamente 7 cm acima da borda anal. Com base nos dados apresentados, a alternativa\ncorreta sobre o exame necessário para definir a conduta a ser seguida é:","options":{"A":"Ultrassonografia endorretal.","B":"Ressonância nuclear magnética endorretal.","C":"Enema baritado com duplo contraste.","D":"Colonoscopia com biópsia."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-273336","number":"273336","sourceNumber":"273336","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma paciente de 45 anos com nódulo tireoidiano de 1,5 cm apresenta um resultado da\nPAF de ?tumor folicular?. Assinale a\nresposta correta:","options":{"A":"Trata-se de um tumor benigno e o tratamento deve ser conservador.","B":"Deverá ser operada já que se trata de um tumor maligno.","C":"Trata-se de um tumor maligno mas o tratamento não é cirúrgico.","D":"Deverá ser operada e o diagnóstico de benigno ou maligno será definido pela peça cirúrgica."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-291488","number":"291488","sourceNumber":"291488","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente 65 anos, masculino, apresentando alteração do hábito intestinal. Como\nhistória familiar, apresenta pai falecido de\ncâncer de próstata aos 70 anos, mãe falecida de câncer\nde colo de útero aos 80 anos, avô paterno e primo por parte de mãe falecidos por câncer de cólon\ncom 60 e 50 anos respectivamente. Realizou colonoscopia que evidenciou lesão estenosante na\njunção reto-sigmoidiana, 3 pólipos em reto e 5 pólipos em sigmoide. O resultado histopatológico da\nlesão estenosante foi adenocarcinoma de cólon moderadamente diferenciado. Quanto aos pólipos,\ntodos eram de natureza adenomatosa, sendo 5 tubulares e 2 túbulos-vilosos (ambos no reto). Em\nqual das situações abaixo, levando em conta a história familiar e o diagnóstico, esse paciente\nmelhor se enquadra?","options":{"A":"Câncer colorretal hereditário não polipoide (Síndrome de Lynch).","B":"Síndrome de Polipose Recessiva.","C":"Polipose adenomatosa familiar.","D":"Câncer colorretal esporádico."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-263431","number":"263431","sourceNumber":"263431","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma mulher com 55 anos de idade, previamente hígida, é admitida em hospital após\nepisódio de síncope. Apresenta bradicardia sinusal, discreta hipertensão arterial sistêmica e edema\npalpebral bilateral. Nota-se um aumento difuso da tireoide que a paciente não havia percebido até\nentão. Não há rouquidão, disfagia nem alteração recente de peso. Ademais, não apresenta\nhistórico familiar de câncer. Um estudo ultrassonográfico da tireoide mostra 3 nódulos de bordas\nregulares, parcialmente císticos, com componente sólido isoecoico, sem calcificações, de 0,4 cm,\n0,6 cm e 0,8 cm. Não há linfadenopatia cervical. O exame revelou TSH = 17,2 mUI/mL (valor de\nreferência = 0,3 a 5,0 mUI/mL). Nesse caso, a abordagem adequada para com a paciente é","options":{"A":"solicitar T3 total e T4 livre e cintilografia da tireoide antes de definir o tratamento.","B":"prescrever levotiroxina e realizar acompanhamento clínico e ultrassonográfico dos nódulos.","C":"prescrever levotiroxina e dosar anti-tireoide peroxidase para definir a abordagem dos nódulos.","D":"solicitar T4 livre e punção aspirativa com agulha fina do maior nódulo antes de definir o\ntratamento."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-263432","number":"263432","sourceNumber":"263432","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente com 70 anos de idade foi atendido no pronto-socorro de hospital de nível\nsecundário, relatando dor abdominal com irradiação para região dorsal, além de emagrecimento, há\n4 meses. Há 2 meses, começou a apresentar prurido cutâneo progressivo e urina escura. Há 15\ndias, notou que os ''olhos ficaram amarelos''. Na ocasião do exame físico, encontrava-se\nemagrecido, ictérico (++/4+), com escoriações dérmicas provocadas pelo ato de coçar. A borda do\nfígado era palpada a 1,5 cm abaixo de rebordo costal direito, com palpação não dolorosa. Com\nbase no caso clínico, os resultados dos exames laboratoriais que confirmam a hipótese diagnóstica\nsão","options":{"A":"aumento da bilirrubina indireta e aumento da amilase.","B":"aumento da bilirrubina direta e aumento da fosfatose alcalina.","C":"aumento da bilirrubina indireta e aumento da alanina aminotransferase.","D":"aumento da bilirrubina direta e diminuição do tempo de protrombina em segundos."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-263435","number":"263435","sourceNumber":"263435","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma paciente com 35 anos de idade procura atendimento hospitalar devido a episódio\núnico de sangramento anal vermelho vivo, indolor, em pequena quantidade durante evacuação.\n\nNega qualquer história prévia de traumatismo local. Em seu exame físico, constatou-se que a\npaciente está em bom estado geral,\nnormocorada, PA = 120 x 60 mmHg, FC = 76 bpm e com pulso\nradial amplo, regular. Abdome plano e depressível, indolor à palpação, sem massas palpáveis e\nsem sinais de irritação peritoneal. A anuscopia não demonstrou doença hemorroidária externa e/ou\nfissuras anais e/ou fístulas perianais. O toque retal não identificou lesões palpáveis, até cerca\nde ±\n6 cm da margem anal, porém, evidenciou discreta quantidade de sangue em dedo-de-luva. O\nmédico assistente solicitou hemograma, cujo resultado foi normal. A paciente foi liberada com\nencaminhamento ambulatorial e com solicitação de exame de colonoscopia. O resultado da\ncolonoscopia mostrou alguns pólipos colônicos, não pediculados, e lesão de borda elevada com\nulceração central, séssil, ± 1,5 cm de diâmetro, em cólon sigmoide, distando ± 35 cm da margem\nanal - a qual foi biopsiada. Nesse caso clínico, a hipótese diagnóstica mais provável para essa\npaciente é de","options":{"A":"polipose adenomatosa familiar.","B":"síndrome de Peutz-Jeghers.","C":"neoplasia colônica.","D":"doença de Crohn."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-244460","number":"244460","sourceNumber":"244460","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente de 17 anos de idade busca atendimento por causa da presença de massa\ncervical em linha média. Ao exame, apresenta aspecto cístico. A respeito desse caso e com base\nnos conhecimentos correlatos, assinale a alternativa correta.","options":{"A":"O tratamento inicial é o procedimento conhecido como cirurgia de Sistrunk, independentemente\nda presença de infecção.","B":"Paralisia temporária unilateral da prega vocal é uma complicação frequente do tratamento desse\ntipo de patologia.","C":"Caso confirmada a hipótese de cisto tireoglosso no transoperatório, a retirada do hioide não\ninflui\nno risco de recidiva no pós-operatório.","D":"Bócio mergulhante deve ser considerado, nesse caso, a idade do paciente.","E":"Deve-se avaliar a tireoide, seja ao exame físico, seja com métodos de imagem para evitar\ncomplicações no pós-operatório."},"answer":"E","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-244463","number":"244463","sourceNumber":"244463","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Acerca de pólipos colônicos, assinale a alternativa correta.","options":{"A":"Pólipos hamartomatosos são característicos da síndrome de Gardner e podem ser causa de\nsangramento.","B":"Polipose adenomatose familiar é uma doença autossômica dominante, e um possível tratamento\nindicado é colectomia e vigilância endoscópica do restante do trato gastrointestinal.","C":"Na polipose juvenil familiar, tipicamente, os pólipos adenomatoides estão presentes no cólon e\nno reto e podem ocasionar sangramento.","D":"Os pólipos inflamatórios são raros e têm alto potencial de malignidade.","E":"Os cânceres de cólon esquerdo são habitualmente lesões exofíticas que estão associadas com\nperda de sangue oculto, e resultam em anemia por deficit de ferro."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-230587","number":"230587","sourceNumber":"230587","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Sobre o câncer colorretal e seu estadiamento, assinale a CORRETA:","options":{"A":"apenas Rx de tórax é necessário, uma vez que o tratamento é sempre cirúrgico.","B":"é necessário apenas ultrassonografia de abdome total.","C":"realização de CT de crânio para todos se faz necessário.","D":"realização de tomografia de abdome, pelve e tórax são necessárias para evidenciar a presença\nde lesões secundárias."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-206097","number":"206097","sourceNumber":"206097","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Há benefício clínico com a radioiodoterapia RIT, o objetivo do tratamento é promover a\nablação de tecido remanescente do câncer da tireoide. Podemos assim apenas ACEITAR que:","options":{"A":"Esta ablação pode ser definida como a ausência de captação de radioiodo em leito tireoidiano\nem estudo cintilográfico, ou a ausência de\nníveis séricos detectáveis de tireoglobulina estimulada.","B":"Esta ablação pode ser definida como a ausência de captação de radioiodo em leito tireoidiano\nem estudo cintilográfico, mas não da ausência de\nníveis séricos detectáveis de tireoglobulina\nestimulada.","C":"Esta ablação não pode ser definida como a ausência de captação de radioiodo em leito\ntireoidiano em estudo cintilográfico, somente com a ausência de níveis séricos detectáveis de\ntireoglobulina estimulada.","D":"Esta ablação pode ser definida como a ausência de captação de radioiodo em leito tireoidiano\nem estudo cintilográfico, ou a ausência de níveis\nséricos detectáveis de tireoglobulina não\nestimulada."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-203047","number":"203047","sourceNumber":"203047","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente de 30 anos de idade realizou tomografia computadorizada de abdome em\nrazão de dor abdominal com achado de lesão sólido-cística de 8 cm x 10 cm em região de\n\ncorpo-cauda de pâncreas. Quanto a esse caso clínico, é correto afirmar que o diagnóstico mais\nprovável é:","options":{"A":"tumor de Frantz.","B":"Adenocarcinoma de pâncreas.","C":"Tumor neuroendócrino.","D":"Pseudocisto pancreático.","E":"Nesidioblastose."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-203066","number":"203066","sourceNumber":"203066","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente de 60 anos de idade, procedente de Santa Maria da Vitória (BA), procura\no ambulatório com histórico de disfagia\nprogressiva há 20 anos, com piora importante há um mês,\nevoluindo com disfagia total. Refere perda de 6 kg em um mês. O paciente é tabagista e etilista há\n45 anos. Considerando esse caso clínico, no momento o exame mais indicado para o paciente e o\n(a):","options":{"A":"Esofagograma.","B":"Sorologia para doença de Chagas.","C":"Endoscopia digestiva alta.","D":"Esofagomanometria.","E":"Tomografia computadorizada de tórax e abdome."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-206143","number":"206143","sourceNumber":"206143","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"A colonoscopia é utilizada para o diagnóstico da doença de câncer de cólon por permitir\no exame de todo o intestino grosso e biópsia de\npólipos que possam estar localizados fora da área\nde ressecção da lesão. Sendo INCORRETO o seguinte:","options":{"A":"Nos casos confirmados da doença de câncer de cólon, a infiltração e extensão do tumor de reto\ndevem ser avaliadas quando possível pela ultrassonografia endorretal, que tem acurácia\ncomparável à tomografia computadorizada pélvica, ou pela\n\nressonância magnética.","B":"Pelo risco de tumores sincrônicos do cólon, a colonoscopia deve ser realizada sempre que\npossível antes do tratamento destes\n\ndoentes.","C":"O exame de tomografia por emissão de pósitrons (PET-CT) é inútil na investigação de doença\nmetastática à distância em doentes\n\nde alto risco com tumor potencialmente ressecável.","D":"A indicação de PET-CT deve ser feita para detecção de metástase de câncer colorretal,\nexclusivamente hepática e potencialmente ressecável."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-202970","number":"202970","sourceNumber":"202970","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma paciente de 38 anos de idade realizou ultrassom de tireoide, no qual foi\nvisualizado um nódulo sólido de 4 cm em lobo\ndireito. Foi feita uma punção aspirativa por agulha\nfina, que mostrou uma lesão classificada como Bethesda VI. A respeito desse caso clínico, qual é a\nconduta indicada?","options":{"A":"Tireoidectomia total.","B":"Lobectomia direita e istmectomia.","C":"Lobotomia direita e istmectomia com biópsia de congelação.","D":"Acompanhamento com ultrassom a cada três meses.","E":"Terapia ablativa com iodo radioativo."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-203056","number":"203056","sourceNumber":"203056","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Considere um paciente de 68 anos de idade com histórico de dor epigástrica há três\nmeses. Ele realizou endoscopia digestiva\nalta com achado de lesão de 2 cm em antrogástrico,\nBormann II, cuja biópsia mostrou adenocarcinoma do tipo intestinal, com células em anel de sinete.\nRealizou estadiamento clínico que sugeriu T2, sem evidências de metástases linfonodais ou a\ndistância. Com relação a esse caso clínico, a conduta indicada é:","options":{"A":"Quimioterapia neoadjuvante.","B":"Ressecção endoscópica.","C":"Gastrectomia total com linfadenectomia à DII.","D":"Gastrectomia subtotal com linfadenectomia à DII.","E":"Quimioterapia e radioterapia exclusivas."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-206161","number":"206161","sourceNumber":"206161","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"É fundamental um exame físico cuidadoso com palpação da região cervical,\ncaracterização do nódulo quanto à\nconsistência, fixação a outras estruturas cervicais e avaliação da\npresença de disfonia secundária à paralisia de corda vocal. O objetivo da avaliação do nódulo\ntireoidiano é estabelecer o risco de câncer por meio de métodos que sejam acurados, precisos,\nalém de seguros e custo-efetivos. Não sendo aceito, entretanto, que:","options":{"A":"O paciente com diagnóstico de doença nodular tireoidiana deve ter a dosagem de hormônio\ntireotrófico (TSH), com o objetivo de avaliar a função tireoidiana.","B":"Na presença de níveis inferiores de hormônio tireotrófico (TSH) aos valores considerados\nnormais, recomenda-se a realização de\n\ncaptação e cintilografia com radioisótopo para investigar a possibilidade de hipofunção\ntireoidiana.","C":"A incidência de neoplasia maligna neste tipo de doença nodular tireoidiana é rara, não havendo\nindicação de realização de punção guiada pela ultrassonografia.","D":"Os níveis de TSH têm sido relacionados ao risco de câncer da tireóide em pacientes com\ndoença nodular."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-206163","number":"206163","sourceNumber":"206163","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O preparo para a terapia com radioiodo tem como objetivo aumentar a eficácia do\ntratamento do câncer da tireóide. A\nprincipal medida relacionada à eficácia é a elevação dos níveis\nde TSH. Sendo adequado considerarmos que:","options":{"A":"A redução deste hormônio estimulante pode ser obtida pela interrupção do uso de levotiroxina,\ninduzindo hipotiroidismo endógeno (causando\nelevação fisiológica do TSH), ou pela administração\nexógena de TSH recombinante humano (TSHrh).","B":"A elevação deste hormônio estimulante não pode ser obtida pela interrupção do uso de\nlevotiroxina, hipotiroidismo endógeno (causando elevação fisiológica do TSH), ou pela\nadministração exógena de TSH recombinante humano (TSHrh).","C":"A elevação deste hormônio estimulante pode ser obtida pela interrupção do uso de levotiroxina,\ninduzindo hipotiroidismo endógeno (causando elevação fisiológica do TSH), ou pela administração\nexógena de TSH recombinante humano (TSHrh).","D":"A elevação deste hormônio estimulante pode ser obtida pela interrupção do uso de levotiroxina,\ninduzindo hipertiroidismo\n\nendógeno (causando elevação fisiológica do TSH), ou pela administração exógena de TSH\nrecombinante humano (TSHrh)."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-206167","number":"206167","sourceNumber":"206167","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O Carcinoma Diferenciado da Tireóide (CDT) é a neoplasia maligna endócrina de maior\nprevalência no mundo, sendo INCORRETO o seguinte:","options":{"A":"Além do carcinoma papilífero, não podemos incluir dentro do grupo de CDT o carcinoma de\ncélulas de Hürthle.","B":"Entende-se como CDT, o tumor maligno da tireóide de origem epitelial.","C":"O carcinoma papilífero é o principal representante desta categoria.","D":"Além do carcinoma papilífero, incluem-se dentro do grupo de CDT o carcinoma folicular e o\ncarcinoma de células de Hürthle."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-206176","number":"206176","sourceNumber":"206176","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Os linfonodos cervicais aumentados são achados frequentes, muitas vezes decorrentes\nde infecções crônicas do trato respiratório\nsuperior. Parte destes nódulos é de natureza benigna,\nporém malignidade pode ser encontrada. Sendo assim, podemos aceitar que:","options":{"A":"Nos tumores diferenciados da tireóide, em especial o carcinoma papilífero, cuja disseminação\nnão é por via linfática, a presença de\nlinfonodos aumentados pode indicar acometimento\nmetastático.","B":"Nos tumores diferenciados da tireóide, em especial o carcinoma papilífero, cuja disseminação é\npor via linfática, a presença de linfonodos aumentados pode indicar acometimento por contiguidade\napenas.","C":"Nos tumores diferenciados da tireóide, em especial o carcinoma papilífero, cuja disseminação é\npor via linfática, a presença de linfonodos aumentados pode indicar acometimento metastático.","D":"Nos tumores diferenciados da tireóide, em especial o carcinoma papilífero, cuja disseminação é\npor via linfática, a presença de linfonodos diminuídos pode indicar acometimento metastático."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-206178","number":"206178","sourceNumber":"206178","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Apesar de a etiologia ser desconhecida, há fatores hereditários e não hereditários\nclaramente associados ao aparecimento e\ndesenvolvimento do câncer gástrico. Os fatores de risco\nconhecidos devem-se a diversos aspectos. Quanto a isso, indique o item INCORRETO:","options":{"A":"Origem infecciosa, como infecção gástrica pelo Helicobacter pylori.","B":"Características demográficas, como idade avançada e sexo masculino.","C":"Hábitos de vida, como dieta rica em produtos de origem vegetal, dieta pobre em sal, consumo de\nalimentos conservados de determinadas formas, como defumação ou conserva, e exposição a\ndrogas, como tabagismo.","D":"Associação com doenças, como gastrite atrófica crônica, metaplasia intestinal da mucosa\ngástrica, anemia perniciosa, pólipo adenomatoso do estômago, gastrite hipertrófica gigante."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-206165","number":"206165","sourceNumber":"206165","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Quando da suspeita do diagnóstico adenocarcinoma do estômago, o paciente deve ser\nsubmetido à endoscopia digestiva alta, para biopsiar lesões. O tratamento deve ser realizado\npreferencialmente em centros especializados, com grande número de atendimentos, cujos\nresultados sejam validados e apresentados periodicamente. NÃO sendo adequado que:","options":{"A":"Tomografia computadorizada de abdômen total e tórax com contraste oral e venoso deve ser\nrealizada para definir o estadiamento e planejar o tratamento, já que comumente a doença se\napresenta em estágios avançados, e o tratamento é não definido por sua extensão na\napresentação.","B":"Ressonância magnética deve ser solicitada caso seu resultado possa alterar a conduta\nterapêutica inicial.","C":"Outros exames de imagem, como a ultrassonografia endoscópica (também conhecida por\necoendoscopia), podem auxiliar na avaliação da extensão locorregional da doença.","D":"Exames laboratoriais são realizados para avaliar as condições clínicas do paciente."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-206172","number":"206172","sourceNumber":"206172","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"A colonoscopia é o método preferencial de diagnóstico por permitir o exame de todo o\nintestino grosso e a remoção ou biópsia de pólipos que possam estar localizados fora da área de\nressecção da lesão principal, oferecendo vantagem sobre a colonografia por tomografia. O\ndiagnóstico de câncer de cólon é estabelecido pelo exame histopatológico de espécime tumoral\nobtido através da colonoscopia ou do exame de peça cirúrgica. Estando INADEQUADO o seguinte:","options":{"A":"O diagnóstico da doença por exame radiológico contrastado do cólon (enema opaco) deve ser\npreferido mesmo com acesso à colonoscopia ou quando existir contraindicação médica para esse\nexame.","B":"A investigação de possíveis metástases intra-abdominais e pélvicas deve ser feita\nalternativamente por meio de exame\nultrassonográfico, tomografia computadorizada ou ressonância\nmagnética, a critério médico.","C":"A investigação de metástases pulmonares deve ser efetuada por meio de radiografia simples de\ntórax ou tomografia computadorizada, também a critério médico.","D":"Na suspeita de câncer retal pela história clínica é mandatória a realização de um exame\nproctológico (toqueretal)."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-206166","number":"206166","sourceNumber":"206166","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"A quimioterapia paliativa está indicada para doentes com câncer colorretal recidivado\ninoperável ou com doença no estágio IV ao diagnóstico, a critério médico. Está INADEQUADO o\nque se afirma na alternativa:","options":{"A":"Em doentes com metástases hepáticas ressecáveis (número limitado de lesões, localização intra\nhepática, ausência de envolvimento vascular, ausência ou mínima doença metastática\n\nextra-hepática, reserva funcional hepática adequada), a ressecção completa da doença hepática\npode resultar em taxas de sobrevida em 5 anos\nde 25% a 40%.","B":"Empregam-se esquemas terapêuticos baseados em fluoropirimidina, associada ou não a\noxaliplatina, irinotecano, mitomicina C, bevacizumabe, cetuximabe ou panitumumabe,\nobservando-se independente das características clínicas do doente.","C":"Doentes com metástases hepáticas irressecáveis e ausência ou mínima doença metastática\nextra-hepática podem se beneficiar de quimioterapia paliativa sistêmica baseada em\nfluoropirimidina, contendo ou não oxaliplatina ou irinotecano, com objetivo de reduzir o volume\ntumoral e permitir a ressecção cirúrgica.","D":"O uso de esquema terapêutico contendo cetuximabe ou bevacizumabe promoveu taxa de\nressecabilidade maior que controles históricos (ou seja, não randomizados e comparativos), porém\no significado clínico em termos de benefícios clínicos duradouros ou ganho de sobrevida são\ndesconhecidos."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-206082","number":"206082","sourceNumber":"206082","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Levantamentos demográficos recentes mostraram que a incidência de neoplasias\nmalignas do intestino delgado tem aumentado ao longo das últimas três décadas. Sobre isso,\nassinale a alternativa INCORRETA:","options":{"A":"Os tumores malignos de intestino delgado mais frequentes são tumores carcinoides,\nadenocarcinoma, linfoma e GIST.","B":"Em crianças menores de 10 anos o tumor maligno do intestino delgado mais comum é o\nLinfoma.","C":"Os Tumores Estromais Gastrintestinais têm o melhor prognóstico de todos os tumores do\nintestino delgado, na forma localizada ou metastática.","D":"Macroscopicamente os linfomas de intestino delgado são volumosos e podem se projetar além\nda mucosa."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-206158","number":"206158","sourceNumber":"206158","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"A Hiperplasia nodular regenerativa HNR é uma condição de pequenos nódulos\nregenerativos no parênquima hepático. Sendo INCORRETO que","options":{"A":"a HNR tem sido reconhecida em pacientes infectados pelo HIV com doença hepática\ncriptogênica.","B":"apesar de a etiologia ainda ser pouco clara, o uso prolongado de didanosina-ddI e trombofilia\ntêm sido associados à doença.","C":"a Hiperplasia nodular regenerativa HNR é uma condição caracterizada por múltiplos e grandes\nnódulos degenerativos no parênquima hepático.","D":"a HNR deve ser considerada em portadores do HIV com hipertensão portal de causa inaparente,\nespecialmente naqueles que fizeram uso de didanosina-ddI."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-177261","number":"177261","sourceNumber":"177261","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente do sexo masculino, de 60 anos de idade, previamente hígido, procura um\npronto-socorro com dor abdominal, náuseas,\nvômitos e inapetência. Nega febre. Refere distensão\nabdominal e ausência de evacuações há 3 dias. Relata que vem apresentando períodos de diarreia\ne de constipação intercalados. Na emergência, realizou tomografia de abdômen, que evidenciou\ntumor em cólon sigmoide e distensão de cólon e das alças intestinais, além de lesão nodular em\nlobo direito do fígado. Em relação ao caso clínico apresentado e considerando-se os\nconhecimentos médicos relativos aos tumores colorretais, é correto afirmar que","options":{"A":"a ocorrência de sangramento é mais comum no cólon esquerdo.","B":"tais tumores são mais comuns no lado esquerdo, principalmente no sigmoide e no reto.","C":"a disseminação da doença ocorre principalmente pela via linfática.","D":"a obstrução intestinal é mais comum nos tumores de cólon direito.","E":"a maioria dos tumores se origina dos pólipos vilosos."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-175128","number":"175128","sourceNumber":"175128","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Segundo a classificação de Lauren para o adenocarcinoma gástrico, aponte a\nalternativa que NÃO corresponde ao tipo intestinal:","options":{"A":"Atrofia gástrica.","B":"Relacionada a fatores familiares.","C":"Disseminação hematogênica.","D":"Formação de glândulas."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-154473","number":"154473","sourceNumber":"154473","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 50 anos de idade com queixa de astenia, apresentando como única\nalteração laboratorial anemia hipocrômica\nmicrocítica (Hb 8,0 g/dl). Durante propedêutica\ninvestigativa, foi submetido à tomografia computadorizada de abdome, sendo evidenciada massa\nem topografia de cólon ascendente, medindo 5 cm em seu maior diâmetro, sem metástases\ndetectadas. Qual deve ser o exame realizado neste momento para orientação da conduta e sua\nrespectiva justificativa?","options":{"A":"PET-Scan (Tomografia com Emissão de Pósitrons), avaliar se a lesão encontrada é ressecável\nou irressecável.","B":"Ecografia com Doppler das artérias mesentéricas, avaliando irrigação tumoral e grau de invasão.","C":"Colonoscopia virtual, avaliando as dimensões precisas do tumor, incluindo profundidade de\ninvasão da parede intestinal.","D":"Ressonância magnética de abdome, avaliar em detalhes a irrigação tumoral, bem como real\nextensão do tumor.","E":"Colonoscopia, para confirmar o achado da tomografia e descartar presença de lesões\nsincrônicas."},"answer":"E","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-159624","number":"159624","sourceNumber":"159624","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente do sexo feminino, de sessenta e três anos de idade, apresentava\nempachamento e desconforto abdominal\nsemelhante à cólica de caratér frequente e que cedia sem\nnecessidade de analgesia. Durante a investigação diagnóstica, ela foi submetida a exame\nlaboratorial e ultrassonografia abdominal total. Os resultados dos exames laboratoriais não\napresentaram anormalidades. Contudo, a ultrassonografia mostrou a presença de cisto de 4 cm de\ndiâmetro na cabeça do pâncreas. Procedeu-se, então, à realização de tomografia computadorizada\nde abdome com contraste, pela qual se identificou cisto pancreático de 4 cm de diâmetro de\nsuperfície regular, com múltiplos pequenos cistos no seu interior, espesso estroma fibroso, sem\ncomunicação com ducto pancreático principal e com calcificações esparsas próximas da periferia\ndo cisto. Considerando esse caso clínico, julgue o item que se segue. Os resultados obtidos na\ntomografia computadorizada da paciente indicam baixa possibilidade de ela ser portadora de\nneoplasia intraductal papilar mucinosa.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-159620","number":"159620","sourceNumber":"159620","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente do sexo feminino, de sessenta e três anos de idade, apresentava\nempachamento e desconforto abdominal\nsemelhante à cólica de caratér frequente e que cedia sem\nnecessidade de analgesia. Durante a investigação diagnóstica, ela foi submetida a exame\nlaboratorial e ultrassonografia abdominal total. Os resultados dos exames laboratoriais não\napresentaram anormalidades. Contudo, a ultrassonografia mostrou a presença de cisto de 4 cm de\ndiâmetro na cabeça do pâncreas. Procedeu-se, então, à realização de tomografia computadorizada\nde abdome com contraste, pela qual se identificou cisto pancreático de 4 cm de diâmetro de\nsuperfície regular, com múltiplos pequenos cistos no seu interior, espesso estroma fibroso, sem\ncomunicação com ducto pancreático principal e com calcificações esparsas próximas da periferia\ndo cisto. Considerando esse caso clínico, julgue o item que se segue. O exame adequado para\ndeterminar a malignidade do cisto pancreático é a ultrassonografia endoscópica, sendo dispensável\na análise citológica e a medida da concentração de marcadores tumorais.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-154511","number":"154511","sourceNumber":"154511","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Em paciente do sexo masculino, 50 anos de idade, portador de cirrose hepática de\netiologia alcoólica, foi identificado em tomografia computadorizada de abdome em nódulo hepático\nde 3 cm de diâmetro, hipervascularizado na fase arterial e radiolucente na fase venosa do exame.\nRealizada dosagem de alfafetoproteína sérica, com resultado de 700 ng/mL. A principal hipótese\ndiagnóstica para o nódulo hepático é:","options":{"A":"Metástase de câncer colorretal.","B":"Hepatoblastoma.","C":"Hepatocarcinoma.","D":"Adenoma hepático.","E":"Colangiocarcinoma."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-168477","number":"168477","sourceNumber":"168477","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma mulher com 50 anos de idade procura atendimento médico na Unidade Básica de\nSaúde, com queixa de astenia progressiva há 3 meses. Ela nega quaisquer outros sintomas e\nafirma não fazer uso de qualquer medicação. Está na menopausa há 2 anos, sem apresentar\nsangramento transvaginal. Não há relato de comorbidades ou de histórico familiar de diabetes,\nhipertensão ou neoplasias. No exame físico da paciente, o único achado é palidez, com mucosas\nhipocoradas (++/4+). O hemograma solicitado mostrou: hemoglobina = 9 g/dL (valor de referência:\n12 a 14 g/dL), hematócrito = 27% (valor de referência: 36 a 42%), VCM = 65 fL (valor de referência:\n80 a 100 fL), HCM = 20 pg (valor de referência: 27 a 32 pg), RDW = 19% (valor de referência: 11,5\na 15%); leucograma e plaquetas normais. Com base nos achados, a conduta inicial para\ncomplementação da investigação diagnóstica dessa paciente é solicitar","options":{"A":"mielograma.","B":"dosagem de ácido fólico.","C":"dosagem de vitamina B12.","D":"pesquisa de sangue oculto nas fezes."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-168436","number":"168436","sourceNumber":"168436","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma mulher com 49 anos de idade é encaminhada para o ambulatório de oncologia,\nem razão de diagnóstico recente de\nadenocarcinoma de pulmão, com CA de pulmão não pequenas\ncélulas em estágio IIIA (T3N1). A paciente nega qualquer história de tabagismo, cabendo ao\nmédico fornecer-lhe, na consulta atual, informações sobre a sua doença e sobre o tratamento ao\nqual será submetida. Assinale a alternativa que apresenta informações adequadas sobre a doença\nou sobre o tratamento a serem dadas pelo médico:","options":{"A":"A mudança recente da epidemiologia do câncer de pulmão revela que cerca de 50% dos casos\nocorrem em pacientes que nunca fumaram.","B":"A inclusão de cisplatina no seu tratamento deverá produzir-lhe uma expectativa de sobrevida em\n5 anos superior a 80%.","C":"O tipo histológico que seria mais esperado no seu caso seria o carcinoma espinocelular, em\nrazão do seu sexo.","D":"O tratamento indicado para a paciente deve consistir em cirurgia e quimioterapia adjuvante."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-159556","number":"159556","sourceNumber":"159556","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente de cinquenta e quatro anos de idade procurou atendimento médico\nqueixando-se de mudanças no hábito intestinal\ne de presença de sangue nas fezes. O paciente\napresentou história de polipose adenomatosa familiar, diagnosticada havia seis anos. O paciente\nrelatou ainda que, com relação ao referido diagnóstico, não havia feito acompanhamento médico. O\nexame físico não mostrou alterações, e o toque retal deixou mancha de sangue na luva do médico.\nPor fim, o profissional da saúde solicitou dosagem do nível sérico de antígeno carcinoembriônico\n(CEA). Com referência a esse caso clínico, julgue o item que se segue. Nesse caso, se forem\nconstatados níveis normais de CEA, deve-se descartar o diagnóstico de câncer colorretal, dada a\nelevada sensibilidade diagnóstica desse marcador.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-159557","number":"159557","sourceNumber":"159557","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente de cinquenta e quatro anos de idade procurou atendimento médico\nqueixando-se de mudanças no hábito intestinal\ne de presença de sangue nas fezes. O paciente\napresentou história de polipose adenomatosa familiar, diagnosticada havia seis anos. O paciente\nrelatou ainda que, com relação ao referido diagnóstico, não havia feito acompanhamento médico. O\nexame físico não mostrou alterações, e o toque retal deixou mancha de sangue na luva do médico.\nPor fim, o profissional da saúde solicitou dosagem do nível sérico de antígeno carcinoembriônico\n(CEA). Com referência a esse caso clínico, julgue o item que se segue. No caso em consideração,\na principal hipótese diagnóstica é câncer colorretal.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-158033","number":"158033","sourceNumber":"158033","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 60 anos de idade, sexo feminino, tabagista ativa, procedente do Rio grande\ndo Sul, em investigação de dor epigástrica,\nrealizou endoscopia digestiva alta, que mostrou lesão\nvegetante localizada no fundo gástrico. A biópsia dela confirmou tratar-se de um adenocarcinoma.\nCom base nesse caso clínico e nos conhecimentos médicos a ele relacionados, assinale a\nalternativa CORRETA.","options":{"A":"O adenocarcinoma é o segundo tipo histológico mais comum dos tumores gástricos.","B":"O principal tratamento para o adenocarcinoma gástrico é a quimioterapia associada a\nradiografia.","C":"A ultrassonografia endoscópica parece ser o método mais adequado para avaliar a profundidade\nda lesão.","D":"A laparoscopia ja foi um procedimento de grande importância na avaliação do estádio do câncer\ngástrico, principalmente na avaliação dos cânceres avançados, mas perdeu espaço para a\nressonância magnética de abdome.","E":"A cirurgia-padrão com intuito curativo é a gastrectomia com linfadenectomia D1."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-129023","number":"129023","sourceNumber":"129023","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Assinale a alternativa que apresenta a localização mais comum para os linfomas no\ntrato gastrointestinal.","options":{"A":"Esôfago.","B":"Estômago.","C":"Duodeno.","D":"Íleo.","E":"Reto."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-129038","number":"129038","sourceNumber":"129038","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Com relação ao modelo de carcinogênese colorretal, assinale a alternativa que\napresenta o evento mais tardio, que parece\nestar associado com a conversão maligna do adenoma\nem carcinoma.","options":{"A":"APC perda 5q.","B":"Perda do DCC 18q.","C":"Estabilidade de microssatélites.","D":"Perda do 17p p53.","E":"Ativação do K-ras 12p."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-133984","number":"133984","sourceNumber":"133984","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Em relação aos tumores do intestino delgado, assinale a alternativa incorreta.","options":{"A":"Têm baixa incidência.","B":"Correspondem a 2,8% de todos os casos novos de câncer digestivo.","C":"Têm sintomas inespecíficos como dor abdominal, náuseas, vômitos ou sangramento oculto.","D":"O gastrointestinal stromal tumor (GIST) é mais frequente no íleo terminal.","E":"Mais de 50% têm doença linfonodal ou metástases na sua apresentação inicial."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-133944","number":"133944","sourceNumber":"133944","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Assinale a alternativa que não apresenta fator de risco reconhecidamente para câncer\nde esôfago.","options":{"A":"Etilismo.","B":"Tabagismo.","C":"Esôfago de Barret.","D":"Esclerodermia.","E":"Diabetes mellitus."},"answer":"E","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-133954","number":"133954","sourceNumber":"133954","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Considere hipoteticamente que determinado paciente de 47 anos de idade, hígido, com\nbom performance status, procurou o serviço de\ncirurgia com disfagia e emagrecimento. Na\nendoscopia digestiva alta, observou-se lesão polipoide de 3 cm limitada a 40% da luz esofágica a\n36 cm da arcada dentária superior. Os exames de imagem indicaram lesão limitada ao esôfago\nsem disseminação a distância, assim como PET-Scan, e a ecoendoscopia classificou como\nT2N0M0. Nesse caso, a conduta mais apropriada para esse paciente é a","options":{"A":"Quimeoterapia exclusiva com cisplatina.","B":"Esofagectomia por via laparoscópica com gastric-pull-up.","C":"Radioterapia e quimioterapia exclusivas","D":"Ressecção endoscópica por ecoendoscopia.","E":"Radioterapia exclusiva com bomba de elétrons."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-133956","number":"133956","sourceNumber":"133956","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Com relação ao câncer gástrico, assinale a alternativa CORRETA.","options":{"A":"O subtipo histológico mais comum é o carcinoma epidermoide.","B":"O GIST é mais comum em indivíduos idosos com mais de 70 anos de idade.","C":"O tratamento para o carcinoide gástrico tipo I é sempre a gastrectomia radical ampliada com\nlinfadenectomia D2.","D":"O adenocarcinoma inicial restrito a mucosa pela ecoendoscopia pode ser tratado com ressecção\nendoscópica.","E":"O tratamento do GIST é amiúde o uso terapia-alvo como imatinibe ou sunitinibe."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-133963","number":"133963","sourceNumber":"133963","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 45 anos de idade, etilista e tabagista, Child A, realizou ultrassonografia\nabdominal em que se observou lesão focal\nhepática em segmentos II-III do lobo esquerdo de 6 cm.\nFoi realizada biopsia percutânea por meio da qual se verificou hepatocarcinoma de baixo grau, sem\ninvasão vascular. No estadiamento, não se constatou doença à distância e, na endoscopia, não\nforam observadas varizes esofágicas. Considerando a situação hipotética apresentada, assinale a\nalternativa que indica o tratamento curativo mais adequado nesse caso.","options":{"A":"Terapia exclusiva com Sorafenib.","B":"Ablação por radiofrequência via aberta.","C":"Alcoolização percutânea.","D":"Transplante hepático.","E":"Segmentectomia lateral esquerda ou lobectomia esquerda, de preferência por laparoscopia."},"answer":"E","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-133969","number":"133969","sourceNumber":"133969","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"A respeito do adenocarcinoma gástrico, assinale a alternativa CORRETA.","options":{"A":"É o câncer mais comum no homem no Brasil.","B":"Pode ser familial em até 10% dos casos.","C":"Pode ser identificado, pela classificação de Lauren, em tipo intestinal mais comumente\nobservado no cárdia e de melhor prognóstico\nou tipo difuso, mais comum no antro e com excelente\nprognóstico.","D":"A classificação de Borrmann é preditiva de prognóstico, sendo os tumores vegetantes e\npolipoides, isto é, Borrmann III, os de pior prognóstico.","E":"A ressecção endoscópica por ecoendoscopia é o padrão ouro para as lesões ulceradas menores\nque 3 cm."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-111354","number":"111354","sourceNumber":"111354","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O achado clínico mais comumente observado nos pacientes portadores de carcinoma\nde cólon direito é:","options":{"A":"A alteração do hábito intestinal.","B":"O tenesmo.","C":"A hematoquezia.","D":"A obstrução.","E":"A anemia."},"answer":"E","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-111323","number":"111323","sourceNumber":"111323","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente do sexo masculino, 72 anos, hipertenso, fez cirurgia gástrica com\ndiagnóstico anatomopatológico de câncer gástrico.\nAlguns meses depois apresentou acidente\nvascular cerebral, com hemiplegia. Na internação constataram-se metástases pulmonares, com\npiora respiratória progressiva e diagnóstico de broncopneumonia uma semana antes do óbito. O\npreenchimento da Declaração de Óbito desse paciente está apresentado abaixo: Parte I- Causa da\nmorte: Broncopneumonia ? 7 dias; Metástases pulmonares - meses; Câncer gástrico - meses; II -\nHipertensão arterial - anos; acidente vascular cerebral - meses. Assinale a alternativa correta em\nrelação ao caso:","options":{"A":"O Câncer gástrico foi considerado, na declaração, a causa básica do óbito.","B":"O Câncer de pulmão deveria ter sido considerado a causa básica do óbito.","C":"A Broncopneumonia foi considerada a causa básica do óbito.","D":"A Hipertensão Arterial e o Acidente Vascular Cerebral foram considerados fatores relevantes\nassociados ao óbito e por isso foram citados na parte II da declaração.","E":"A causa terminal ou imediata do óbito é a causa básica do óbito para efeitos de preenchimento\nda Declaração de Óbito."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-111337","number":"111337","sourceNumber":"111337","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Segundo estimativas do Instituto Nacional do Câncer para o ano de 2014, se\nexcluirmos os cânceres de pele não-melanoma, os\n5 cânceres mais frequentes no Brasil são, da\nmaior para a menor frequência, respectivamente:","options":{"A":"Homens: estômago, pulmão, próstata, cólon/reto, boca. Mulheres: colo de útero, maam,\ncólon/reto, pulmão, ovário.","B":"Homens: pulmão, próstata, estômago, cólon/reto, boca. Mulheres: mama, colo de útero,\ncólon/reto, pulmão, estômago.","C":"Homens: próstata, pulmão, cólon/reto, estômago, boca. Mulheres: mama, colo do útero,\ncólon/reto, pulmão, estômago.","D":"Homens: próstata, pulmão. cólon/reto, linfomas, boca. Mulheres: mama, colo de útero, pulmão.\nestômago, cólon/reto.","E":"Homens: pulmão, próstata, cólon/reto, boca, leucemia. Mulheres: colo do útero, mama,\ncólon/reto, pulmão, estômago."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-97809","number":"97809","sourceNumber":"97809","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Uma senhora com 47 anos de idade é atendida na Unidade Básica de Saúde com\nqueixa de \"caroço\" no pescoço há quatro\nmeses. À palpação da região cervical, o médico\nencontrou um nódulo de mais ou menos 4 cm, de consistência endurecida e aderido aos planos\nprofundos. Foi solicitada ultrassonografia cervical, que evidenciou nódulo tireoidiano de 4,3 cm,\ncom hipoecogenicidade, microcalcificações, ausência de halo periférico, bordas irregulares e fluxo\nintranodular. As dosagens séricas de T3, T4 e TSH foram normais. A principal hipótese diagnóstica\ne a investigação inicial são:","options":{"A":"bócio nodular tóxico; cintilografia tireoidiana.","B":"cisto do conduto tireoglosso; biópsia excisional","C":"tireoidite de Hashimoto; dosagem de anticorpos antitireoidianos.","D":"carcinoma de tireoide; biópsia por agulha fina guiada por ultrassom."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-97763","number":"97763","sourceNumber":"97763","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um paciente com 55 anos de idade vem à unidade Básica de Saúde com queixa de\nalteração do hábito intestinal. Notou afilamento das fezes há cerca de quatro meses. Refere que\nvem emagrecendo há cerca de seis meses. É tabagista (carga tabágica de 30 maços/ano) e\nhipertenso leve. Nega etilismo, diabetes ou outras doenças associadas. Relata cirurgia para\nretirada de vesícula biliar há cerca de 20 anos. Ao exame físico apresenta-se corado, hidratado,\neupneico, acianótico e anictérico. Auscultas cardíaca e pulmonar sem alterações. Abdome sem\nalterações, exceto pela cicatriz subcostal de cirurgia prévia. Exame proctológico sem alterações.\nQual a conduta correta a ser seguida?","options":{"A":"Receitar acréscimo de fibras na dieta e líquidos (2.500 ml/dia) e retorno após um mês para\nverificar se o quadro está normalizado.","B":"Receitar acréscimo de fibras na dieta e líquidos (2.500 ml/dia) e solicitar ultrassom, uma vez\nque\no exame proctológico foi negativo.","C":"O tratamento não é dietético; solicitar diretamente uma colonoscopia, pois o paciente apresenta\nsuspeita diagnóstica que justifica a realização do exame.","D":"O tratamento não é dietético; solicitar uma tomografia por ser exame menos invasivo que a\ncolonoscopia e pelo afilamento das fezes, que pode ser indicativo de estenose."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-97761","number":"97761","sourceNumber":"97761","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um homem com 55 anos de idade procura Unidade Básica de Saúde (UBS)\nqueixando-se que há três meses apresenta cor\namarelada da pele e dos \"olhos\", com coceira e\nurina muito escura. Refere piora progressiva dos sintomas há cerca de 25 dias. Sente cansaço\nprogressivo, que associa a emagrecimento de 20 kg nos últimos seis meses. Eventualmente refere\ndor em mesogástrio e nas costas, que melhora com antiácidos e jejum. História pregressa de\netilismo (destilados) há mais de 30 anos. Retorna à UBS após 45 dias da primeira consulta,\n\ntrazendo ultrassonografia abdominal que evidencia dilatação de vias biliares intra e\nextra-hepáticas.\nA hipótese diagnóstica e a conduta correta são:","options":{"A":"Hepatite alcoólica e realização de biópsia hepática transparietal.","B":"Adenocarcinoma de pâncreas e realização de colangiorressonância magnética.","C":"Adenocarcinoma de pâncreas e realização de tomografia abdominal contrastada.","D":"Pancreatite aguda e realização de colangiopancreatografia endoscópica retrógrada."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-336256","number":"336256","sourceNumber":"336256","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Mulher, 40 anos, apresenta nódulo em lobo direito da tireoide de 20 mm, cuja PAAF\nevidenciou carcinoma papilífero. Tendo em vista o diagnóstico obtido pela PAAF e de acordo com\nseus conhecimentos acerca do tema tumores diferenciados da tireoide, assinale a alternativa\ncorreta:","options":{"A":"O tratamento cirúrgico proposto é de tireoidectomia parcial por tratar-se de microcarcinoma\npapilífero seguida de radioiodoterapia, sendo indicado\no seguimento com a USG cervical.","B":"O tratamento cirúrgico proposto é tireoidectomia total devendo ser solicitado no pós operatório a\ndosagem da tireoglobulina e deve ser prescrito no pós operatório doses adequadas da levotiroxina\na fim de manter o TSH suprimido e o paciente em um quadro de hipertireoidismo subclínico\n(assintomático).","C":"O tratamento cirúrgico proposto é de tireoidectomia total e caso haja alteração no proto\noncogene RET deve ser pesquisada todos os\nfamiliares uma vez que essa alteração evidencia o\ncarcinoma papilífero familiar.","D":"O tratamento cirúrgico proposto é de tireoidectomia total sendo indicado o seguimento com a\nUSG cervical e a dosagem da calcitonina."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-337617","number":"337617","sourceNumber":"337617","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Homem, 65 anos, foi submetido a apendicectomia videolaparoscópica por apendicite\naguda com peritonite. Recebeu alta após 7\ndias. Retorna no ambulatório com resultado de exame\nanatomopatológico que mostra em adenocarcinoma invasivo mucinoso do apêndice, sem presença\nde linfonodo positivo. Nesse caso, assinale a alternativa que apresenta o tratamento ADEQUADO\ncomplementar para esse paciente.","options":{"A":"Quimioterapia seguida de observação clínica e dosagem de antígeno carcinoembrionário (CEA).","B":"Seguimento clínico, pois não teve linfonodos positivos na peça retirada na cirurgia.","C":"Hemicolectomia direita e peritoniectomia com quimioterapia citoredutora.","D":"Hemicolectomia direita."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-345699","number":"345699","sourceNumber":"345699","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O diagnóstico do carcinoma hepatocelular (CHC) deve ser realizado:","options":{"A":"Preferencialmente, por exames de imagem invasivos, tais como a ultrassonografia (US),\ntomografia computadorizada (TC) ou ressonância\nmagnética (RM), as quais também podem ser\nutilizadas para o estadiamento.","B":"Preferencialmente, por exames de imagem não invasivos, tais como a ultrassonografia (US),\ntomografia computadorizada (TC) ou ressonância magnética (RM), as quais não podem ser\nutilizadas para o estadiamento.","C":"Preferencialmente, por exames de imagem não invasivos, tais como a ultrassonografia (US),\ntomografia computadorizada (TC), mas nunca pela ressonância magnética (RM), as quais também\nsomente podem ser utilizadas para o estadiamento.","D":"Preferencialmente, por exames de imagem não invasivos, tais como a ultrassonografia (US),\ntomografia computadorizada (TC) ou ressonância magnética (RM), as quais também podem ser\nutilizadas para o estadiamento."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-345704","number":"345704","sourceNumber":"345704","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O diagnóstico anatomopatológico do carcinoma hepatocelular (CHC):","options":{"A":"Deve ser vetado para pacientes não cirróticos e para aquelas situações em que os exames de\nimagem sejam inconclusivos.","B":"Deve ser reservado para pacientes não cirróticos e para aquelas situações em que os exames\nde imagem sejam inconclusivos.","C":"Deve ser reservado para pacientes não cirróticos e não para aquelas situações em que os\nexames de imagem sejam inconclusivos.","D":"Deve ser reservado para pacientes não cirróticos e para aquelas situações em que os exames\nde imagem sejam conclusivos."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-335074","number":"335074","sourceNumber":"335074","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Um jovem de 17 anos de idade apresenta um nódulo cervical direito de 2 cm. É feita\numa punção aspirativa com agulha fina, e as células se coram positivamente para calcitonina. Os\ntestes laboratoriais revelam também cálcio elevado. O diagnóstico mais provável, nesse caso, é","options":{"A":"câncer folicular da tireoide.","B":"NEM 1.","C":"NEM 2a.","D":"NEM 2b."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-334727","number":"334727","sourceNumber":"334727","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente MCF, sexo feminino, 51 anos, refere ter percebido no banho a presença de\num nódulo em topografia cervical anterior a\nesquerda, medindo cerca de 3 cm, não doloroso e que\nse movia quando a paciente deglutia. A paciente procurou assistência médica e foi solicitado\nultrassonografia do pescoço. A ultrassonografia mostrou um nódulo de 2,5 cm, hipoecóico de\ncontornos irregulares e com microcalcificações. Foi solicitado uma punção aspirativa do nódulo que\nteve o resultado de Bethesda V. Qual das condutas abaixo não seriam adequadas para o caso\nacima?","options":{"A":"Tireoidectomia parcial com exame de congelação intraoperatória.","B":"Acompanhamento.","C":"Tireoidectomia parcial.","D":"Tireoidectomia total."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-320444","number":"320444","sourceNumber":"320444","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O câncer de pulmão é a principal causa de morte por câncer. Trata-se de uma doença\nque afeta principalmente a população mais\nidosa, com incidência de pico naqueles indivíduos entre\n65 e 85 anos. Qual a alternativa correta em relação ao rastreio desta neoplasia?","options":{"A":"O rastreio desta neoplasia está indicado para pessoas entre 50 e 80 anos com histórico de\ntabagismo atual ou cessado há no máximo 20 anos.","B":"O exame utilizado para o rastreio desta neoplasia é a Ressonância magnética de tórax com\nbaixa radiação.","C":"Paciente com cessação do tabagismo superior há 10 anos, independente da idade cronológica,\ndeve realizar rastreio para neoplasia de pulmão.","D":"A periodicidade do rastreio é anual para os pacientes com indicação.","E":"Exames alternativos para rastreio desta neoplasia incluem radiografia simples de tórax ou\ncitologia de escarro."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-320455","number":"320455","sourceNumber":"320455","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 57 anos admitido em Pronto Socorro com quadro de dor abdominal de forte\nintensidade. Realizada rotina de abdome agudo com evidência de pneumoperitônio. Ao toque retal,\ndiagnosticada lesão de reto a 5 cm de margem anal, estenosante. Submetido a laparotomia de\nurgência, com identificação de válvula ileocecal competente e perfuração de ceco. Diante dos\nachados pré e intra-operatórios, qual a melhor conduta a ser tomada durante a cirurgia de\nurgência?","options":{"A":"Colectomia total com ressecção de lesão primária e ileostomia terminal.","B":"Colectomia direita com ileostomia à Mikulicz.","C":"Colectomia total com ressecção da lesão primária e íleo reto anastomose.","D":"Rafia de ceco com ileostomia em alça à montante da lesão.","E":"Rafia de ceco com amputação abdominoperineal do reto."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-336309","number":"336309","sourceNumber":"336309","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Mulher, 50 anos, hipertensa em uso de losartana, refere aparecimento de nódulo em\nlobo esquerdo da tireóide há 2 anos, de crescimento lento, sem disfonia, disfagia e dispnéia. Nega\nsintomas de hipertireoidismo, hipotireoidismo e diabetes melitus. Nega história familiar de\nneoplasias. Tabagista há 30 anos (20 cigarros/semana) e nega etilismo. Exame físico: Oroscopia:\nausência de lesões. Laringoscopia: mobilidade normal de pregas vocais, ausência de lesões. À\npalpação cervical identificado nódulo de cerca de 4 cm, localizado em lobo esquerdo da tireoide,\nausência de linfadenomegalia cervical. Tendo em vista a anamnese e o exame físico desta\npaciente bem como seus conhecimentos acerca do tema doenças cirúrgica da tireoide é correto\nafirmar que além de USG cervical, é necessário solicitar:","options":{"A":"Dosagem do TSH. Caso a USG evidencie nódulo cístico com componente sólido associado é\nnecessário a realização da PAAF","B":"Dosagem de TSH e cintilografia. Caso a USG evidencie nódulo sólido, hipoecoico, com\nmacrocalcificações não é necessário realizar a PAAF.","C":"Dosagem de TSH. Caso a USG evidencie nódulo cístico com componente sólido associado não\nestá indicado a realização da PAAF.","D":"Dosagem de TSH e tireoglobulina. Caso a USG evidencie nódulo sólido hipoecoico, com\nmicrocalcificações e altura maior que largura estamos diante de características ultrassonográficas\nde um nódulo benigno."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-304860","number":"304860","sourceNumber":"304860","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Mulher, 35 anos, assintomática do ponto de vista cervical, realizou ultrassonografia de\nmama e teve seu pescoço rastreado no\nexame. Encontrou-se nódulo sólido em lobo esquerdo de\ntireoide, isoecoico, com halo hipoecoico bem definido, 0,9 cm em seu maior diâmetro, TI-RADS® 3,\nsem outros achados suspeitos ou informações de risco. Dosagem de TSH de 1,2. A melhor conduta\nserá:","options":{"A":"Indicar PAAF, dirigida por ultrassom.","B":"Indicar observação clínica e ultrassonográfica.","C":"Indicar lobectomia esquerda e biópsia de congelação.","D":"Indicar tireoidectomia total."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-257340","number":"257340","sourceNumber":"257340","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Homem de 57 anos realiza exame periódico de saúde com seu clínico. É portador de\nHipertensão Arterial Sistêmica (HAS) há 22 anos e diabetes mellitus tipo 2 há 2 anos. Faz uso\nregular de anlodipino 10mg, 1 vez ao dia, e metformina 1000mg, 1 vez ao dia. Não possui queixas\nou outras comorbidades. O exame físico não apresenta anormalidades. Traz resultado de pesquisa\nde sangue oculto nas fezes, que resultou positivo em 1 de 3 amostras. Após a correta interpretação\ndo resultado da pesquisa de sangue oculto nas fezes apresentado por esse paciente, a conduta\nsequencial MAIS ADEQUADA é a de:","options":{"A":"Realizar colonoscopia.","B":"Realizar endoscopia digestiva alta.","C":"Repetir a pesquisa de sangue oculto nas fezes.","D":"Solicitar a cinética do ferro."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-287844","number":"287844","sourceNumber":"287844","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Assinalar a alternativa que preenche a lacuna abaixo CORRETAMENTE: A punção\naspirativa por agulha fina (PAAF) é\nessencial para definição diagnóstica de pacientes com nódulos\nde tireoide e, consequentemente, definir a necessidade de abordagem cirúrgica. A classificação\n\né a que padroniza a terminologia usada para descrever os achados do exame.","options":{"A":"BI-RADS","B":"Bethesda","C":"Bosniak","D":"TNM","E":"ASA"},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-287849","number":"287849","sourceNumber":"287849","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Em relação à intervenção cirúrgica no câncer de pâncreas, assinalar a alternativa\nCORRETA:","options":{"A":"Pancreatectomia distal é sinônimo de cirurgia de Whipple.","B":"A cirurgia de Whipple é a técnica mais frequentemente utilizada para remover o câncer de\ncabeça do pâncreas.","C":"A técnica mais frequentemente utilizada é a pancreatectomia total.","D":"A duodenopancreatectomia é uma técnica raramente utilizada.","E":"A cirurgia de Whipple retira somente a parte distal do pâncreas."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-257371","number":"257371","sourceNumber":"257371","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Analise a proposição e a razão apresentadas. Proposição: Sinal de Chvostek pode ser\nencontrado no pós-operatório de uma tireoidectomia total PORQUE Razão: A hipercalcemia dessa\ncirurgia pode ser complicação. Com base na análise realizada, DEVE-SE concluir que:","options":{"A":"A proposição e a razão são verdadeiras e a razão é realmente a causa da proposição","B":"A proposição e a razão são verdadeiras, mas a razão não é a causa da proposição.","C":"A proposição é falsa, mas a razão é verdadeira.","D":"A proposição é verdadeira e a razão é falsa."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-257377","number":"257377","sourceNumber":"257377","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Sobre as neoplasias colorretais, assinale a alternativa que apresenta a associação\nCORRETA:","options":{"A":"Os pólipos da síndrome de Peutz-Jeghers estão associados a neoplasia de canal anal\nespecificamente.","B":"A polipose adenomatosa familiar está associada a hipertrofia congênita do epitélio pigmentar\nretiniano.","C":"Os pólipos juvenis são pólipos inflamatórios e constituem os pólipos mais comuns em crianças,\ngeralmente com apresentação solitária, e não se associam a potencial maligno.","D":"A síndrome de Turcot está associada a neoplasia primária do sistema sanguíneo e polipose\ncolorretal."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-260708","number":"260708","sourceNumber":"260708","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Sobre as lesões cáusticas do trato gastrointetinal é correto afirmar:","options":{"A":"A mortalidade destas lesões é relativamente baixa (<5%).","B":"A ocorrência de carcinoma epidermóide esofágico não se modifica nestes pacientes.","C":"O prognóstico do carcinoma esofágico associado à ingestão de cáusticos é pior que o do\nesporádico.","D":"A complicação tardia mais frequente é a estenose antro-pilórica.","E":"Hemorragia digestiva alta maciça é um evento comum."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-246731","number":"246731","sourceNumber":"246731","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"No rastreio dos tumores de colón e reto, na população geral, a conduta mais correta,\ndentre as abaixo, é:","options":{"A":"Hemograma completo e dosagem de CEA (antígeno carcinoembrionário) anualmente.","B":"Hemograma completo, dosagem de CEA (antígeno carcinoembrionário) e pesquisa de sangue\noculto nas fezes a cada 2 anos.","C":"Dosagem de CEA anualmente.","D":"Pesquisa de sangue oculto nas fezes a cada 5 anos.","E":"Colonoscopia a cada 10 anos entre 50 e 75 anos de idade."},"answer":"E","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-255635","number":"255635","sourceNumber":"255635","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Enquanto realizava o exame da língua de Dona Judith, Dr. Wagner, médico\nacupunturista, observou um nódulo em sua região cervical anterior. Quanto à investigação e\ndiagnóstico do nódulo solitário da tireóide, MARQUE A CORRETA:","options":{"A":"Após coleta da história e exame físico, o TSH e T4 livre devem ser pedidos.","B":"O achado de uma lesão cística pode ser tranquilizante, mas este representa uma pequena\nminoria entre os nódulos tireóideos.","C":"As lesões nas quais o resultado da biópsia da punção aspirativa por agulha fina for\npersistentemente não diagnóstico devem ser\nacompanhadas por ultrassonografia a cada 6 meses.","D":"O carcinoma papilífero é a mais comum das neoplasias da tireóide e está geralmente associado\na um prognóstico ruim."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-246375","number":"246375","sourceNumber":"246375","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente 36 anos, sexo feminino, procura o ambulatório de cirurgia de cabeça e\npescoço com relato de durante consulta de\nrotina ter sido identificado nódulo em lobo esquerdo da\ntireoide. Nega disfonia, dispneia e disfagia. Nega história familiar de doença tireoidiana e\nirradiação\ndo pescoço durante a infância. Nega diabetes melitus e hipertensão arterial sistêmica. Nega\ntabagismo e etilismo. Ao exame físico presença de nódulo de cerca de 2 cm em lobo esquerdo da\ntireoide, sem linfonodos cervicais palpáveis. Videolaparoscopia: cordas vocais móveis. Realizado\nUSG cervical com identificação de nódulo de cerca de 2 cm localizado em lobo esquerdo, de\ncontornos irregulares, microcalcificações, circulação central e halo incompleto. PAAF é sugestivo de\nneoplasia maligna (Bethesda VI). Realizado tireoidismo total sendo que o histopatológico\nevidenciou Carcinoma medular de tireoide. Sobre o carcinoma medular é incorreto afirmar:","options":{"A":"A Síndrome NEN 2 A é caracterizada pela presença de carcinoma medular da tireoide, doença\ndas paratireoides e feocromocitoma.","B":"A disseminação metastática do carcinoma medular da tireoide se dá tanto por via linfática\nlinfonodal como por via hematogênica.","C":"O carcinoma medular da tireoide é uma neoplasia de diferenciação intermediária e proveniente\ndas células C ou parafoliculares.","D":"A síndrome NEN 2 B é caracterizada pela presença de feocromocitoma, doença das\nparatireoides e carcinoma medular da tireodie."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-246376","number":"246376","sourceNumber":"246376","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente 44 anos, sexo masculino, diabético, procura o ambulatório de Cirurgia de\nCabeça e Pescoço com relato de bócio há 5\nanos sendo que nos últimos 30 dias apresenta queixa\nde dispneia e disfagia devido ao crescimento rápido da lesão. Nega disfonia. Relata história\nfamiliar\nde neoplasia de tireoide (irmão com diagnóstico de carcinoma papilifero e irmã com relato de\nnódulo tireoidiano em investigação). Ao exame apresenta aumento difuso da glândula tireoide e\nmassa linfonodal à direita que ocupa níveis II, III e IV. Videolaringoscopia evidência pregas vocais\nmóveis e sem lesões. Realizado USG cervical e tomografia de pescoço. PAAF realizada é\nsugestiva de neoplasia maligna (Bethesda VI). Analisando o caso descrito assinale a alternativa\ncorreta em relação em relação às doenças neoplásicas da tireoide.","options":{"A":"O carcinoma folicular de tireoide é um tumor cujo padrão de disseminação metastática é\npredominantemente linfática.","B":"O carcinoma insular de tireoide é uma neoplasia de diferenciação intermediaria , com\nprognóstico melhor que o carcinoma anaplásico.","C":"O carcinoma medular de tireoide é uma neoplasia bem diferenciada da tireoide, cujo seguimento\nse faz com a dosagem de calcitonina.","D":"O carcinoma anaplásico é um tumor indiferenciado, de prognóstico reservado, derivado das\ncélulas foliculares"},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-227105","number":"227105","sourceNumber":"227105","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente masculino, 70 anos, apresenta adenocarcinoma tipo intestinal de Lauren no\nantro gástrico. No exame físico não demonstra presença de metástases à distância. A tomografia\nde abdômen não apresentou ascite e nem suspeita de lesão hepática. Considerando o caso\ndescrito, a cirurgia MAIS ADEQUADA a ser realizada seria a:","options":{"A":"Gastrectomia total + linfadenectomia D2.","B":"Gastrectomia total + linfadenectomia de ao menos 15 linfonodos perigástricos.","C":"Gastrectomia subtotal + linfadenectomia D2.","D":"Gastroenteroanastomose paliativa."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-227111","number":"227111","sourceNumber":"227111","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 70 anos admitido com quadro suspeito de neoplasia da cabeça do\npâncreas confirmado na tomografia de abdômen. No\nexame físico desse paciente, é CORRETO\nencontrar:","options":{"A":"Sinal courvoisier e vascolejo.","B":"Icterícia obstrutiva e sinal de Kernig.","C":"Sinal do vascolejo e transaminases acima de 2000 unidades.","D":"Sinal de Grey Turner e icterícia padrão obstrutivo."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-232147","number":"232147","sourceNumber":"232147","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Sobre o câncer gástrico, avalie as seguintes afirmações: I. Mais de 95% dos tumores\nmalignos do estômago são adenocarcinomas; II. A constipação está presente em 10% dos\npacientes; III. 40% dos pacientes apresentam sinais de anemia crônica; IV. A presença do nódulo\nde Virchow demonstra doença avançada e é caracterizado pela presença de lesão em região\numbilical; Assinale a opção que contém as afirmativas corretas:","options":{"A":"I e III.","B":"I e II.","C":"I, II e III.","D":"I, II e IV.","E":"II, III e IV."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-232150","number":"232150","sourceNumber":"232150","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O Antígeno Cárcino-embrionário (CEA) é um marcador tumoral utilizado no câncer\ncolorretal. Sobre o mesmo, assinale a alternativa incorreta:","options":{"A":"Sua elevação no pós-operatório é patognomônica para a presença de mestástase hepática.","B":"A maioria dos carcinomas precoces está associada a níveis normais de CEA.","C":"Elevações do CEA têm sido encontradas em doenças não malignas do cólon.","D":"Tabagismo é causa de elevação na sua dosagem sanguínea.","E":"Seu aumento nesses pacientes deve impor a realização de PET-Scan."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-243031","number":"243031","sourceNumber":"243031","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Quando suspeitar de Síndrome de Veia Cava Superior, EXCETO:","options":{"A":"dispneia progressiva.","B":"ataxia.","C":"edema cervicofacial.","D":"circulação colateral toracobraquial.","E":"pletora facial."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-232152","number":"232152","sourceNumber":"232152","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Em relação ao câncer de testículo, assinale ( V ) para verdadeiro e ( F ) para falso nas\nafirmações abaixo. ( ) A grande maioria dos tumores testiculares representa tumores de células\ngerminativas. ( ) Geralmente, os pacientes apresentam quadro de massa dolorosa e com sinais\ninflamatórios. ( ) Qualquer massa intratesticular sólida deve, provavelmente, representar um tumor\nde células germinativas malignas e será tratada como tal, se não houver forte suspeita do contrário.\n( ) Devem ser solicitados beta-hCG, Alfa-fetoproteína e LDH. De acordo com a característica de\ncada afirmação, assinale a alternativa correta:","options":{"A":"V, F, F, V","B":"V, F, V, V","C":"F, V, F, V","D":"V, F, F, F","E":"V, V, V, F"},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-227304","number":"227304","sourceNumber":"227304","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Paciente de 60 anos, classe social baixa, tabagista 60 anos/maço, 60kg, previamente\nhígida, relata início de quadro de\nepigastralgia atípica, sem irradiação, associado a hiporexia,\nplenitude pós prandial e anemia de difícil controle, de início há cerca de 06 meses, com\nemagrecimento de 06 kg. Nega relação da dor com atividade física. Ao exame, hipocorada,\nemagrecida, sem massas ou visceromegalias palpáveis, restante do exame físico normal. Diante do\nquadro clínico e principal suspeita diagnóstica, qual o exame complementar inicial a ser\nsolicitado?","options":{"A":"Tomografia Computadorizada de Abdome.","B":"Ultrassonografia de Abdome.","C":"Endoscopia Digestiva Alta.","D":"Raio X de abdome agudo."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-246780","number":"246780","sourceNumber":"246780","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"A suscetibilidade hereditária ao câncer pode ser claramente observada nas diversas\nsíndromes genéticas, nas quais os fatores genéticos desempenham um papel central. Sobre a\nsíndrome do Câncer colorretal hereditário não poliposo (HNPCC) ou síndrome de Lynch é\nCORRETO afirmar que:","options":{"A":"Por se tratar de câncer colorretal não relacionado a polipose, a colonoscopia de rastreio não é,\ncomo via de regra, recomendada de forma rotineira.","B":"Alguns pacientes com HNPCC podem apresentar associação com tumores do SNC, na\nchamada síndrome de Gardner.","C":"o tumor extracólico mais comum na Síndrome de Lynch é o câncer de ovário.","D":"trata-se de uma síndrome genética com herança autossômica recessiva, associada a mutações\nem, pelo menos, cinco genes de reparo de\nDNA: MSH2, MSH6, MLH1, PMS1 e PMS2","E":"Dentre os tumores colorretais com caráter hereditário, a Síndrome de Lynch é a mais comum,\nrespondendo por cerca de 3 a 5% do total das neoplasias colorretais."},"answer":"E","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-227306","number":"227306","sourceNumber":"227306","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Marque qual letra representa a Lobectomia Direita conforme a figura (área escura é a\nárea que será ressecada):","options":{"A":"A.","B":"B.","C":"C.","D":"D."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":["question_bank/media/medcurso/med-cirurgia-med-cir-06/227306.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-246783","number":"246783","sourceNumber":"246783","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O adenocarcinoma de pâncreas tem na ressecção cirúrgica como único tratamento com\nintuito curativo. No entanto, no momento do diagnóstico pequena parcela torna-se candidata ao\nprocedimento cirúrgico. Assim, analise os achados descritos abaixo e assinale aquele que NÃO\nCONTRA-INDICA a cirurgia curativa:","options":{"A":"Lesão de 4 cm com invasão da parede posterior do antro gástrico por contiguidade","B":"Nódulo de 0,5cm sugestivo de implante no peritoneo do diafragma","C":"Lesão de 3cm com acometimento circunferencial da artéria mesentérica superior","D":"Lesão de 2cm em paciente com nódulo supraclavicular esquerdo endurecido e fixo","E":"tumor de 2cm limitado ao pâncreas em paciente com doença coronariana grave e sinais de ICC\nlimitante"},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-246785","number":"246785","sourceNumber":"246785","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"O intestino delgado representa cerca de 75% do comprimento e 90% da área de\nsuperfície do trato digestivo e, de forma contraditória, responde por apenas 1% das neoplasias\nmalignas do sistema digestivo. Sobre o câncer do intestino delgado, pode-se afirmar:","options":{"A":"O adenocarcinoma do instestino delgado ocorre mais frequentemente na porção terminal do íleo\ne geralmente está associado à doença de Crohn.","B":"O GIST (tumor estromal gastrointestinal) se localiza mais fr//equentemente no duodeno. Por sua\ndisseminação ser hematogênica a linfadenectomia é prescindível durante a ressecção cirúrgica.","C":"Os tumores carcinóides do delgado se localizam de forma mais frequente no íleo terminal e\nraramente apresenta metástases quando comparamos com outros sítios primários.","D":"As manifestações exuberantes da síndrome carcinóide são frequentes nos tumores localizados\nno intestino médio acometendo mais da metade dos\npacientes com tumores carcinoides desta\nlocalização.","E":"Devido ao caráter indolente/crescimento lento dos tumores carcinóides, a ressecção ampla do\ntumor primário é preconizada mesmo nos pacientes já com doença metastática."},"answer":"E","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-246787","number":"246787","sourceNumber":"246787","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"São achados no exame físico do paciente com adenocarcinoma pancreático\ncompatíveis com doença avançada, exceto:","options":{"A":"Prateleira de Blumer","B":"Nódulo de Irish","C":"sinal de Troisier","D":"nódulo da Irmã Maria José","E":"sinal de Fox"},"answer":"E","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-243056","number":"243056","sourceNumber":"243056","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Qual a conduta mais adequada diante de um paciente portador de adenocarcinoma de\nreto a 7 cm da borda anal cujos exames de estadiamento (tomografia de tórax e abdome e\nressonância magnética de pelve) mostraram tratar-se de uma lesão estádio clínico T3N0M0?","options":{"A":"Radioquimioterapia neoadjuvante seguido de retossigmoidectomia e anastomose colorretal.","B":"Retossigmoidectomia com anastomose colorretal seguido de radioquimioterapia adjuvante.","C":"Amputação abdominoperineal do reto (cirurgia de Miles) seguido de quimioterapia adjuvante.","D":"Quimioterapia neoadjuvante seguido de retossigmoidectomia com colostomia terminal (cirurgia\nde Hartmann).","E":"Radioterapia neoadjuvante seguido de amputação abdominoperineal do reto (cirurgia de Miles)."},"answer":"A","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-243057","number":"243057","sourceNumber":"243057","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Qual a conduta mais adequada em um paciente com performance status ECOG-PS1\nportador de carcinoma epidermoide de\nesôfago médio cujos exames de estadiamento (tomografia\nde tórax e abdome) não evidenciaram doença metastática ? estádio clinico T3N0M0:","options":{"A":"esofagectomia seguido de quimioterapia adjuvante.","B":"radioquimioterapia neoadjuvante seguido de esofagectomia.","C":"radioterapia neoadjuvante seguido de esofagectomia e quimioterapia adjuvante.","D":"radioquimioterapia exclusiva sem esofagectomia.","E":"esofagectomia exclusiva sem radioterapia ou quimioterapia."},"answer":"B","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-220289","number":"220289","sourceNumber":"220289","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Homem de 60 anos se queixa de urina ?cor de coca-cola? e fezes ?cor de palha?\n(aspecto de massa de vidraceiro) há 10 dias,\nalém de prurido generalizado. Estava em uso de\nnaproxeno por causa de epigastralgia há 3 semanas. Ao exame físico, o paciente estava\nhipocorado e ictérico. A vesícula biliar era palpável, distendida, compressível e indolor, abaixo do\nrebordo costal direito. Sobre o caso descrito, assinale a alternativa que apresenta uma hipótese\netiológica CORRETA:","options":{"A":"Anemia hemolítica autoimune.","B":"Síndrome de Crigler-Najjar tipo II.","C":"Adenocarcinoma pancreático.","D":"Hepatite medicamentosa."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-196732","number":"196732","sourceNumber":"196732","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Os pólipos colônicos mais comuns mostrando células com desnaturação são:","options":{"A":"Adenomatosos.","B":"Esquistossomóticos.","C":"Hiperplásicos.","D":"Vilosos."},"answer":"C","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-196745","number":"196745","sourceNumber":"196745","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"A biópsia com agulha fina (pequeno calibre 23 à 27) é uma ferramenta valiosa e de\ngrande custo/benefício, tornando-se uma modalidade chave na avaliação de pacientes com:","options":{"A":"Derrame Pleural.","B":"Tuberculose Peritoneal.","C":"Carcinomatose Peritoneal.","D":"Nódulos Tireoidianos."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-06-199518","number":"199518","sourceNumber":"199518","collectionBlock":"med:med-cirurgia-med-cir-06","collectionLabel":"MED · MED CIR 06","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 06","subtopic":"","stem":"Homem, 68 anos, queixa de empachamento e plenitude pós-prandial há 5 meses, com\npiora no último mês, quando passou a se alimentar de dieta líquida, pois vomita ao ingerir sólidos.\nNo exame físico: não apresenta linfonodos periféricos ou massas abdominais palpáveis. Presença\nde prateleira de Blumer no toque retal e sinal de piparote positivo. A endoscopia mostrou uma lesão\nulceroinfiltrativa da região antro-pilórica, cuja biópsia revelou adenocarcinoma. US: não evidenciou\nmetástases hepáticas no abdômen. O estadiamento oncológico MAIS PROVÁVEL desse paciente\né o:","options":{"A":"I.","B":"II.","C":"III.","D":"IV."},"answer":"D","source":"Cirurgia/MED CIR 06/MED CIR 06.txt","sourceLabel":"MED · MED CIR 06","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 06","MED"],"answerSource":"explicit","commentDeferred":true}]};
